def H(s):
    if isinstance(s,str): s=s.encode()
    return base64.b64encode(hashlib.sha256(s).digest()).decode()
targets={
 "20261008215017.sql":"LC9R5J06WIvGLIMGhg75kkIptnS5DcGnnAYlhyfyT08=",
 "20261008215017_foo.sql":"wZscl2TLDEF6+xqMO/EI5rlZg/zbX0Lbw0w1ck9sA50=",
 "20261008215017_add-users.sql":"4HWiZilxCB/gEZ4HmSFRAjoNvJRdEFuqn3Ydy6KHfRQ=",
