}
for name,t in targets.items():
    print(name,t)
    # generate combos of components
    stem=name[:-4]
    ver=name.split("_")[0]
    desc=stem[len(ver)+1:] if "_" in stem else ""
    comps={"name":name,"stem":stem,"ver":ver,"desc":desc,"empty":"","nl":"\n","sql":".sql"}
    candidates=[]
    # single
    for k,v in comps.items(): candidates.append((k,v))
    # concatenations up to 3 components with separators
    seps=[""," ","  ","\n","_","-","/","h1:"]
    # try specific patterns mimicking dirhash: write hash of file bytes in hex then etc
    eh=hashlib.sha256(b"").hexdigest()
    candidates += [
        ("hexempty+2sp+name+nl", eh+"  "+name+"\n"),
        ("hexempty+sp+name", eh+" "+name),
        ("name+hexempty", name+eh),
        ("hexempty+name", eh+name),
        ("ver+desc", ver+desc),
        ("desc+ver", desc+ver),
    ]
    for a,b in itertools.permutations(["name","stem","ver","desc"],2):
        for sep in seps:
            candidates.append((f"{a}{sep!r}{b}", comps[a]+sep+comps[b]))
