# Try hash of bytes of name without extension etc already.
# Try Go dirhash default hash1 function for single file line: overall file hash in atlas may be hash of content using sha256 but with file name written as ??? Could be they hash using fnv? but b64 len 44 => 32 bytes sha256.
# Brute substrings from name: any substring whose sha256 matches?
for name,t in targets.items():
    found=False
    for i in range(len(name)):
        for j in range(i+1,len(name)+1):
            if H(name[i:j])==t:
                print("substr match",name, repr(name[i:j])); found=True
    if not found: print("no substr",name)
PY"}

