import re, os
from dataclasses import dataclass, field

class HCLError(Exception):
    """Error whose string is already in the form printed after 'Error: '."""
    pass

@dataclass
class Range:
    filename: str = ""
    line: int = 1
    col: int = 1
    end_line: int = 1
    end_col: int = 1
    start: int = 0
    end: int = 0
    def __str__(self):
        fn = self.filename
        if self.line == self.end_line:
            return f"{fn}:{self.line},{self.col}-{self.end_col}"
        return f"{fn}:{self.line},{self.col}-{self.end_line},{self.end_col}"

def diag(rng, summary, detail):
    if rng is None:
        return HCLError(f"{summary}; {detail}")
    return HCLError(f"{rng}: {summary}; {detail}")

@dataclass
class Token:
    type: str
    text: str
    rng: Range
    # For STRING tokens: parsed segments list of ('lit', str) / ('expr', source_range_text)
    segments: list = None
    heredoc: bool = False
    indent_heredoc: bool = False

TOKEN_NAMES = {
    '{': 'OBRACE', '}': 'CBRACE', '[': 'OBRACK', ']': 'CBRACK', '(': 'OPAREN', ')': 'CPAREN',
}

def _is_ident_start(ch):
    return ch.isalpha() or ch == '_'
def _is_ident(ch):
    return ch.isalnum() or ch in ('_', '-')

class Scanner:
    def __init__(self, src, filename=""):
        self.src = src
        self.filename = filename
        self.n = len(src)
        self.i = 0
        self.line = 1
        self.col = 1
    def rng(self, sl, sc, so):
        return Range(self.filename, sl, sc, self.line, self.col, so, self.i)
    def adv(self, k=1):
        for _ in range(k):
            if self.i >= self.n: return
            if self.src[self.i] == '\n':
                self.line += 1; self.col = 1
            else:
                self.col += 1
            self.i += 1
    def peek(self, off=0):
        j = self.i + off
        return self.src[j] if j < self.n else ''

    def tokenize(self):
        toks = []
        while self.i < self.n:
            sl, sc, so = self.line, self.col, self.i
            ch = self.src[self.i]
            if ch in ' \t\r':
                self.adv(); continue
            if ch == '\n':
                self.adv(); toks.append(Token('NEWLINE', '\n', self.rng(sl, sc, so))); continue
            if ch == '#' or (ch == '/' and self.peek(1) == '/'):
                start = self.i
                while self.i < self.n and self.src[self.i] != '\n': self.adv()
                toks.append(Token('COMMENT', self.src[start:self.i], self.rng(sl, sc, so))); continue
            if ch == '/' and self.peek(1) == '*':
                start = self.i; self.adv(2)
                while self.i < self.n and not (self.src[self.i] == '*' and self.peek(1) == '/'): self.adv()
                if self.i < self.n: self.adv(2)
                toks.append(Token('COMMENT', self.src[start:self.i], self.rng(sl, sc, so))); continue
            if ch == '"':
                toks.append(self.scan_string()); continue
            if ch == '<' and self.peek(1) == '<':
                # possible heredoc <<IDENT or <<-IDENT followed by newline
                m = re.match(r'<<(-?)([A-Za-z_][A-Za-z0-9_]*)\n', self.src[self.i:])
                if m:
                    toks.append(self.scan_heredoc(m)); continue
                # else fall through as operator tokens
            if _is_ident_start(ch):
                start = self.i
                while self.i < self.n and _is_ident(self.src[self.i]): self.adv()
                toks.append(Token('IDENT', self.src[start:self.i], self.rng(sl, sc, so))); continue
            if ch.isdigit():
                start = self.i
                # HCL number: digits [.digits] [(e|E)[+-]digits]
                while self.i < self.n and self.src[self.i].isdigit(): self.adv()
                if self.i < self.n and self.src[self.i] == '.' and self.peek(1).isdigit():
                    self.adv()
                    while self.i < self.n and self.src[self.i].isdigit(): self.adv()
                if self.i < self.n and self.src[self.i] in 'eE':
                    j = self.i + 1
                    if j < self.n and self.src[j] in '+-': j += 1
                    if j < self.n and self.src[j].isdigit():
                        while self.i < j: self.adv()
                        while self.i < self.n and self.src[self.i].isdigit(): self.adv()
                toks.append(Token('NUMBER', self.src[start:self.i], self.rng(sl, sc, so))); continue
            three = self.src[self.i:self.i+3]
            two = self.src[self.i:self.i+2]
            if three == '...':
                self.adv(3); toks.append(Token('ELLIPSIS', three, self.rng(sl, sc, so))); continue
            if two in ('==','!=','<=','>=','&&','||','=>','.*','[*'):
                typ = {'==':'EQ','!=':'NE','<=':'LE','>=':'GE','&&':'AND','||':'OR','=>':'FATARROW','.*':'DOTSPLAT','[*':'SPLATOPEN'}[two]
                self.adv(2); toks.append(Token(typ, two, self.rng(sl, sc, so))); continue
            single = {'{':'OBRACE','}':'CBRACE','[':'OBRACK',']':'CBRACK','(':'OPAREN',')':'CPAREN','.':'DOT',',':'COMMA','=':'ASSIGN','!':'BANG','<':'LT','>':'GT','+':'PLUS','-':'MINUS','*':'STAR','/':'SLASH','%':'PERCENT','?':'QUESTION',':':'COLON'}
            if ch in single:
                self.adv(); toks.append(Token(single[ch], ch, self.rng(sl, sc, so))); continue
            self.adv(); toks.append(Token('INVALID', ch, self.rng(sl, sc, so))); continue
        toks.append(Token('EOF', '', Range(self.filename, self.line, self.col, self.line, self.col, self.i, self.i)))
        return toks

    def scan_string(self):
        sl, sc, so = self.line, self.col, self.i
        start = self.i
        self.adv()  # opening quote
        segments = []
        lit = []
        def flush():
            if lit: segments.append(('lit', ''.join(lit))); lit.clear()
        while self.i < self.n:
            ch = self.src[self.i]
            if ch == '"':
                self.adv(); break
            if ch == '\n':
                break  # unterminated; let parser handle roughly
            if ch == '\\' and self.i + 1 < self.n:
                lit.append(self.src[self.i:self.i+2]); self.adv(2); continue
            if ch == '$' and self.peek(1) == '$' and self.peek(2) == '{':
                lit.append('${'); self.adv(3); continue
            if ch == '%' and self.peek(1) == '%' and self.peek(2) == '{':
                lit.append('%{'); self.adv(3); continue
            if (ch == '$' and self.peek(1) == '{'):
                flush()
                # capture until matching brace
                self.adv(2); depth = 1; estart = self.i
                erng_start = (self.line, self.col, self.i)
                while self.i < self.n and depth:
                    c = self.src[self.i]
                    if c == '"':
                        # skip nested string roughly
                        self.adv()
                        while self.i < self.n and self.src[self.i] != '"':
                            if self.src[self.i] == '\\': self.adv()
                            if self.i < self.n: self.adv()
                        if self.i < self.n: self.adv()
                        continue
                    if c == '{': depth += 1
                    elif c == '}':
                        depth -= 1
                        if depth == 0: break
                    self.adv()
                src_text = self.src[estart:self.i]
                segments.append(('expr', src_text, erng_start))
                if self.i < self.n: self.adv()  # }
                continue
            if (ch == '%' and self.peek(1) == '{'):
                # template directive: capture whole as segment
                flush()
                self.adv(2); dstart = self.i; erng_start=(self.line,self.col,self.i)
                while self.i < self.n and self.src[self.i] != '}': self.adv()
                segments.append(('directive', self.src[dstart:self.i].strip(), erng_start))
                if self.i < self.n: self.adv()
                continue
            lit.append(ch); self.adv()
        flush()
        t = Token('STRING', self.src[start:self.i], self.rng(sl, sc, so), segments=segments)
        return t

    def scan_heredoc(self, m):
        sl, sc, so = self.line, self.col, self.i
        start = self.i
        marker = m.group(2); indented = bool(m.group(1))
        # consume first line
        while self.i < self.n and self.src[self.i] != '\n': self.adv()
        if self.i < self.n: self.adv()
        body_start = self.i
        lines = []
        while self.i < self.n:
            ls = self.i
            while self.i < self.n and self.src[self.i] != '\n': self.adv()
            line = self.src[ls:self.i]
            if line.strip() == marker:
                body = lines
                if self.i < self.n: self.adv()
                t = Token('STRING', self.src[start:self.i], self.rng(sl, sc, so), segments=[('lit_raw', body)], heredoc=True, indent_heredoc=indented)
                return t
            lines.append(line)
            if self.i < self.n: self.adv()
        t = Token('STRING', self.src[start:self.i], self.rng(sl, sc, so), segments=[('lit_raw', lines)], heredoc=True, indent_heredoc=indented)
        return t

def tokenize(src, filename=""):
    return Scanner(src, filename).tokenize()

# --------------- AST ---------------
@dataclass
class Node:
    rng: Range = None
@dataclass
class Literal(Node):
    value: object = None
    kind: str = ''  # number, string, bool, null
    raw: str = ''
    token: Token = None
@dataclass
class Template(Node):
    parts: list = field(default_factory=list)  # str or Node or ('directive', str)
    token: Token = None
@dataclass
class Traversal(Node):
