            # We look ahead skipping comments only (not newlines)
            j = self.pos
            while self.toks[j].type == 'COMMENT': j += 1
            nt = self.toks[j]
            sl = (nt.type not in ('NEWLINE', 'CBRACE', 'EOF') and nt.rng.line == brace.rng.line)
            inner = self.parse_body(top=False, single_line=sl, open_line=brace.rng.line)
            inner.filename = self.filename; inner.src = self.src
            if self.cur().type == 'CBRACE': self.advance()
            blk = Block(name_tok.text, labels, lrngs, inner, name_tok.rng, name_tok.rng, brace.rng)
            body.blocks.append(blk)
            first = False
            # after block, expect newline / } / eof / comment
            nt2 = self.cur()
            if nt2.type not in ('NEWLINE', 'EOF', 'CBRACE', 'COMMENT'):
                # e.g. single line extra tokens handled by single_line of parent? block definitions must end with newline
                if single_line:
                    raise diag(nt2.rng, "Invalid single-argument block definition", "A single-line block definition must end with a closing brace immediately after its single argument definition.")
                raise diag(nt2.rng, "Missing newline after block definition", "A block definition must end with a newline.")
            if single_line and self.cur().type == 'NEWLINE':
                single_line = False
        body.filename = self.filename; body.src = self.src
        return body

    # Expression grammar
    def parse_expr(self):
        return self.parse_conditional()
    def parse_conditional(self):
        left = self.parse_or()
        if self.cur().type == 'QUESTION':
            self.advance(); self.skip_newlines()
            yes = self.parse_expr()
            if self.cur().type != 'COLON':
                raise diag(self.cur().rng, "Missing conditional separator", "Expected a colon (\":\") to mark the beginning of the false result of the conditional expression.")
            self.advance(); self.skip_newlines()
            no = self.parse_expr()
            return Conditional(left.rng, left, yes, no)
        return left
    def _binlevel(self, sub, ops):
        left = sub()
        while self.cur().type in ops:
            op = self.advance(); self.skip_newlines()
            right = sub()
            left = Binary(left.rng, ops[op.type] if isinstance(ops, dict) else op.text, left, right)
        return left
    def parse_or(self):
        return self._binlevel(self.parse_and, {'OR': '||'})
    def parse_and(self):
        return self._binlevel(self.parse_eq, {'AND': '&&'})
    def parse_eq(self):
        return self._binlevel(self.parse_cmp, {'EQ': '==', 'NE': '!='})
    def parse_cmp(self):
        return self._binlevel(self.parse_add, {'LT': '<', 'LE': '<=', 'GT': '>', 'GE': '>='})
    def parse_add(self):
        return self._binlevel(self.parse_mul, {'PLUS': '+', 'MINUS': '-'})
    def parse_mul(self):
        return self._binlevel(self.parse_unary, {'STAR': '*', 'SLASH': '/', 'PERCENT': '%'})
    def parse_unary(self):
        if self.cur().type in ('BANG', 'MINUS'):
            op = self.advance()
            e = self.parse_unary()
            return Unary(op.rng, op.text, e)
        return self.parse_postfix()

    def parse_postfix(self):
        node = self.parse_primary()
        # traversals / index / splat applied to any node; for Traversal node, parse_primary already consumed them.
        while True:
            if self.cur().type == 'DOT':
                dot = self.advance()
                if self.cur().type == 'NUMBER':
                    nt = self.advance(); key = int(nt.text)
                    node = Index(node.rng, node, Literal(nt.rng, key, 'number', nt.text))
                elif self.cur().type == 'IDENT':
                    nt = self.advance()
                    if isinstance(node, Traversal):
                        rng = Range(self.filename, dot.rng.line, dot.rng.col, nt.rng.end_line, nt.rng.end_col, dot.rng.start, nt.rng.end)
                        node.parts.append(nt.text); node.step_ranges.append(rng)
                    else:
                        node = Index(node.rng, node, Literal(nt.rng, nt.text, 'attrname', nt.text))
                elif self.cur().type == 'STAR':
                    self.advance(); node = Splat(node.rng, node, [])
                    # consume .attr chains into rest
                    while self.cur().type == 'DOT':
                        self.advance()
                        if self.cur().type == 'IDENT':
                            node.rest.append(self.advance().text)
                        else: break
                else:
                    raise diag(self.cur().rng, "Invalid attribute name", "An attribute name is required after a dot.")
            elif self.cur().type == 'OBRACK' or self.cur().type == 'SPLATOPEN':
                if self.cur().type == 'SPLATOPEN':
                    self.advance()
                    if self.cur().type == 'CBRACK': self.advance()
                    node = Splat(node.rng, node, [])
                    while self.cur().type == 'DOT':
                        self.advance()
                        if self.cur().type == 'IDENT': node.rest.append(self.advance().text)
                        else: break
                else:
                    self.advance(); self.skip_newlines()
                    key = self.parse_expr(); self.skip_newlines()
                    if self.cur().type != 'CBRACK':
                        raise diag(self.cur().rng, "Missing index key closing bracket", "The index operator must end with a closing bracket.")
                    self.advance()
                    if isinstance(node, Traversal):
                        node.parts.append(('index', key)); node.step_ranges.append(key.rng if hasattr(key,'rng') else None)
                    else:
                        node = Index(node.rng, node, key)
            elif self.cur().type == 'DOTSPLAT':
                self.advance(); node = Splat(node.rng, node, [])
                while self.cur().type == 'DOT':
                    self.advance()
                    if self.cur().type == 'IDENT': node.rest.append(self.advance().text)
                    else: break
            else:
                break
        return node

    def parse_primary(self):
        self.skip_newlines()
        t = self.cur()
        if t.type == 'NUMBER':
            self.advance()
            # int vs float
            if re.fullmatch(r'\d+', t.text):
                v = int(t.text)
            else:
                v = float(t.text)
            return Literal(t.rng, v, 'number', t.text, t)
        if t.type == 'STRING':
            self.advance()
            return self.string_node(t)
        if t.type == 'OPAREN':
            self.advance(); self.skip_newlines()
            e = self.parse_expr(); self.skip_newlines()
            if self.cur().type != 'CPAREN':
                raise diag(self.cur().rng, "Unbalanced parentheses", "Expected a closing parenthesis to terminate the expression.")
            self.advance()
            return Paren(t.rng, e)
        if t.type == 'OBRACK':
            return self.parse_list()
        if t.type == 'OBRACE':
            return self.parse_object()
        if t.type == 'IDENT':
            name = t.text
            if name in ('true', 'false'):
                self.advance(); return Literal(t.rng, name == 'true', 'bool', name, t)
            if name == 'null':
                self.advance(); return Literal(t.rng, None, 'null', name, t)
            # function call
            if self.peek(1).type == 'OPAREN':
                name_tok = self.advance(); self.advance()
                args = []; expand = False
                self.skip_newlines()
                while self.cur().type != 'CPAREN':
                    args.append(self.parse_expr()); self.skip_newlines()
                    if self.cur().type == 'ELLIPSIS':
                        expand = True; self.advance(); self.skip_newlines(); break
                    if self.cur().type == 'COMMA':
                        self.advance(); self.skip_newlines(); continue
                    break
                if self.cur().type != 'CPAREN':
                    raise diag(self.cur().rng, "Missing argument separator", "A comma is required to separate each function argument from the next.")
                self.advance()
                return Call(name_tok.rng, name, args, expand, name_tok.rng)
            self.advance()
            return Traversal(t.rng, [name], t.rng, [])
        raise diag(t.rng, "Invalid expression", "Expected the start of an expression, but found an invalid expression token.")

    def string_node(self, t):
        if t.heredoc:
            lines = t.segments[0][1] if t.segments else []
            if t.indent_heredoc and lines:
                # strip smallest leading spaces
                indents = [len(l) - len(l.lstrip(' \t')) for l in lines if l.strip()]
                m = min(indents) if indents else 0
                lines = [l[m:] if len(l) >= m else l for l in lines]
            text = ''.join(l + '\n' for l in lines)
            # heredoc may contain interpolations; handle simple ${} substitution via re-parse
            if '${' in text:
                return self._template_from_text(text, t)
            return Literal(t.rng, text, 'string', t.text, t)
        if not t.segments or all(s[0] == 'lit' for s in t.segments):
            val = unquote_raw(''.join(s[1] for s in t.segments)) if t.segments else ''
            return Literal(t.rng, val, 'string', t.text, t)
        parts = []
        for seg in t.segments:
            if seg[0] == 'lit': parts.append(unquote_raw(seg[1]))
            elif seg[0] == 'expr':
                sub = parse_expression(seg[1], self.filename)
                parts.append(sub)
            elif seg[0] == 'directive':
                parts.append(('directive', seg[1]))
        return Template(t.rng, parts, t)

    def _template_from_text(self, text, t):
        parts = []; i = 0
        while i < len(text):
            j = text.find('${', i)
            if j < 0:
                parts.append(text[i:]); break
            parts.append(text[i:j])
            depth = 1; k = j + 2
            while k < len(text) and depth:
                if text[k] == '{': depth += 1
                elif text[k] == '}':
                    depth -= 1
                    if depth == 0: break
                k += 1
            parts.append(parse_expression(text[j+2:k], self.filename))
            i = k + 1
        return Template(t.rng, parts, t)

    def parse_list(self):
        open_t = self.advance(); self.skip_newlines()
        if self.cur().type == 'IDENT' and self.cur().text == 'for':
            return self.parse_for(open_t, False)
        items = []
        while self.cur().type != 'CBRACK':
            if self.cur().type == 'EOF': break
            items.append(self.parse_expr()); self.skip_newlines()
            if self.cur().type == 'COMMA':
                self.advance(); self.skip_newlines(); continue
            break
        self.skip_newlines()
        if self.cur().type == 'CBRACK': self.advance()
        return ListCons(open_t.rng, items)

    def parse_object(self):
        open_t = self.advance(); self.skip_newlines()
        if self.cur().type == 'IDENT' and self.cur().text == 'for':
            return self.parse_for(open_t, True)
        items = []
        while self.cur().type != 'CBRACE':
            if self.cur().type == 'EOF': break
            # key
            kt = self.cur(); dynamic = False
            if kt.type == 'IDENT':
                self.advance(); key = kt.text
                # traversal key like a.b treated dynamic if followed by dot etc - simplify: if dot/brace then parse as expr?
                if self.cur().type in ('DOT', 'OBRACK'):
                    # rebuild traversal
                    node = Traversal(kt.rng, [kt.text], kt.rng, [])
                    # use postfix on node manually by temporary rewinding is complex; handle simple dot chain
                    while self.cur().type == 'DOT':
                        dot = self.advance()
                        nt = self.advance(); node.parts.append(nt.text)
                    key = node; dynamic = True
            elif kt.type == 'STRING':
                self.advance(); key = string_token_value(kt)
            elif kt.type == 'OPAREN':
                key = self.parse_expr(); dynamic = True
            else:
                key = self.parse_expr(); dynamic = True
            self.skip_newlines()
            if self.cur().type in ('ASSIGN', 'COLON'):
                self.advance()
            else:
                raise diag(self.cur().rng, "Missing key/value separator", "Expected an equals sign (\"=\") to mark the beginning of the attribute value.")
            self.skip_newlines()
            val = self.parse_expr()
            items.append((key, val, dynamic))
            # separator comma or newline
            if self.cur().type == 'COMMA':
                self.advance()
            self.skip_newlines()
            while self.cur().type == 'COMMENT': self.advance()
        if self.cur().type == 'CBRACE': self.advance()
        return ObjectCons(open_t.rng, items)

    def parse_for(self, open_t, is_object):
        self.advance()  # for
        self.skip_newlines()
        v1 = self.advance()  # ident
        key_var = None; val_var = v1.text
        if self.cur().type == 'COMMA':
            self.advance(); self.skip_newlines()
            v2 = self.advance(); key_var = val_var; val_var = v2.text
        self.skip_newlines()
        if self.cur().type == 'IDENT' and self.cur().text == 'in': self.advance()
        self.skip_newlines()
        coll = self.parse_expr(); self.skip_newlines()
        if self.cur().type == 'COLON': self.advance()
        self.skip_newlines()
        grouping = False
        if is_object:
            key = self.parse_expr(); self.skip_newlines()
            if self.cur().type == 'FATARROW': self.advance()
            self.skip_newlines()
            val = self.parse_expr(); self.skip_newlines()
            if self.cur().type == 'ELLIPSIS': grouping = True; self.advance()
        else:
            key = None; val = self.parse_expr(); self.skip_newlines()
        cond = None
        if self.cur().type == 'IDENT' and self.cur().text == 'if':
            self.advance(); self.skip_newlines(); cond = self.parse_expr(); self.skip_newlines()
        # closing
        if self.cur().type in ('CBRACK', 'CBRACE'): self.advance()
        return ForExpr(open_t.rng, is_object, key_var, val_var, coll, val, key, cond, grouping)

def string_token_value(t):
    if t.heredoc:
        lines = t.segments[0][1] if t.segments else []
        return ''.join(l + '\n' for l in lines)
    if not t.segments:
        return ''
    # only literal assumed
    return unquote_raw(''.join(s[1] for s in t.segments if s[0] == 'lit'))

def parse_expression(src, filename=""):
    toks = tokenize(src, filename)
    p = Parser(toks, filename, src)
    return p.parse_expr()

def parse_hcl(src, filename=""):
    if isinstance(src, bytes): src = src.decode('utf-8', 'replace')
    toks = tokenize(src, filename)
    p = Parser(toks, filename, src)
    return p.parse_file()

# ---------------- Evaluation ----------------
class NullType:
    def __repr__(self): return 'null'
NULL = NullType()

class CtyType:
    def __init__(self, name, arg=None):
        self.name = name; self.arg = arg
    def __repr__(self):
        return self.name if self.arg is None else f"{self.name}({self.arg!r})"

class Ref:
    def __init__(self, parts):
        self.parts = tuple(parts)
    def __repr__(self): return '.'.join(str(p) for p in self.parts)
    def __str__(self): return '.'.join(str(p) for p in self.parts)
    def __eq__(self, other): return isinstance(other, Ref) and self.parts == other.parts
    def __hash__(self): return hash(self.parts)

class RefBuilder:
    # mapping children: name -> Ref or RefBuilder
    def __init__(self, children=None):
        self.children = children or {}

class SqlExpr:
    def __init__(self, x): self.x = x
    def __repr__(self): return f'sql("{self.x}")'

class TypeValue:
    # schemahcl type e.g int, varchar(255)
    def __init__(self, name, args=None, raw=None):
        self.name = name; self.args = args or []; self.raw = raw
    def __repr__(self):
        if self.raw is not None: return f'sql("{self.raw}")'
        if self.args: return f"{self.name}({','.join(str(a) for a in self.args)})"
        return self.name

def levenshtein(a, b):
    if a == b: return 0
    la, lb = len(a), len(b)
    if la == 0: return lb
    if lb == 0: return la
    prev = list(range(lb+1))
    for i in range(1, la+1):
        cur = [i] + [0]*lb
        for j in range(1, lb+1):
            cost = 0 if a[i-1] == b[j-1] else 1
            cur[j] = min(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
        prev = cur
    return prev[lb]

def suggestion(name, candidates):
    best = None; bestd = None
    for c in candidates:
        d = levenshtein(name, c)
        # HCL uses SuggestionThreshold... roughly if distance <=2 or prefix
        if bestd is None or d < bestd:
            bestd, best = d, c
    if best is not None and (bestd <= 2 or (best and name and (best.startswith(name[:2]) if len(name)>=2 else False))):
        # observed foo -> bool (distance 2? foo/b ol?) lev=2
        return best
    return None

class EvalCtx:
    def __init__(self, vars=None, functions=None, filename=""):
        self.vars = vars or {}
        self.functions = functions or {}
        self.filename = filename
        self.scopes = []
    def child(self, extra_vars):
        c = EvalCtx(dict(self.vars), self.functions, self.filename)
        c.vars.update(extra_vars)
        return c

def to_string(v):
    if v is NULL or v is None: return ''
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, float):
        if v == int(v) and abs(v) < 1e15: return str(int(v)) if False else _format_number(v)
        return _format_number(v)
    if isinstance(v, (list, tuple)):
        return '[' + ', '.join(to_string(x) for x in v) + ']'
    return str(v)

def _format_number(v):
    if isinstance(v, int): return str(v)
    # Go big.Float text/plural? Use repr trimming
    s = ('%f' % v)
    # but small/large: use g with enough precision
    s = format(v, '.15g')
    return s

def truthy(v):
    return bool(v)

def eval_expr(node, ctx):
    if node is None: return NULL
    if isinstance(node, Paren): return eval_expr(node.expr, ctx)
    if isinstance(node, Literal):
        if node.kind == 'null': return NULL
        return node.value
    if isinstance(node, Template):
        return eval_template(node, ctx)
    if isinstance(node, ListCons):
        return [eval_expr(x, ctx) for x in node.items]
    if isinstance(node, ObjectCons):
        d = {}
        for key, val, dyn in node.items:
            if dyn:
                kv = eval_expr(key, ctx) if not isinstance(key, str) else key
                k = to_string(kv)
            else:
                k = key if isinstance(key, str) else to_string(eval_expr(key, ctx))
            d[k] = eval_expr(val, ctx)
        return d
    if isinstance(node, Traversal):
        return eval_traversal(node, ctx)
    if isinstance(node, Index):
        coll = eval_expr(node.coll, ctx)
        key = eval_expr(node.key, ctx)
        return index_value(coll, key, node)
    if isinstance(node, Splat):
        coll = eval_expr(node.coll, ctx)
        if not isinstance(coll, (list, tuple)): coll = [coll]
        out = []
        for el in coll:
            v = el
            for r in node.rest:
                v = index_value(v, r, node)
            out.append(v)
        return out
    if isinstance(node, Call):
        return eval_call(node, ctx)
    if isinstance(node, Unary):
        v = eval_expr(node.expr, ctx)
        if node.op == '!': return not truthy(v)
        if node.op == '-': return -v
        return v
    if isinstance(node, Binary):
        if node.op == '&&':
            return truthy(eval_expr(node.left, ctx)) and truthy(eval_expr(node.right, ctx))
        if node.op == '||':
            return truthy(eval_expr(node.left, ctx)) or truthy(eval_expr(node.right, ctx))
        l = eval_expr(node.left, ctx); r = eval_expr(node.right, ctx)
        try:
            if node.op == '+': return l + r
            if node.op == '-': return l - r
            if node.op == '*': return l * r
            if node.op == '/':
                # HCL number division yields float
                return l / r
            if node.op == '%': return l % r
            if node.op == '==': return values_equal(l, r)
            if node.op == '!=': return not values_equal(l, r)
            if node.op == '<': return l < r
            if node.op == '<=': return l <= r
            if node.op == '>': return l > r
            if node.op == '>=': return l >= r
        except HCLError:
            raise
        except Exception as e:
            raise diag(node.rng, "Invalid operand", str(e))
    if isinstance(node, Conditional):
        return eval_expr(node.yes if truthy(eval_expr(node.cond, ctx)) else node.no, ctx)
    if isinstance(node, ForExpr):
        coll = eval_expr(node.coll, ctx)
        items = []
        if isinstance(coll, dict):
            iterable = list(coll.items())
        elif isinstance(coll, (list, tuple)):
            iterable = list(enumerate(coll))
        else:
            iterable = [(0, coll)]
        if node.is_object:
            out = {}
            for k, v in iterable:
                extra = {node.val_var: v}
                if node.key_var: extra[node.key_var] = k
                c2 = ctx.child(extra)
                if node.cond is not None and not truthy(eval_expr(node.cond, c2)): continue
                kk = to_string(eval_expr(node.key, c2)); vv = eval_expr(node.val, c2)
                if node.grouping:
                    out.setdefault(kk, []).append(vv)
                else:
                    out[kk] = vv
            return out
        else:
            out = []
            for k, v in iterable:
                extra = {node.val_var: v}
                if node.key_var: extra[node.key_var] = k
                c2 = ctx.child(extra)
                if node.cond is not None and not truthy(eval_expr(node.cond, c2)): continue
                out.append(eval_expr(node.val, c2))
            return out
    raise HCLError(f"unsupported expression {type(node).__name__}")

def values_equal(a, b):
    if a is NULL: a = None
    if b is NULL: b = None
    if isinstance(a, bool) != isinstance(b, bool): return False
    return a == b

def index_value(coll, key, node=None):
    if isinstance(coll, RefBuilder):
        if isinstance(key, str) and key in coll.children:
            return coll.children[key]
        raise HCLError("unsupported attribute")
    if isinstance(coll, dict):
        if key in coll: return coll[key]
        # unsupported attribute diagnostic constructed by traversal caller mostly; here generic
        rng = getattr(node, 'rng', None)
        raise diag(rng, "Unsupported attribute", f'This object does not have an attribute named "{key}".')
    if isinstance(coll, (list, tuple)):
        try:
            idx = int(key)
            return coll[idx]
        except Exception:
            raise diag(getattr(node,'rng',None), "Invalid index", "The given key does not identify an element in this collection value.")
    if isinstance(coll, (Ref,)):
        return Ref(coll.parts + (key,))
    raise diag(getattr(node,'rng',None), "Unsupported attribute", f'This object does not have an attribute named "{key}".')

def eval_traversal(node, ctx):
    root = node.parts[0]
    if root not in ctx.vars:
        candidates = list(ctx.vars.keys())
        sug = suggestion(root, candidates)
        detail = f'There is no variable named "{root}".'
        if sug: detail += f' Did you mean "{sug}"?'
        summary = "Unknown variable"
        if root == 'local':
            summary = "Unknown local"
        raise diag(node.root_rng, summary, detail)
    v = ctx.vars[root]
    for idx, part in enumerate(node.parts[1:]):
        rng = node.step_ranges[idx] if idx < len(node.step_ranges) else node.rng
        if isinstance(part, tuple) and part and part[0] == 'index':
            key = eval_expr(part[1], ctx)
            v = index_value(v, key, node)
            continue
        if isinstance(v, RefBuilder):
            if part in v.children:
                v = v.children[part]; continue
            raise diag(rng, "Unsupported attribute", f'This object does not have an attribute named "{part}".')
        if isinstance(v, Ref):
            v = Ref(v.parts + (part,)); continue
        if isinstance(v, dict):
            if part in v:
                v = v[part]; continue
            raise diag(rng, "Unsupported attribute", f'This object does not have an attribute named "{part}".')
        if isinstance(v, (list, tuple)) and part.isdigit():
            v = v[int(part)]; continue
        # attributes on objects implemented as python objects? allow simple
        raise diag(rng, "Unsupported attribute", f'This object does not have an attribute named "{part}".')
    return v

def eval_template(node, ctx):
    out = []
    # directives if/for not implemented in detail; process simple sequential, ignoring directive markers except structure unsupported -> treat literal exclusion roughly
    i = 0
    parts = node.parts
    # Simple handling: if directives present, attempt eval if blocks
    def render_range(start, end, local_ctx):
        s = []
        j = start
        while j < end:
            p = parts[j]
            if isinstance(p, tuple) and p[0] == 'directive':
                # skip directives (if/else/endif/for/endfor) very rough: ignore
                j += 1; continue
            if isinstance(p, str): s.append(p)
            else: s.append(to_string(eval_expr(p, local_ctx)))
            j += 1
        return ''.join(s)
    return render_range(0, len(parts), ctx)

def eval_call(node, ctx):
    fn = ctx.functions.get(node.name)
    if fn is None:
        sug = suggestion(node.name, list(ctx.functions.keys()))
        detail = f'There is no function named "{node.name}".'
        if sug: detail += f' Did you mean "{sug}"?'
        raise diag(node.name_rng, "Call to unknown function", detail)
    args = []
    for a in node.args:
        v = eval_expr(a, ctx)
        if node.expand and a is node.args[-1] and isinstance(v, (list, tuple)):
            args.extend(v)
        else:
            args.append(v)
    try:
        return fn(*args)
    except HCLError:
        raise
    except TypeError as e:
        raise diag(node.name_rng, "Invalid function argument", str(e))
    except Exception as e:
        raise diag(node.name_rng, "Error in function call", str(e))

