    return out

def expand_string(t):
    s = t.text
    out = []
    if not s.startswith('"'):
        return [FT('STRING', s, t.rng)]
    out.append(FT('OQUOTE', '"', t.rng))
    i = 1
    lit_start = 1
    n = len(s)
    # determine end quote position: last char if closing present
    end = n-1 if n >= 2 and s.endswith('"') else n
    while i < end:
        if s[i] == '\\':
            i += 2; continue
        if s.startswith('$${', i) or s.startswith('%%{', i):
            i += 3; continue
        if s.startswith('${', i) or s.startswith('%{', i):
            if lit_start < i:
                out.append(FT('QLIT', s[lit_start:i], t.rng))
            kind = 'TEMPLATE_INTERP' if s[i] == '$' else 'TEMPLATE_CTRL'
            out.append(FT(kind, s[i:i+2], t.rng))
            # find matching }
            depth = 1; j = i+2
            while j < end and depth:
                if s[j] == '"':
                    j += 1
                    while j < end and s[j] != '"':
                        if s[j] == '\\': j += 1
                        j += 1
                elif s[j] == '{': depth += 1
                elif s[j] == '}':
                    depth -= 1
                    if depth == 0: break
                j += 1
            inner = s[i+2:j]
            if inner.strip():
                inner_toks = [x for x in expand_tokens(tokenize(inner, t.rng.filename if t.rng else "")) if x.type not in ('EOF','NEWLINE')]
                out.extend(inner_toks)
            out.append(FT('TEMPLATE_END', '}', t.rng))
            i = j+1; lit_start = i
            continue
        i += 1
    if lit_start < end:
        out.append(FT('QLIT', s[lit_start:end], t.rng))
    if n >= 2 and s.endswith('"'):
        out.append(FT('CQUOTE', '"', t.rng))
    return out

def spaces_before(out_tokens, i):
    """Default spaces before token i in its line (i=index within line list)."""
    if i == 0:
        return 0
    prev = out_tokens[i-1]; cur = out_tokens[i]
    pt, ct = prev.type, cur.type
    # template / string internals: no spaces at delimiters
    if ct in ('CQUOTE','TEMPLATE_END') or pt in ('OQUOTE','TEMPLATE_INTERP','TEMPLATE_CTRL'):
        return 0
    if ct in ('TEMPLATE_INTERP','TEMPLATE_CTRL') and pt in ('QLIT','OQUOTE','TEMPLATE_END'):
        return 0
    if pt == 'QLIT' or ct == 'QLIT':
        return 0
    if ct in ('COMMA','CPAREN','CBRACK','DOT','ELLIPSIS'):
        return 0
    if ct == 'CBRACE':
        return 0 if pt == 'OBRACE' else 1
    if pt in ('OPAREN','OBRACK','DOT','SPLATOPEN','DOTSPLAT'):
        return 0
    if pt == 'OBRACE':
        return 1
    if pt == 'BANG':
        return 0
    if pt == 'MINUS':
        # determine unary by token before prev
        if is_unary(out_tokens, i-1):
            return 0
        return 1
    if ct == 'OPAREN' and pt in OPERAND_END:
        return 0
    if ct == 'OBRACK' and pt in OPERAND_END:
        return 0
    if ct == 'SPLATOPEN' and pt in OPERAND_END:
        return 0
    return 1

def is_unary(tokens, idx):
    if idx == 0: return True
    prev = tokens[idx-1]
    if prev.type in OPERAND_END:
        return False
    return True

def format_hcl(src):
    if isinstance(src, bytes): src = src.decode('utf-8', 'replace')
    toks = expand_tokens(tokenize(src, ""))
    # split lines by NEWLINE tokens (EOF last)
    lines = []  # list of (tokens, had_newline)
    cur = []
    for t in toks:
        if t.type == 'NEWLINE':
            lines.append((cur, True)); cur = []
        elif t.type == 'EOF':
            if cur: lines.append((cur, False))
            break
        else:
            cur.append(t)
    # if source empty: lines empty => ''
    # compute depths
    depth = 0
    line_infos = []
    for ltoks, had_nl in lines:
        start_depth = depth
        # compute end depth, tracking only actual bracket tokens (not inside strings because expanded only templates braces are separate types)
        d = depth
        for t in ltoks:
            if t.type in OPEN: d += 1
            elif t.type in CLOSE: d -= 1
            if d < 0: d = 0
        end_depth = d
        depth = d
        indent_level = min(start_depth, end_depth)
        if indent_level < 0: indent_level = 0
        line_infos.append({
            'toks': ltoks, 'nl': had_nl, 'start_depth': start_depth, 'end_depth': end_depth,
            'indent': '  ' * indent_level,
        })
    # build each line with default spaces; keep spaces arrays for alignment adjustments
    for info in line_infos:
        ltoks = info['toks']
        spaces = [spaces_before(ltoks, i) for i in range(len(ltoks))]
        info['spaces'] = spaces
    def render(info, upto=None):
        ltoks = info['toks']; spaces = info['spaces']
        s = info['indent'] if ltoks else ''
        n = len(ltoks) if upto is None else upto
        for i in range(n):
            if i > 0: s += ' ' * spaces[i]
            s += ltoks[i].text
        return s
    # assignment alignment
    def assign_index(info):
        ltoks = info['toks']
        if not ltoks: return None
        if info['start_depth'] != info['end_depth']: return None
        d = info['start_depth']; found = None; count = 0
        for i,t in enumerate(ltoks):
            if t.type == 'ASSIGN' and d == info['start_depth']:
                found = i; count += 1
            if t.type in OPEN: d += 1
            elif t.type in CLOSE: d -= 1
        return found if count == 1 else None
    # groups contiguous qualifying
    i = 0
    while i < len(line_infos):
        if assign_index(line_infos[i]) is None:
            i += 1; continue
        j = i
        group = []
        while j < len(line_infos) and assign_index(line_infos[j]) is not None:
            group.append(line_infos[j]); j += 1
        if len(group) > 1:
            widths = []
            for info in group:
                ai = assign_index(info)
                width = len(render(info, ai))  # before assign, excluding its spaces_before
                widths.append(width)
            target = max(widths)
            for info in group:
                ai = assign_index(info)
                width = len(render(info, ai))
                info['spaces'][ai] = (target - width) + 1
        i = j
    # comment alignment groups contiguous trailing-comment lines
    def trailing_comment_index(info):
        ltoks = info['toks']
        if len(ltoks) >= 2 and ltoks[-1].type == 'COMMENT':
            return len(ltoks)-1
        return None
    i = 0
    while i < len(line_infos):
        if trailing_comment_index(line_infos[i]) is None:
            i += 1; continue
        j = i; group = []
        while j < len(line_infos) and trailing_comment_index(line_infos[j]) is not None:
            group.append(line_infos[j]); j += 1
        if len(group) > 1:
            widths = [len(render(info, trailing_comment_index(info))) for info in group]
            target = max(widths)
            for info in group:
                ci = trailing_comment_index(info)
                width = len(render(info, ci))
                info['spaces'][ci] = (target - width) + 1
        i = j
    out_parts = []
    for info in line_infos:
        rendered = render(info) if info['toks'] else ''
        out_parts.append(rendered)
        if info['nl']: out_parts.append('\n')
    return ''.join(out_parts)
