from dataclasses import dataclass, field
import re

@dataclass
class Default:
    kind: str  # 'literal' or 'raw'
    value: str  # literal V (may be SQL string token if sql_string) or raw expr X
    sql_string: bool = False

@dataclass
class Generated:
    expr: str = ''
    type: str = ''  # STORED or VIRTUAL

@dataclass
class Column:
    name: str = ''
    raw_type: str = ''
    null: bool = True
    default: object = None  # Default
    auto_increment: bool = False
    generated: object = None  # Generated
    # internal flags
    attrs: dict = field(default_factory=dict)

@dataclass
class IndexPart:
    column: str = None
    expr: str = None
    desc: bool = False
    # raw attrs
    collate: str = None

@dataclass
class Index:
    name: str = ''
    unique: bool = False
    parts: list = field(default_factory=list)
    where: str = None
    attrs: dict = field(default_factory=dict)

@dataclass
class ForeignKey:
    name: str = ''
    columns: list = field(default_factory=list)
    ref_table: str = ''
    ref_columns: list = field(default_factory=list)
    on_update: str = 'NO ACTION'
    on_delete: str = 'NO ACTION'

@dataclass
class Check:
    name: str = None
    expr: str = ''

@dataclass
class Table:
    name: str = ''
    schema_name: str = 'main'
    columns: list = field(default_factory=list)
    indexes: list = field(default_factory=list)
    primary_key: object = None  # Index or None
    foreign_keys: list = field(default_factory=list)
    checks: list = field(default_factory=list)
    without_rowid: bool = False
    strict: bool = False
    attrs: dict = field(default_factory=dict)
    def column(self, name):
        for c in self.columns:
            if c.name == name: return c
        return None

@dataclass
class Schema:
    name: str = 'main'
    tables: list = field(default_factory=list)
    attrs: dict = field(default_factory=dict)
    charset: str = None
    collate: str = None
    def table(self, name):
        for t in self.tables:
            if t.name == name: return t
        return None

@dataclass
class Realm:
    schemas: list = field(default_factory=list)
    attrs: dict = field(default_factory=dict)
    def schema(self, name):
        for s in self.schemas:
            if s.name == name: return s
        return None
    def main(self):
        return self.schemas[0] if self.schemas else None

# Type families for sqlite
INT_TYPES = {'int','integer','bigint','int2','int8','unsigned big int','tinyint','smallint','mediumint'}
STRING_TYPES = {'varchar','character','varying character','nchar','native character','nvarchar','text','clob'}
FLOAT_TYPES = {'real','double','double precision','float'}
DECIMAL_TYPES = {'numeric','decimal'}

def parse_raw_type(raw):
    """Returns (base lowercase type without parens/underscores->spaces, args list strings)."""
    if raw is None: return ('', [])
    s = str(raw).strip()
    if not s: return ('', [])
    m = re.match(r'^(.*?)(\((.*)\))?$', s, re.S)
    base = s; args = []
    if '(' in s and s.rstrip().endswith(')'):
        idx = s.find('(')
        base = s[:idx]
        inner = s[idx+1:-1].strip()
        if inner:
            args = [a.strip() for a in inner.split(',')]
    base = re.sub(r'\s+', ' ', base.strip().lower().replace('_', ' '))
    return (base, args)

def type_family(raw):
    base, _ = parse_raw_type(raw)
    if base == '': return 'blob'
    if base in INT_TYPES: return 'int'
    if base in STRING_TYPES: return 'string'
    if base in FLOAT_TYPES: return 'float'
    if base in DECIMAL_TYPES: return 'decimal'
    if base == 'boolean': return 'bool'
    if base in ('date','datetime','time','timestamp'): return 'time'
    if base in ('json','jsonb'): return 'json'
    if base == 'blob': return 'blob'
    if base == 'uuid': return 'uuid'
    # unknown types each its own family keyed by base
    return 'custom:' + base

def types_equivalent(a, b):
    return type_family(a) == type_family(b)

KNOWN_HCL_TYPES = None  # filled in hclschema to avoid cycle

def sql_type_name(raw):
    """Type name as generated in SQL CREATE statements: base without parens args."""
    base, _ = parse_raw_type(raw)
    if base == '': return 'blob'
    return base

def copy_table(t):
    import copy
    return copy.deepcopy(t)
def copy_realm(r):
    import copy
    return copy.deepcopy(r)
