    return realm

def _glob_match(pat, s):
    # Implement Go path.Match: * matches any seq of non-/ chars, ? single non-/, [] classes, \\ escapes
    import fnmatch
    # fnmatch * matches everything incl / but table names won't contain /
    return fnmatch.fnmatchcase(s, pat)

