    # mimic path.Match syntax error for bad patterns: unclosed [, trailing \
    i = 0
    while i < len(pat):
        c = pat[i]
        if c == '\\':
            i += 2; continue
        if c == '[':
            j = i+1
            if j < len(pat) and pat[j] == '^': j += 1
            if j < len(pat) and pat[j] == ']': j += 1
            while j < len(pat) and pat[j] != ']': j += 1
            if j >= len(pat):
                raise AtlasError("syntax error in pattern")
            i = j+1; continue
        i += 1

def _qid(name):
    return "'" + str(name).replace("'", "''") + "'"

def _strip_index_part_suffix(expr):
    e = expr.strip()
    # strip trailing DESC/ASC, COLLATE xxx at top level if present - simplistic
    for suf in (' DESC', ' ASC'):
        if e.upper().endswith(suf): e = e[:-len(suf)].strip()
    m = re.search(r'\s+COLLATE\s+\S+$', e, re.I)
    if m: e = e[:m.start()].strip()
    return e
