        return Default('literal', low, sql_string=True)
    if re.fullmatch(r"[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?", low):
        return Default('literal', low)
    if low.lower() in ('true','false'):
        return Default('literal', low)
    if re.fullmatch(r"0[xX][0-9a-fA-F]+", low):
        return Default('literal', low)
    if re.fullmatch(r"[xX]'[0-9a-fA-F]*'", low):
        return Default('literal', low)
    return Default('raw', low)

