import re
from model import *
from dataclasses import dataclass, field

def qid(name):
    return '`' + str(name).replace('`', '``') + '`'

NUMERIC_FAMILIES = {'int','float','decimal','bool'}

def format_default(col):
    d = col.default
    if d is None: return None
    if d.kind == 'raw':
        return f"({d.value})"
    fam = type_family(col.raw_type)
    if fam in NUMERIC_FAMILIES:
        return d.value
    if d.sql_string:
        return d.value
    return "'" + str(d.value).replace("'", "''") + "'"

def column_sql(col, table=None):
    parts = [qid(col.name), sql_type_name(col.raw_type)]
    parts.append('NULL' if col.null else 'NOT NULL')
    # inline auto increment pk handled by table builder (needs knowledge); append marker via attribute
    s = ' '.join(parts)
    return s

def build_column(col, table):
    s = f"{qid(col.name)} {sql_type_name(col.raw_type)} {'NULL' if col.null else 'NOT NULL'}"
    inline_pk = False
    if col.auto_increment and table is not None and table.primary_key is not None:
        pkcols = [p.column for p in table.primary_key.parts]
        if pkcols == [col.name]:
            inline_pk = True
    if inline_pk:
        s += ' PRIMARY KEY AUTOINCREMENT'
    if col.generated is not None:
        expr = col.generated.expr or ''
        if expr and not expr.strip().startswith('('):
            expr = f"({expr})"
        s += f" AS {expr} {col.generated.type}" if col.generated.type else f" AS {expr}"
    elif col.default is not None:
        fd = format_default(col)
        if fd is not None:
            s += f" DEFAULT {fd}"
    return s, inline_pk

def effective_index_name(table_name, idx):
    if idx.name and not idx.name.startswith('sqlite_autoindex_'):
        return idx.name
    cols = []
    for p in idx.parts:
        cols.append(p.column if p.column else (p.expr or ''))
    return f"{table_name}_{'_'.join(cols)}"

def build_create_table(table, name_override=None, indent=""):
    tname = name_override or table.name
    clauses = []
    has_inline_pk = False
    for col in table.columns:
        cs, inline = build_column(col, table)
        has_inline_pk = has_inline_pk or inline
        clauses.append(cs)
    if table.primary_key is not None and not has_inline_pk:
        pkcols = ', '.join(qid(p.column) for p in table.primary_key.parts)
        clauses.append(f"PRIMARY KEY ({pkcols})")
    for fk in table.foreign_keys:
        cols = ', '.join(qid(c) for c in fk.columns)
        refcols = ', '.join(qid(c) for c in fk.ref_columns)
        clauses.append(f"CONSTRAINT {qid(fk.name)} FOREIGN KEY ({cols}) REFERENCES {qid(fk.ref_table)} ({refcols}) ON UPDATE {fk.on_update} ON DELETE {fk.on_delete}")
    for ch in table.checks:
        if ch.name:
            clauses.append(f"CONSTRAINT {qid(ch.name)} CHECK {ch.expr}")
        else:
            clauses.append(f"CHECK {ch.expr}")
    suffix = ''
    opts = []
    if table.without_rowid: opts.append('WITHOUT ROWID')
    if table.strict: opts.append('STRICT')
    if opts: suffix = ' ' + ', '.join(opts)
    if indent:
        if not clauses:
            body = '()'
            return f"CREATE TABLE {qid(tname)} {body}{suffix}"
        inner = (',\n' + indent).join(clauses)
        return f"CREATE TABLE {qid(tname)} (\n{indent}{inner}\n){suffix}"
    else:
        return f"CREATE TABLE {qid(tname)} ({', '.join(clauses)}){suffix}"

def build_create_index(table_name, idx):
    parts = []
    for p in idx.parts:
        if p.column:
            s = qid(p.column)
        else:
            s = p.expr or ''
        if p.desc: s += ' DESC'
        parts.append(s)
    uniq = 'UNIQUE ' if idx.unique else ''
    s = f"CREATE {uniq}INDEX {qid(effective_index_name(table_name, idx))} ON {qid(table_name)} ({', '.join(parts)})"
    if idx.where:
        s += f" WHERE {idx.where}"
    return s

@dataclass
class PlanChange:
    cmd: str = ''
    comment: str = ''
    reverse: str = ''
    source: object = None  # string kind like AddTable etc or object reference for templates
    create_table: object = None
    create_name: str = None
    # For recreate, create_table is a Table model and create_name is new_ name.

def capitalize_comment(c):
    if not c: return c
    return c[0].upper() + c[1:]

def pretty_create(cmd, indent):
    # Generic split if needed (used when create_table not available)
    if not cmd.startswith('CREATE TABLE '):
        return cmd
    i = cmd.find('(')
    if i < 0: return cmd
    depth = 0; j = i
    in_str = False; in_bt = False
    while j < len(cmd):
        ch = cmd[j]
        if in_str:
            if ch == "'":
                if j+1 < len(cmd) and cmd[j+1] == "'": j += 1
                else: in_str = False
        elif in_bt:
            if ch == '`': in_bt = False
        else:
            if ch == "'": in_str = True
            elif ch == '`': in_bt = True
            elif ch == '(': depth += 1
            elif ch == ')':
                depth -= 1
                if depth == 0: break
        j += 1
    inner = cmd[i+1:j]
    if not inner.strip(): return cmd
    parts = []; cur = ''; depth = 0; in_str=False; in_bt=False
    for ch in inner:
        if in_str:
            cur += ch
            if ch == "'": in_str=False
            continue
        if in_bt:
            cur += ch
            if ch == '`': in_bt=False
            continue
        if ch == "'": in_str=True; cur+=ch; continue
        if ch == '`': in_bt=True; cur+=ch; continue
        if ch == '(': depth += 1
        elif ch == ')': depth -= 1
        if ch == ',' and depth == 0:
            parts.append(cur.strip()); cur=''
        else: cur += ch
    if cur.strip(): parts.append(cur.strip())
    return cmd[:i] + "(\n" + indent + (",\n"+indent).join(parts) + "\n)" + cmd[j+1:]

def render_sql(changes, indent=""):
    out = []
    for ch in changes:
        stmt = ch.cmd
        if indent:
            if ch.create_table is not None:
                stmt = build_create_table(ch.create_table, name_override=ch.create_name, indent=indent)
            elif stmt.startswith('CREATE TABLE '):
                stmt = pretty_create(stmt, indent)
        if ch.comment:
            out.append(f"-- {capitalize_comment(ch.comment)}\n")
        out.append(stmt + ";\n")
    return ''.join(out)

def changes_for_new_table(table):
    changes = []
    cmd = build_create_table(table)
    changes.append(PlanChange(cmd=cmd, comment=f'create "{table.name}" table', reverse=f"DROP TABLE {qid(table.name)}", source=('AddTable', table), create_table=table))
    for idx in table.indexes:
        en = effective_index_name(table.name, idx)
        changes.append(PlanChange(cmd=build_create_index(table.name, idx), comment=f'create index "{en}" to table: "{table.name}"', reverse=f"DROP INDEX {qid(en)}", source=('AddIndex', table, idx)))
    return changes

def realm_to_changes(realm):
    changes = []
    for sch in realm.schemas:
        for t in sch.tables:
            changes.extend(changes_for_new_table(t))
    return changes
