import json, re
from model import *
from errors import AtlasError
from hclfmt import format_hcl

SIZED_TYPES = {'varchar','character','varying character','nchar','native character','nvarchar','numeric','decimal','text'}
KNOWN_IDENTS = {'int','integer','bigint','int2','int8','unsigned_big_int','tinyint','smallint','mediumint','clob','blob','real','double','double_precision','float','boolean','date','datetime','json','jsonb','uuid'}

def hcl_quote(s):
    out = '"'
    for ch in str(s):
        if ch == '"': out += '\\"'
        elif ch == '\\': out += '\\\\'
        elif ch == '\n': out += '\\n'
        elif ch == '\r': out += '\\r'
        elif ch == '\t': out += '\\t'
        elif ord(ch) < 0x20:
            out += '\\u%04x' % ord(ch)
        else: out += ch
    out += '"'
    # escape template sequences (after other escaping, sequences are literal chars)
    out = out.replace('${', '$${').replace('%{', '%%{')
    return out

def is_ident(s):
    return re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', str(s)) is not None

def ref_step(prefix, name):
    if is_ident(name):
        return f"{prefix}.{name}"
    return f"{prefix}[{hcl_quote(name)}]"

def col_ref(name):
    return ref_step('column', name)

def table_col_ref(table, col):
    return ref_step(ref_step(ref_step('table', table), 'column') if False else (f"table.{table}.column" if is_ident(table) else f"table[{hcl_quote(table)}].column"), col) if False else _tcr(table,col)

def _tcr(table, col):
    base = f"table.{table}" if is_ident(table) else f"table[{hcl_quote(table)}]"
    return ref_step(base + '.column', col)

def hcl_type(raw):
    if raw is None or str(raw).strip() == '':
        return 'blob'
    base, args = parse_raw_type(raw)
    ident = base.replace(' ', '_')
    if base in SIZED_TYPES:
        if args:
            return f"{ident}({','.join(args)})"
        return ident
    if ident in KNOWN_IDENTS:
        return ident
    if base == 'char':
        return 'sql("char")'
    return f"sql({hcl_quote(raw)})"

def format_float_go(v):
    # approx strconv.FormatFloat(v,'f',-1,64) via g then expand
    s = format(v, '.15g')
    if 'e' in s or 'E' in s:
        from decimal import Decimal
        s = format(Decimal(s), 'f')
    return s

class MarshalError(Exception):
    pass

def hcl_default(col):
    d = col.default
    if d is None: return None
    if d.kind == 'raw':
        return f"sql({hcl_quote(d.value)})"
    v = d.value
    if d.sql_string:
        content = v[1:-1].replace("''", "'") if len(v) >= 2 else v
        return hcl_quote(content)
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, (int, float)):
        # HCL-origin numeric value
        if type_family(col.raw_type) == 'string':
            return hcl_quote(format_float_go(v) if isinstance(v,float) else str(v))
        return format_float_go(v) if isinstance(v,float) else str(v)
    sv = str(v)
    if sv.lower() in ('true','false'):
        return sv.lower()
    if re.fullmatch(r"[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?", sv):
        if type_family(col.raw_type) == 'string':
            return hcl_quote(sv)
        if '.' in sv:
            try:
                fv = float(sv)
            except Exception:
                raise MarshalError(f'strconv.ParseFloat: parsing "{sv}": invalid syntax')
            return format_float_go(fv)
        else:
            # ParseInt then ParseUint semantics
            if re.fullmatch(r"[+-]?\d+", sv):
                iv = int(sv)
                if -2**63 <= iv <= 2**63-1:
                    return str(iv)
                if iv >= 0 and iv <= 2**64-1:
                    return str(iv)
                if iv >= 0:
                    raise MarshalError(f'strconv.ParseUint: parsing "{sv}": value out of range')
                raise MarshalError(f'strconv.ParseInt: parsing "{sv}": value out of range')
            # exponent without dot -> ParseInt syntax error
            raise MarshalError(f'strconv.ParseInt: parsing "{sv}": invalid syntax')
    if isinstance(v, str) and d.kind == 'literal' and getattr(d, '_hcl_string', False):
        return hcl_quote(v)
    return f"sql({hcl_quote(sv)})"

def marshal_hcl(realm):
    try:
        return _marshal_hcl(realm)
    except MarshalError as e:
        raise AtlasError(f"specutil: failed converting schema to spec: {e}")

def _marshal_hcl(realm):
    lines = []
    for sch in realm.schemas:
        for t in sch.tables:
            lines.append(f"table {hcl_quote(t.name)} {{")
            lines.append(f"  schema = {ref_step('schema', sch.name)}")
            for col in t.columns:
                lines.append(f"  column {hcl_quote(col.name)} {{")
                lines.append(f"    null = {'true' if col.null else 'false'}")
                lines.append(f"    type = {hcl_type(col.raw_type)}")
                dv = hcl_default(col)
                if dv is not None:
                    lines.append(f"    default = {dv}")
                if col.auto_increment:
                    lines.append(f"    auto_increment = true")
                if col.generated is not None:
                    lines.append(f"    as {{")
                    lines.append(f"      expr = {hcl_quote(col.generated.expr)}")
                    lines.append(f"      type = {col.generated.type}")
                    lines.append(f"    }}")
                lines.append(f"  }}")
            if t.primary_key is not None:
                lines.append(f"  primary_key {{")
                cols = ', '.join(col_ref(p.column) for p in t.primary_key.parts)
                lines.append(f"    columns = [{cols}]")
                lines.append(f"  }}")
            for fk in t.foreign_keys:
                lines.append(f"  foreign_key {hcl_quote(fk.name)} {{")
                cols = ', '.join(col_ref(c) for c in fk.columns)
                lines.append(f"    columns = [{cols}]")
                refs = ', '.join(_tcr(fk.ref_table, c) for c in fk.ref_columns)
                lines.append(f"    ref_columns = [{refs}]")
                lines.append(f"    on_update = {str(fk.on_update).replace(' ','_')}")
                lines.append(f"    on_delete = {str(fk.on_delete).replace(' ','_')}")
                lines.append(f"  }}")
            for idx in t.indexes:
                lines.append(f"  index {hcl_quote(idx.name)} {{")
                simple = all(p.column and not p.desc and not p.expr for p in idx.parts)
                if idx.unique:
                    lines.append(f"    unique = true")
                if simple:
                    cols = ', '.join(col_ref(p.column) for p in idx.parts)
                    lines.append(f"    columns = [{cols}]")
                else:
                    for p in idx.parts:
                        lines.append(f"    on {{")
                        if p.desc:
                            lines.append(f"      desc = true")
                        if p.column:
                            lines.append(f"      column = {col_ref(p.column)}")
                        if p.expr:
                            lines.append(f"      expr = {hcl_quote(p.expr)}")
                        lines.append(f"    }}")
                if idx.where:
                    lines.append(f"    where = {hcl_quote(idx.where)}")
                lines.append(f"  }}")
            for ch in t.checks:
                if ch.name:
                    lines.append(f"  check {hcl_quote(ch.name)} {{")
                else:
                    lines.append(f"  check {{")
                lines.append(f"    expr = {hcl_quote(ch.expr)}")
                lines.append(f"  }}")
            if t.without_rowid:
                lines.append(f"  without_rowid = true")
            if t.strict:
                lines.append(f"  strict = true")
            lines.append("}")
        # schema block
        lines.append(f"schema {hcl_quote(sch.name)} {{")
        if sch.charset: lines.append(f"  charset = {hcl_quote(sch.charset)}")
        if sch.collate: lines.append(f"  collate = {hcl_quote(sch.collate)}")
        lines.append("}")
    text = '\n'.join(lines) + ('\n' if lines else '')
    return format_hcl(text)

def go_json(obj):
    s = json.dumps(obj, ensure_ascii=False, separators=(',', ':'))
    # Go json.Marshal HTML escaping
    s = s.replace('&', '\\u0026').replace('<', '\\u003c').replace('>', '\\u003e')
    s = s.replace('\u2028', '\\u2028').replace('\u2029', '\\u2029')
    return s

def realm_to_json_spec(realm):
    schemas = []
    for sch in realm.schemas:
        so = {"name": sch.name}
        if sch.tables:
            tables = []
            for t in sch.tables:
                to = {"name": t.name}
                if t.columns:
                    cols = []
                    for c in t.columns:
                        co = {"name": c.name}
                        if c.raw_type:
                            co["type"] = c.raw_type
                        if c.null:
                            co["null"] = True
                        cols.append(co)
                    to["columns"] = cols
                if t.indexes:
                    idxs = []
                    for idx in t.indexes:
                        io = {"name": idx.name}
                        if idx.unique: io["unique"] = True
                        parts = []
                        for p in idx.parts:
                            po = {}
                            if p.desc: po["desc"] = True
                            if p.column: po["column"] = p.column
                            if p.expr: po["expr"] = p.expr
                            parts.append(po)
                        if parts: io["parts"] = parts
                        idxs.append(io)
                    to["indexes"] = idxs
                if t.primary_key is not None:
                    to["primary_key"] = {"parts": [{"column": p.column} if p.column else {"expr": p.expr} for p in t.primary_key.parts]}
                if t.foreign_keys:
                    fks = []
                    for fk in t.foreign_keys:
                        fks.append({"name": fk.name, "columns": list(fk.columns), "references": {"table": fk.ref_table, "columns": list(fk.ref_columns)}})
                    to["foreign_keys"] = fks
                tables.append(to)
            so["tables"] = tables
        schemas.append(so)
    return {"schemas": schemas}

def realm_to_json(realm):
    return go_json(realm_to_json_spec(realm))

def realm_to_mermaid(realm):
    lines = ["erDiagram"]
    rels = []
