                    to["foreign_keys"] = fks
                tables.append(to)
            so["tables"] = tables
        schemas.append(so)
    return {"schemas": schemas}

def realm_to_json(realm):
    return go_json(realm_to_json_spec(realm))

def realm_to_mermaid(realm):
    lines = ["erDiagram"]
    rels = []
    for sch in realm.schemas:
        for t in sch.tables:
            pkcols = set(p.column for p in t.primary_key.parts) if t.primary_key else set()
            fkcols = set()
            for fk in t.foreign_keys: fkcols.update(fk.columns)
