                lines.append(f"      {typ} {c.name}{suffix}")
            lines.append("    }")
            for fk in t.foreign_keys:
                rels.append(f"    {t.name} }}o--o| {fk.ref_table} : {fk.name}")
    lines.extend(rels)
    return '\n'.join(lines) + '\n'
