                        idx = s[1]; en = effective_index_name(cur.name, idx)
                        body.append(PlanChange(cmd=f"DROP INDEX {qid(en)}", comment=f'drop index "{en}" from table: "{cur.name}"', source=('DropIndex', cur, idx)))
