                    if s[0] == 'AddIndex':
                        idx = s[1]; en = effective_index_name(des.name, idx)
                        body.append(PlanChange(cmd=build_create_index(des.name, idx), comment=f'create index "{en}" to table: "{des.name}"', source=('AddIndex', des, idx)))
