def _recreate_table(cur, des):
    out = []
    new_name = f"new_{des.name}"
    out.append(PlanChange(cmd=build_create_table(des, name_override=new_name), comment=f'create "{new_name}" table', source=('AddTable', des), create_table=des, create_name=new_name))
    cur_names = {c.name for c in cur.columns}
    common = [c.name for c in des.columns if c.name in cur_names and c.generated is None]
    if common:
        cols = ', '.join(qid(c) for c in common)
        out.append(PlanChange(cmd=f"INSERT INTO {qid(new_name)} ({cols}) SELECT {cols} FROM {qid(cur.name)}", comment=f'copy rows from old table "{cur.name}" to new temporary table "{new_name}"', source=('CopyTable', cur, des)))
    out.append(PlanChange(cmd=f"DROP TABLE {qid(cur.name)}", comment=f'drop "{cur.name}" table after copying rows', source=('DropTable', cur)))
    out.append(PlanChange(cmd=f"ALTER TABLE {qid(new_name)} RENAME TO {qid(des.name)}", comment=f'rename temporary table "{new_name}" to "{des.name}"', source=('RenameTable', cur, des)))
    for idx in des.indexes:
        en = effective_index_name(des.name, idx)
        out.append(PlanChange(cmd=build_create_index(des.name, idx), comment=f'create index "{en}" to table: "{des.name}"', source=('AddIndex', des, idx)))
    return out

def plan_for_drop_all(realm):
    """Schema clean: drop all tables."""
    des = Realm(schemas=[Schema(name=realm.schemas[0].name if realm.schemas else 'main', tables=[])])
    plan, _ = plan_changes(realm, des)
    return plan
