import os, re
from hcl import *
from errors import AtlasError

class EnvConfig:
    def __init__(self):
        self.name = ''
        self.url = ''
        self.dev = ''
        self.src = []
        self.schemas = []
        self.exclude = []
        self.migration_dir = ''
        self.migration_format = ''
        self.revisions_schema = ''
        self.raw = {}

def file_path_from_url(url, kind='config'):
    # kind config or dir
    if url.startswith('file://'):
        rest = url[len('file://'):]
        return rest
    if url.startswith('file:'):
        return url[len('file:'):]
    if '://' not in url:
        if kind == 'config':
            raise AtlasError(f"missing scheme for config file. Did you mean file://{url}?")
        elif kind == 'dir':
            raise AtlasError(f'missing scheme for dir url. Did you mean "file://{url}"? ')
        else:
            raise AtlasError("missing scheme. See: https://atlasgo.io/url")
    scheme = url.split('://',1)[0]
    if kind == 'config':
        raise AtlasError(f'unsupported config file driver "{scheme}"')
    if kind == 'dir':
        raise AtlasError(f'unsupported driver "{scheme}"')
    raise AtlasError(f'unsupported driver "{scheme}"')

def convert_to_type(value, ctytype):
    if ctytype is None: return value
    name = ctytype.name if isinstance(ctytype, CtyType) else str(ctytype)
    if name == 'string':
        if isinstance(value, bool): return 'true' if value else 'false'
        if isinstance(value, float): return _format_number(value)
        if value is NULL: return ''
        return str(value)
    if name == 'bool':
        if isinstance(value, bool): return value
        raise ValueError('bool')
    if name == 'number':
        if isinstance(value, bool): raise ValueError('number')
        if isinstance(value, (int,float)): return value
        raise ValueError('number')
    if name in ('list','set'):
        if isinstance(value, (list,tuple)):
            arg = ctytype.arg if isinstance(ctytype, CtyType) else None
            return [convert_to_type(v, arg) for v in value]
        raise ValueError(name)
    if name == 'map':
        if isinstance(value, dict):
            arg = ctytype.arg if isinstance(ctytype, CtyType) else None
            return {k: convert_to_type(v, arg) for k,v in value.items()}
        raise ValueError(name)
    return value

def convert_input_string(raw, ctytype, varname):
    if ctytype is None: return raw
    name = ctytype.name if isinstance(ctytype, CtyType) else str(ctytype)
    if name == 'string' or name == 'any': return raw
    if name == 'bool':
        low = raw.strip().lower()
        if low in ('true','t','1'): return True
        if low in ('false','f','0'): return False
        raise AtlasError(f'variable "{varname}": a bool is required')
    if name == 'number':
        try:
            if re.fullmatch(r'[+-]?\d+', raw.strip()): return int(raw)
            return float(raw)
        except Exception:
            raise AtlasError(f'variable "{varname}": a number is required')
    # complex: parse as HCL expression
    try:
        node = parse_expression(raw)
        v = eval_expr(node, EvalCtx(vars=default_type_vars(), functions=default_functions()))
        return convert_to_type(v, ctytype)
    except Exception:
        # Fall back to raw string; conversion errors at use sites
        return raw

def resolve_variables(body, inputs, allow_getenv=False, atlas_env='', extra_functions=None):
    """inputs: dict name->str from --var. Returns dict var values."""
    values = {}
    # undeclared inputs stay as strings
    for k,v in (inputs or {}).items(): values[k] = v
    fns = default_functions(extra_functions)
    if allow_getenv:
        fns['getenv'] = lambda name: os.environ.get(str(name), '')
    for blk in body.blocks_of('variable'):
        if not blk.labels: continue
        name = blk.labels[0]
        tb = blk.body
        type_attr = tb.attr('type')
        if type_attr is None:
            # range at open brace position zero-width
            rng = blk.open_brace_rng
            if rng is not None:
                z = Range(rng.filename, rng.line, rng.col, rng.line, rng.col, rng.start, rng.start)
            else: z = blk.type_rng
            raise diag(z, "Missing required argument", 'The argument "type" is required, but no definition was found.')
        ctx = EvalCtx(vars=default_type_vars(), functions=fns, filename=body.filename)
        # type constructors list(string) handled by default functions returning CtyType
        tval = eval_expr(type_attr.expr, ctx)
        if not isinstance(tval, CtyType):
            tval = CtyType(str(tval))
        if inputs and name in inputs:
            values[name] = convert_input_string(inputs[name], tval, name)
        elif tb.attr('default') is not None:
            ctx2 = EvalCtx(vars={**default_type_vars(), 'var': values, 'atlas': {'env': atlas_env}}, functions=fns, filename=body.filename)
            dv = eval_expr(tb.attr('default').expr, ctx2)
            try:
                values[name] = convert_to_type(dv, tval)
            except Exception:
                values[name] = dv
        else:
            raise AtlasError(f'missing value for required variable "{name}"')
    return values

class LazyLocals(dict):
    pass

def resolve_locals(body, var_values, atlas_env='', allow_getenv=False, extra_functions=None, type_vars_extra=None):
    locals_blocks = body.blocks_of('locals')
    if not locals_blocks: return None
    exprs = {}
    for blk in locals_blocks:
        for a in blk.body.attr_list:
            exprs[a.name] = a.expr
    fns = default_functions(extra_functions)
    if allow_getenv:
        fns['getenv'] = lambda name: os.environ.get(str(name), '')
    values = {}
    resolving = []
    def resolve_one(name):
        if name in values: return values[name]
        if name in resolving:
            raise AtlasError(f'cyclic reference to "local.{name}"')
        if name not in exprs:
            raise KeyError(name)
        resolving.append(name)
        # local object that lazily resolves via a dict subclass marker: we use a special dict where missing keys resolve in eval_traversal? Our eval only does dict lookup.
        # Build a proxy dict populated on demand: use a custom dict subclass overriding __contains__/getitem.
        class LocalProxy(dict):
            def __contains__(self, k): return k in exprs
            def __getitem__(self, k): return resolve_one(k)
            def get(self, k, d=None):
                return resolve_one(k) if k in exprs else d
        vars_map = {**default_type_vars(), 'var': var_values, 'atlas': {'env': atlas_env}, 'local': LocalProxy()}
        if type_vars_extra: vars_map.update(type_vars_extra)
        ctx = EvalCtx(vars=vars_map, functions=fns, filename=body.filename)
        v = eval_expr(exprs[name], ctx)
        resolving.pop()
        values[name] = v
        return v
    for name in list(exprs.keys()):
        resolve_one(name)
    return values

def get_string_attr(vals, name, struct='*cmdapi.Project'):
    if name not in vals: return ''
    v = vals[name]
    if v is NULL or v is None: return ''
    if not isinstance(v, str):
        raise AtlasError(f'schemahcl: failed reading spec as {struct}: value of attr "{name}" cannot be read as string: string value is required')
    return v

def get_string_list(vals, name, struct='*cmdapi.Project'):
    if name not in vals: return []
    v = vals[name]
    if isinstance(v, str): return [v]
    if isinstance(v, (list,tuple)):
        out = []
        for x in v:
            if not isinstance(x, str):
                raise AtlasError(f'schemahcl: failed reading spec as {struct}: value of attr "{name}" cannot be read as list of string: string value is required')
            out.append(x)
        return out
    raise AtlasError(f'schemahcl: failed reading spec as {struct}: value of attr "{name}" cannot be read as string: string value is required')

def eval_body_values(body, ctx):
    vals = {}
    for a in body.attr_list:
        vals[a.name] = eval_expr(a.expr, ctx)
    # blocks to dicts (first of each type; list if repeated handled by caller if needed)
    blocks = {}
    for b in body.blocks:
        bv = eval_body_values(b.body, ctx)
        if b.labels: bv['_labels'] = b.labels
        if b.type in blocks:
            if isinstance(blocks[b.type], list): blocks[b.type].append(bv)
            else: blocks[b.type] = [blocks[b.type], bv]
        else:
            blocks[b.type] = bv
    vals['_blocks'] = blocks
    return vals

def load_env(config_url, env_name, inputs):
    path = file_path_from_url(config_url, 'config')
    if not os.path.isfile(path):
        raise AtlasError(f'config file "{path}" was not found: stat {path}: no such file or directory')
    src = open(path, 'rb').read().decode('utf-8', 'replace')
    fname = os.path.basename(path)
    body = parse_hcl(src, fname)
    return select_env(body, env_name, inputs, fname)

def select_env(body, env_name, inputs, fname='atlas.hcl'):
    var_values = resolve_variables(body, inputs, allow_getenv=True, atlas_env=env_name)
    locals_values = resolve_locals(body, var_values, atlas_env=env_name, allow_getenv=True)
    env_blocks = body.blocks_of('env')
    matches = [b for b in env_blocks if b.labels and b.labels[0] == env_name]
    if len(matches) > 1:
        raise AtlasError(f'multiple envs found for "{env_name}"')
    chosen = None
    if matches:
        chosen = matches[0]
    else:
        # dynamic env
        for b in env_blocks:
            if not b.labels:
                na = b.body.attr('name')
                if na is not None and isinstance(na.expr, Traversal) and na.expr.parts == ['atlas','env']:
                    chosen = b; break
    if chosen is None:
        raise AtlasError(f'env "{env_name}" not defined in config file')
    fns = default_functions(); fns['getenv'] = lambda name: os.environ.get(str(name), '')
    vars_map = {**default_type_vars(), 'var': var_values, 'atlas': {'env': env_name}}
    if locals_values is not None: vars_map['local'] = locals_values
    ctx = EvalCtx(vars=vars_map, functions=fns, filename=fname)
    vals = eval_body_values(chosen.body, ctx)
    env = EnvConfig(); env.name = env_name; env.raw = vals
    env.url = get_string_attr(vals, 'url')
    env.dev = get_string_attr(vals, 'dev')
    if 'src' in vals: env.src = get_string_list(vals, 'src')
    if 'schemas' in vals: env.schemas = get_string_list(vals, 'schemas')
    if 'exclude' in vals: env.exclude = get_string_list(vals, 'exclude')
    mig = vals.get('_blocks', {}).get('migration')
    if isinstance(mig, dict):
        env.migration_dir = get_string_attr(mig, 'dir')
        # field may be format or dir_format
        env.migration_format = get_string_attr(mig, 'format') or get_string_attr(mig, 'dir_format')
        env.revisions_schema = get_string_attr(mig, 'revisions_schema')
    elif isinstance(mig, list) and mig:
        env.migration_dir = get_string_attr(mig[0], 'dir')
    return env
