import re, sqlite3, os
from urllib.parse import urlsplit, parse_qsl, unquote
from errors import AtlasError

KNOWN_DRIVERS = {'sqlite','libsql','mysql','mariadb','postgres','postgresql','docker','file'}

class GoURL:
    def __init__(self, raw):
        self.raw = raw or ''
        self.Scheme = ''
        self.Opaque = ''
        self.User = None
        self.Host = ''
        self.Path = ''
        self.RawPath = ''
        self.OmitHost = False
        self.ForceQuery = False
        self.RawQuery = ''
        self.Fragment = ''
        self.RawFragment = ''
        self.Schema = ''
        self.driver = ''
        self._parse()
    def _parse(self):
        s = self.raw
        m = re.match(r'^([A-Za-z][A-Za-z0-9+.\-]*):(.*)$', s, re.S)
        if not m: return
        self.Scheme = m.group(1).lower(); self.driver = self.Scheme
        rest = m.group(2)
        if rest.startswith('//'):
            try:
                u = urlsplit(s)
            except Exception:
                u = None
            if u is not None:
                self.Host = u.netloc.rsplit('@',1)[-1]
                if '@' in u.netloc: self.User = {}
                self.Path = u.path or ''
                self.RawQuery = u.query or ''
                self.Fragment = u.fragment or ''
                if '?' in s.split('#',1)[0] and not self.RawQuery:
                    self.ForceQuery = True
        else:
            self.Opaque = rest
            self.OmitHost = True
        if self.Scheme in ('sqlite','libsql'):
            self.Schema = 'main'; self.driver = 'sqlite'
        elif self.Scheme in ('mysql','mariadb'):
            self.Schema = self.Path.strip('/')
            self.driver = 'mysql'
        elif self.Scheme in ('postgres','postgresql'):
            self.driver = 'postgres'
            q = dict(parse_qsl(self.RawQuery))
            self.Schema = q.get('search_path','') or self.Path.strip('/')
    def query(self):
        return dict(parse_qsl(self.RawQuery, keep_blank_values=True))
    def __str__(self):
        return self.raw
    def to_json_obj(self):
        return {"Scheme": self.Scheme, "Opaque": self.Opaque, "User": self.User, "Host": self.Host, "Path": self.Path,
                "RawPath": self.RawPath, "OmitHost": self.OmitHost, "ForceQuery": self.ForceQuery, "RawQuery": self.RawQuery,
                "Fragment": self.Fragment, "RawFragment": self.RawFragment, "Schema": self.Schema}

def parse_client_url(s, state_context=False):
    """Validates a DB/state URL like Atlas. Returns GoURL. Raises AtlasError (without 'Error:' prefix)."""
    if s is None: s = ''
    if '://' not in s:
        if state_context and os.path.isfile(s) and (s.endswith('.hcl') or s.endswith('.sql')):
            raise AtlasError(f"missing scheme. Did you mean file://{s}?")
        raise AtlasError("missing scheme. See: https://atlasgo.io/url")
    # invalid url escape in authority
    auth = s.split('://',1)[1]
    auth_end = len(auth)
    for ch in '/?#':
        idx = auth.find(ch)
        if idx >= 0: auth_end = min(auth_end, idx)
    authority = auth[:auth_end]
    idx = authority.find('%')
    if idx >= 0:
        esc = authority[idx:idx+3]
        raise AtlasError(f'invalid URL escape "{esc}"')
    # invalid port
    hostport = authority.rsplit('@',1)[-1]
    if ':' in hostport:
        # handle ipv6 [..]:port roughly skip
        if hostport.startswith('['):
            after = hostport.rsplit(']',1)[-1]
            if after.startswith(':'):
                port = after[1:]
                if port and not port.isdigit():
                    raise AtlasError(f'invalid port ":{port}" after host')
        else:
            port = hostport.rsplit(':',1)[1]
            if port and not port.isdigit():
                raise AtlasError(f'invalid port ":{port}" after host')
    u = GoURL(s)
    return u

def check_driver(u):
    if u.Scheme not in KNOWN_DRIVERS:
        raise AtlasError(f'sql/sqlclient: unknown driver "{u.Scheme}". See: https://atlasgo.io/url')
    return u

def sqlite_path_from_url(u):
    s = u.raw
    rest = s.split('://',1)[1] if '://' in s else ''
    # strip query/fragment for path determination
    rest_nq = rest.split('?',1)[0].split('#',1)[0]
    q = u.query()
    if q.get('mode') == 'memory':
        return ':memory:'
    if rest_nq.startswith('file:'):
        path = rest_nq[len('file:'):]
    else:
        path = rest_nq
    path = unquote(path)
    if path in ('', ':memory:'):
        return ':memory:'
    return path

def open_sqlite(url_str, state_context=False):
    u = check_driver(parse_client_url(url_str, state_context=state_context))
    if u.Scheme == 'file':
        return u, None  # caller handles file state
    if u.Scheme == 'docker':
        _docker_error(u.raw)
    if u.Scheme in ('mysql','mariadb'):
        raise AtlasError('mysql: query system variables: dial tcp 127.0.0.1:3306: connect: connection refused' if not u.Host else _mysql_error(u))
    if u.Scheme in ('postgres','postgresql'):
        raise AtlasError(_postgres_error(u))
    if u.Scheme == 'libsql' and u.Host and ('.' in u.Host or u.Host not in ('',)):
        pass
    if u.Scheme not in ('sqlite','libsql'):
        check_driver(u)
    path = sqlite_path_from_url(u) if u.Scheme == 'sqlite' else ':memory:'
    if u.Scheme == 'libsql':
        # libsql+file style not in scope; treat host as file path if looks like file, else memory/error approximated by caller paths
        path = sqlite_path_from_url(u)
    try:
        con = sqlite3.connect(path)
    except sqlite3.OperationalError as e:
        raise AtlasError(f"sqlite: querying schemas: unable to open database file: no such file or directory")
    con.isolation_level = None  # autocommit; explicit BEGIN where needed
    return u, con

def _docker_error(raw):
    # docker://<image>/<...> supported images mysql/mariadb/postgres/sqlite? observed sqlite unsupported
    rest = raw.split('://',1)[1] if '://' in raw else ''
    img = rest.split('/',1)[0]
    if img not in ('mysql','mariadb','postgres'):
        raise AtlasError(f'unsupported docker image "{img}"')
    raise AtlasError('exec: "docker": executable file not found in $PATH')

def _mysql_error(u):
    host = u.Host or '127.0.0.1:3306'
    # crude: if host has no port and is not localhost/127..., DNS lookup error form is environment dependent; use connection refused for localhost
    h = host.split(':')[0]
    if h in ('localhost','127.0.0.1','::1'):
        return f'mysql: query system variables: dial tcp {host if ":" in host else host+":3306"}: connect: connection refused'
    return f'mysql: query system variables: dial tcp: lookup {h} on 10.0.0.2:53: dial udp 10.0.0.2:53: connect: network is unreachable'

def _postgres_error(u):
    if not u.Host and not u.Path:
        return f'postgres: scanning system variables: missing "=" after "{u.Scheme}:" in connection info string"'
    h = (u.Host or '').split(':')[0]
    if h in ('localhost','127.0.0.1'):
        return 'postgres: scanning system variables: dial tcp 127.0.0.1:5432: connect: connection refused'
    return f'postgres: scanning system variables: dial tcp: lookup {h} on 10.0.0.2:53: dial udp 10.0.0.2:53: connect: network is unreachable'
