from sqlparse import sql_tokens

def _split(sql, trigger_aware):
    toks = sql_tokens(sql)
    stmts = []
    cur = []
    def flush(semi=None):
        nonlocal cur
        if cur:
            start = cur[0].start
            end = semi.end if semi is not None else cur[-1].end
            stmts.append(sql[start:end])
        cur = []
    i = 0
    in_trigger = False
    trigger_depth = 0  # case/begin nesting after trigger BEGIN
    seen_begin = False
    while i < len(toks):
        t = toks[i]
        if t.text == ';':
            if trigger_aware and in_trigger and seen_begin and trigger_depth > 0:
                cur.append(t); i += 1; continue
            if trigger_aware and in_trigger and not seen_begin:
                cur.append(t); i += 1; continue
            flush(semi=t)
            in_trigger = False; seen_begin = False; trigger_depth = 0
            i += 1; continue
        cur.append(t)
        w = t.word()
        if trigger_aware:
            # detect CREATE [TEMP|TEMPORARY] TRIGGER at statement start
            if not in_trigger:
                words = [x.word() for x in cur if x.kind == 'word']
