import os, re, hashlib, base64
from errors import AtlasError
from stmts import split_statements_exec, split_statements_generic

FORMATS = {'atlas','flyway','liquibase','goose','golang-migrate','dbmate'}

class MigFile:
    def __init__(self, name, path, content, version, description):
        self.name = name; self.path = path; self.content = content
        self.version = version; self.description = description

class MigDir:
    def __init__(self, path, fmt='atlas', query=None):
        self.path = path; self.fmt = fmt; self.query = query or {}
    def files(self):
        if self.fmt not in FORMATS:
            raise AtlasError(f'unknown dir format "{self.fmt}"')
        if not os.path.isdir(self.path): return []
        names = sorted([n for n in os.listdir(self.path) if os.path.isfile(os.path.join(self.path,n))])
        out = []
        for n in names:
            parsed = parse_filename(n, self.fmt)
            if parsed is None: continue
            version, desc = parsed
            content = open(os.path.join(self.path,n),'rb').read()
            out.append(MigFile(n, os.path.join(self.path,n), content, version, desc))
        if self.fmt == 'flyway':
            _flyway_postprocess(out)
        return out

def parse_filename(name, fmt):
    if fmt == 'golang-migrate':
        if not name.endswith('.up.sql'): return None
        stem = name[:-len('.up.sql')]
        return _split_ver(stem)
    if fmt == 'flyway':
        m = re.match(r'^V(.+)__(.*)\.sql$', name)
        if m: return (m.group(1), m.group(2))
        m = re.match(r'^R__(.*)\.sql$', name)
        if m: return ('', m.group(1))
        if name.startswith('U'): return None
        return None
    # atlas-like
    if not name.endswith('.sql'): return None
    if name == 'atlas.sum': return None
    stem = name[:-4]
    return _split_ver(stem)

def _split_ver(stem):
    if '_' in stem:
        v, d = stem.split('_',1)
        return v, d
    return stem, ''

def _flyway_postprocess(files):
    lastver = ''
    for f in files:
        if f.name.startswith('V'): lastver = f.version
    for f in files:
        if f.name.startswith('R__'):
            f.version = f"{lastver}R" if lastver else 'R'

def parse_dir_url(url, fmt_flag='', env_fmt=''):
    if url is None: url = 'file://migrations'
    query = {}
    if url.startswith('file://'):
        rest = url[len('file://'):]
    elif url.startswith('file:'):
        rest = url[len('file:'):]
    elif '://' in url:
        scheme = url.split('://',1)[0]
        raise AtlasError(f'unsupported driver "{scheme}"')
    else:
        raise AtlasError(f'missing scheme for dir url. Did you mean "file://{url}"? ')
    if '?' in rest:
        path, qs = rest.split('?',1)
        for part in qs.split('&'):
            if '=' in part:
                k,v = part.split('=',1); query[k]=v
            elif part: query[part]=''
    else:
        path = rest
    fmt = query.get('format') or fmt_flag or env_fmt or 'atlas'
    return MigDir(path, fmt, query)

def open_dir(url, fmt_flag='', env_fmt='', create=False):
    d = parse_dir_url(url, fmt_flag, env_fmt)
    if d.fmt not in FORMATS:
        raise AtlasError(f'unknown dir format "{d.fmt}"')
    if create:
        os.makedirs(d.path, exist_ok=True)
    if not os.path.isdir(d.path):
        raise AtlasError(f"sql/migrate: stat {d.path}: no such file or directory")
    return d

def file_content_text(f):
    return f.content.decode('utf-8','replace') if isinstance(f.content, bytes) else f.content

def extract_up(sql, fmt):
    if fmt == 'goose':
        return _section(sql, r'--\s*\+goose\s+Up\b', r'--\s*\+goose\s+Down\b')
    if fmt == 'dbmate':
        return _section(sql, r'--\s*migrate:up\b', r'--\s*migrate:down\b')
    return sql

def _section(sql, start_pat, end_pat):
    lines = sql.splitlines(True)
    out = []; inside = False; found = False
    for line in lines:
        if not inside and re.search(start_pat, line, re.I):
            inside = True; found = True; continue
        if inside and re.search(end_pat, line, re.I):
            break
        if inside: out.append(line)
    return ''.join(out) if found else sql

def file_statements(f, fmt, generic=False):
    text = extract_up(file_content_text(f), fmt)
    # strip atlas directive comment lines at top (they are comments so splitter already skips empty)
    if generic:
        return split_statements_generic(text)
    return split_statements_exec(text)

def directives_of(f):
    text = file_content_text(f)
    dirs = {}
    for line in text.splitlines():
        m = re.match(r'\s*--\s*atlas:([A-Za-z0-9_-]+)(?:\s+(.*))?$', line)
        if m: dirs[m.group(1)] = (m.group(2) or '').strip()
        elif line.strip() == '': continue
        elif line.lstrip().startswith('--'): continue
        else: break
    return dirs

def compute_hashes(files):
    """files: list MigFile sorted by name. Returns (total_b64, [(name,b64),...])"""
    h = hashlib.sha256()
    entries = []
    for f in sorted(files, key=lambda x: x.name):
        h.update(f.name.encode())
        h.update(f.content if isinstance(f.content, bytes) else f.content.encode())
        b64 = base64.b64encode(h.copy().digest()).decode()
        entries.append((f.name, b64))
    th = hashlib.sha256()
    for name, b64 in entries:
        th.update(name.encode()); th.update(b64.encode())
    total = base64.b64encode(th.digest()).decode()
    return total, entries

def sum_file_content(files):
    total, entries = compute_hashes(files)
    lines = [f"h1:{total}"] + [f"{n} h1:{b}" for n,b in entries]
    return '\n'.join(lines) + '\n'

def write_hash(d):
    files = d.files()
    content = sum_file_content(files)
    with open(os.path.join(d.path, 'atlas.sum'), 'w') as fh:
        fh.write(content)
    return content

class ChecksumError(Exception):
    def __init__(self, kind, detail=None):
        self.kind = kind  # 'notfound' or 'mismatch'
        self.detail = detail  # (line, filename, action)

def validate_hash(d):
    files = d.files()
    sumpath = os.path.join(d.path, 'atlas.sum')
    if not os.path.exists(sumpath):
        if not files:
            return
        raise ChecksumError('notfound')
    actual_content = sum_file_content(files)
    existing = open(sumpath).read()
    if existing == actual_content:
        return
    detail = _diagnose(files, existing)
    raise ChecksumError('mismatch', detail)

def _diagnose(files, existing):
    lines = existing.splitlines()
    if not lines: return None
    m = re.fullmatch(r'h1:([A-Za-z0-9+/=]+)', lines[0].strip()) if False else None
    # parse entries
    entries = []
    for line in lines[1:]:
        if not line.strip(): continue
        mm = re.match(r'^(.+)\s+h1:(\S+)$', line)
        if not mm: return None
        entries.append((mm.group(1), mm.group(2)))
    # internal consistency total
    if not lines[0].startswith('h1:'): return None
    total_given = lines[0][3:].strip()
    th = hashlib.sha256()
    for n,b in entries: th.update(n.encode()); th.update(b.encode())
    if base64.b64encode(th.digest()).decode() != total_given:
        return None
    _, actual_entries = compute_hashes(files)
    actual_map = dict(actual_entries); existing_map = dict(entries)
    # walk aligned
    n = max(len(entries), len(actual_entries))
    for i in range(n):
        if i >= len(actual_entries):
            return (i+2, entries[i][0], 'removed')
        if i >= len(entries):
            return (i+2, actual_entries[i][0], 'added')
        en, eh = entries[i]; an, ah = actual_entries[i]
        if en == an:
            if eh != ah: return (i+2, en, 'edited')
            continue
        # names differ
        if en not in actual_map:
            return (i+2, en, 'removed')
        if an not in existing_map:
            return (i+2, an, 'added')
        # reorder elsewhere: no detail
        return None
    return None
