    def require(self, kind):
        if not self.url:
            if kind == 'sql':
                raise AtlasError("--dev-url cannot be empty. See: https://atlasgo.io/atlas-schema/sql#dev-database")
            raise AtlasError("--dev-url cannot be empty")
