        con = self.open()
        con.execute("PRAGMA foreign_keys=off")
        rows = con.execute("SELECT type,name FROM sqlite_master WHERE name NOT LIKE 'sqlite_%'").fetchall()
        for typ, name in rows:
            if typ == 'table': con.execute(f'DROP TABLE IF EXISTS "{name.replace(chr(34),chr(34)+chr(34))}"')
            elif typ == 'view': con.execute(f'DROP VIEW IF EXISTS "{name.replace(chr(34),chr(34)+chr(34))}"')
