import re, json
from schemamarshal import go_json

_counter = [0xC000000000]
def fake_addr():
    _counter[0] += 0x110
    return "0x%x" % _counter[0]

class GoStruct:
    def __init__(self, go_type, fields=None, methods=None, json_obj=None, stringer=None, embedded=None, sharp_fields=None):
        self.go_type = go_type
        self.fields = fields or {}
        self.methods = methods or {}
        self.json_obj = json_obj
        self.stringer = stringer
        self.embedded = embedded or []  # list GoStruct whose fields promote
        self.sharp_fields = sharp_fields  # list (name,value representation already object)
        self.addr = fake_addr()
    def lookup_field(self, name):
        if name in self.fields: return self.fields[name]
        for e in self.embedded:
            try: return e.lookup_field(name)
            except KeyError: pass
        raise KeyError(name)
    def has_field(self, name):
        try:
            self.lookup_field(name); return True
        except KeyError:
            return False

class GoMethodError(Exception): pass
class FunctionTypeError(Exception):
    def __init__(self, msg, arg_index=0):
        super().__init__(msg); self.arg_index = arg_index
class TemplateParseError(Exception):
    def __init__(self, line, msg):
        super().__init__(msg); self.line = line; self.msg = msg
class TemplateExecError(Exception):
    def __init__(self, line, col, context, msg):
        super().__init__(msg); self.line=line; self.col=col; self.context=context; self.msg=msg

