    if isinstance(v, GoStruct): return v.go_type
    if isinstance(v, bool): return 'bool'
    if isinstance(v, str): return 'string'
    if isinstance(v, int): return 'int'
    if isinstance(v, float): return 'float64'
    if isinstance(v, list): return '[]interface {}'
    if isinstance(v, dict): return 'map[string]interface {}'
    if v is None: return 'interface {}'
    # custom wrapper objects may define go_type
    return getattr(v, 'go_type', type(v).__name__)

def format_value(v, mode='v'):
    # mode v, +v, #v roughly
    if v is None:
        return '<nil>' if mode == '#v' else '<no value>'
    if isinstance(v, bool): return 'true' if v else 'false'
    if isinstance(v, str):
        if mode == '#v': return go_quote(v)
        return v
    if isinstance(v, (int,float)):
