class Tok:
    def __init__(self, kind, text, pos):
        self.kind=kind; self.text=text; self.pos=pos

def lex_action(s, base):
    toks=[]; i=0; n=len(s)
    while i<n:
        c=s[i]
        if c in ' \t\r\n': i+=1; continue
        start=base+i
        if c=='"':
            j=i+1
            while j<n:
                if s[j]=='\\': j+=2; continue
                if s[j]=='"': j+=1; break
                j+=1
            toks.append(Tok('STRING', s[i:j], start)); i=j; continue
        if c=='`':
            j=s.find('`', i+1); j=n if j<0 else j+1
            toks.append(Tok('RAWSTRING', s[i:j], start)); i=j; continue
        if c=="'":
            j=i+1
            while j<n:
                if s[j]=='\\': j+=2; continue
                if s[j]=="'": j+=1; break
                j+=1
            toks.append(Tok('CHAR', s[i:j], start)); i=j; continue
        if s.startswith(':=',i): toks.append(Tok('DEFINE',':=',start)); i+=2; continue
        if c in '|,()=':
            toks.append(Tok(c,c,start)); i+=1; continue
        if c=='$':
            j=i+1
            while j<n and (s[j].isalnum() or s[j]=='_'): j+=1
            # field chain after var
            while j<n and s[j]=='.':
                j+=1
                while j<n and (s[j].isalnum() or s[j]=='_'): j+=1
            toks.append(Tok('VAR', s[i:j], start)); i=j; continue
        if c=='.':
            j=i
            # .Field.0.Field or just .
            j+=1
            while j<n and (s[j].isalnum() or s[j]=='_'): j+=1
            while j<n and s[j]=='.':
                j+=1
                while j<n and (s[j].isalnum() or s[j]=='_'): j+=1
            toks.append(Tok('FIELD', s[i:j], start)); i=j; continue
        if c.isdigit() or (c=='-' and i+1<n and s[i+1].isdigit()):
            j=i
            if s[j]=='-': j+=1
            dot=False
            while j<n and (s[j].isdigit() or s[j] in '.eE+-xXoObBa-fA-F'):
                j+=1
            toks.append(Tok('NUMBER', s[i:j], start)); i=j; continue
        if c.isalpha() or c=='_':
            j=i
            while j<n and (s[j].isalnum() or s[j]=='_'): j+=1
            toks.append(Tok('IDENT', s[i:j], start)); i=j; continue
        toks.append(Tok('ERR', c, start)); i+=1
    toks.append(Tok('EOF','',base+n))
    return toks

# AST nodes as dicts/tuples classes
class Node: pass
class Text(Node):
    def __init__(self,text): self.text=text
class Action(Node):
    def __init__(self,pipe,pos,line): self.pipe=pipe; self.pos=pos; self.line=line
class If(Node):
    def __init__(self,pipe,body,els,pos,line): self.pipe=pipe; self.body=body; self.els=els; self.pos=pos; self.line=line
class Range(Node):
    def __init__(self,pipe,body,els,pos,line): self.pipe=pipe; self.body=body; self.els=els; self.pos=pos; self.line=line
class With(Node):
    def __init__(self,pipe,body,els,pos,line): self.pipe=pipe; self.body=body; self.els=els; self.pos=pos; self.line=line
class Pipeline:
    def __init__(self, cmds, decl=None, assign=None):
        self.cmds=cmds; self.decl=decl or []; self.assign=assign or []
class Command:
    def __init__(self, terms, pos):
        self.terms=terms; self.pos=pos
class Term:
    def __init__(self,kind,text,pos,sub=None):
        self.kind=kind; self.text=text; self.pos=pos; self.sub=sub
    def __repr__(self): return self.text

