import datetime as _dt
class GoTime:
    go_type = 'time.Time'
    def __init__(self, dt=None):
        self.dt = dt or _dt.datetime.now(_dt.timezone.utc)
    def rfc3339nano(self):
        d=self.dt.astimezone(_dt.timezone.utc)
        base=d.strftime('%Y-%m-%dT%H:%M:%S')
        frac=f"{d.microsecond*1000:09d}".rstrip('0')
        return base+('.'+frac if frac else '')+'Z'
    def db_string(self):
        d=self.dt.astimezone(_dt.timezone.utc)
        base=d.strftime('%Y-%m-%d %H:%M:%S')
        frac=f"{d.microsecond*1000:09d}".rstrip('0')
        return base+('.'+frac if frac else '')+'+00:00'
    def __str__(self):
        d=self.dt.astimezone(_dt.timezone.utc)
        base=d.strftime('%Y-%m-%d %H:%M:%S')
        frac=f"{d.microsecond*1000:09d}".rstrip('0')
        return base+('.'+frac if frac else '')+' +0000 UTC'
    def to_json_obj(self):
        return self.rfc3339nano()
    def go_string(self): return str(self)

class GoDuration:
    go_type='time.Duration'
    def __init__(self,ns=0): self.ns=int(ns)
    def __int__(self): return self.ns
    def __str__(self): return format_go_duration(self.ns)
    def to_json_obj(self): return self.ns
    def go_string(self): return str(self)

def format_go_duration(ns):
    ns=int(ns)
    if ns==0: return '0s'
    sign='-' if ns<0 else ''
    d=abs(ns)
    if d<1000: return f"{sign}{d}ns"
    if d<1000000:
        whole=d//1000; frac=d%1000
        return f"{sign}{whole}"+(f".{frac:03d}".rstrip('0') if frac else '')+'µs'
    if d<1000000000:
        whole=d//1000000; frac=d%1000000
        return f"{sign}{whole}"+(f".{frac:06d}".rstrip('0') if frac else '')+'ms'
    total_seconds=d//1000000000; frac=d%1000000000
    frac_s=(f".{frac:09d}".rstrip('0') if frac else '')
    if total_seconds<60:
        return f"{sign}{total_seconds}{frac_s}s"
    if total_seconds<3600:
        m=total_seconds//60; s=total_seconds%60
        return f"{sign}{m}m{s}{frac_s}s"
    h=total_seconds//3600; rem=total_seconds%3600; m=rem//60; s=rem%60
