class RevisionType:
    go_type='migrate.RevisionType'
    def __init__(self, v, name):
        self.v=v; self.name=name
    def go_string(self): return self.name
    def sharp_repr(self): return hex(self.v)
    def to_json_obj(self): return self.name
    def __str__(self): return self.name

def env_struct(driver, url_obj, dir_str=''):
    e=GoStruct('cmdlog.Env', fields={'Driver':driver,'URL':url_obj,'Dir':dir_str})
    ej={}
    if driver: ej['Driver']=driver
    if url_obj is not None: ej['URL']=url_obj
    if dir_str: ej['Dir']=dir_str
    e.json_obj=ej
    return e

def realm_struct(realm):
    # Build with back refs
    realm_s=GoStruct('*schema.Realm', fields={'Schemas':[]})
    realm_s.sharp_fields=[('Schemas', realm_s.fields['Schemas'])]
    schemas=[]
    for sch in realm.schemas:
        ss=GoStruct('*schema.Schema', fields={'Name':sch.name,'Realm':realm_s,'Tables':[]})
        tables=[]
        for t in sch.tables:
            ts=GoStruct('*schema.Table', fields={'Name':t.name,'Schema':ss,'Columns':[],'Indexes':[],'PrimaryKey':None,'ForeignKeys':[]})
            cols=[]
            col_by_name={}
            for c in t.columns:
                type_s=GoStruct('schema.ColumnType', fields={'Type':c.raw_type,'Raw':c.raw_type,'Null':c.null}, stringer=c.raw_type)
                cs=GoStruct('*schema.Column', fields={'Name':c.name,'Type':type_s,'Default':None,'Attrs':[]})
                cols.append(cs); col_by_name[c.name]=cs
            ts.fields['Columns']=cols
            if t.primary_key is not None:
                ts.fields['PrimaryKey']=GoStruct('*schema.Index', fields={'Parts':[GoStruct('*schema.IndexPart', fields={'Column':col_by_name.get(p.column),'X':None}) for p in t.primary_key.parts],'Unique':True,'Table':ts})
            idxs=[]
            for idx in t.indexes:
                parts=[]
                for p in idx.parts:
                    parts.append(GoStruct('*schema.IndexPart', fields={'Column':col_by_name.get(p.column) if p.column else None,'X':p.expr,'Desc':p.desc}))
                idxs.append(GoStruct('*schema.Index', fields={'Name':idx.name,'Unique':idx.unique,'Table':ts,'Parts':parts}))
            ts.fields['Indexes']=idxs
            fks=[]
            for fk in t.foreign_keys:
                fks.append(GoStruct('*schema.ForeignKey', fields={'Name':fk.name,'Table':ts,'Columns':[col_by_name.get(c) for c in fk.columns],'RefTable':fk.ref_table,'RefColumns':fk.ref_columns,'OnUpdate':fk.on_update,'OnDelete':fk.on_delete}))
            ts.fields['ForeignKeys']=fks
            tables.append(ts)
        ss.fields['Tables']=tables
        schemas.append(ss)
    realm_s.fields['Schemas']=schemas
    realm_s.sharp_fields=[('Schemas',schemas),('Objects',[]),('Attrs',[])]
    return realm_s

