                cols.append(cs); col_by_name[c.name]=cs
            ts.fields['Columns']=cols
            if t.primary_key is not None:
                ts.fields['PrimaryKey']=GoStruct('*schema.Index', fields={'Parts':[GoStruct('*schema.IndexPart', fields={'Column':col_by_name.get(p.column),'X':None}) for p in t.primary_key.parts],'Unique':True,'Table':ts})
            idxs=[]
            for idx in t.indexes:
                parts=[]
                for p in idx.parts:
                    parts.append(GoStruct('*schema.IndexPart', fields={'Column':col_by_name.get(p.column) if p.column else None,'X':p.expr,'Desc':p.desc}))
