import csv, io, re
from errors import AtlasError

class Flag:
    def __init__(self,name,short='',typ='string',default=None,hidden=False):
        self.name=name; self.short=short; self.typ=typ; self.default=default; self.hidden=hidden

class Parsed:
    def __init__(self, specs):
        self.values={}
        self.changed=set()
        for f in specs:
            if f.typ=='bool': self.values[f.name]=False if f.default is None else f.default
            elif f.typ in ('strings','var'): self.values[f.name]=list(f.default) if f.default else []
            elif f.typ=='uint': self.values[f.name]=f.default or 0
            else: self.values[f.name]=f.default if f.default is not None else ''
        self.args=[]
    def get(self,name): return self.values.get(name)
    def is_set(self,name): return name in self.changed
    def set_default_from_env(self,name,value):
        if name not in self.changed and value:
            self.values[name]=value; self.changed.add(name)

def _csv_split(val):
    if val=='':
        return []
    try:
        r=list(csv.reader(io.StringIO(val)))
        return r[0] if r else []
    except Exception as e:
        raise AtlasError(str(e))

def parse_duration_ns(s):
    orig=s
    if s=='0': return 0
    if not s:
        raise ValueError(f'invalid duration "{orig}"')
    neg=False
    if s[0] in '+-':
        neg=s[0]=='-'; s=s[1:]
    if not s:
        raise ValueError(f'invalid duration "{orig}"')
    units={'ns':1,'us':1000,'µs':1000,'μs':1000,'ms':1000000,'s':1000000000,'m':60000000000,'h':3600000000000}
    total=0; i=0
    while i<len(s):
        m=re.match(r'(\d+(?:\.\d*)?|\.\d+)',s[i:])
        if not m:
            raise ValueError(f'invalid duration "{orig}"')
        num=m.group(1); i+=len(num)
        m2=re.match(r'[A-Za-zµμ]+',s[i:])
        if not m2:
            raise ValueError(f'missing unit in duration "{orig}"')
        unit=m2.group(0); i+=len(unit)
        if unit not in units:
            raise ValueError(f'unknown unit "{unit}" in duration "{orig}"')
        total+=float(num)*units[unit]
    return -int(total) if neg else int(total)

def _convert(flag, raw, display_name):
    # display_name like --latest (for messages always long name)
    if flag.typ=='string': return raw
    if flag.typ=='bool':
        low=raw.lower()
        if low in ('1','t','true','TRUE','True'.lower()): return True
        if low in ('0','f','false'): return False
        # Go strconv.ParseBool accepts: 1,t,T,TRUE,true,True,0,f,F,FALSE,false,False
        if raw in ('T','TRUE','True'): return True
        if raw in ('F','FALSE','False'): return False
        raise AtlasError(f'invalid argument "{raw}" for "--{flag.name}" flag: strconv.ParseBool: parsing "{raw}": invalid syntax')
    if flag.typ=='strings': return _csv_split(raw)
    if flag.typ=='var':
        vals=_csv_split(raw) if False else [raw]
        # var flag in Atlas is a custom pflag Value; go through values after csv? --var supports comma? If raw contains comma, variables may split? Original implementation likely uses custom slice type that splits comma. We'll split csv and validate each.
        vals=_csv_split(raw) if ',' in raw and '=' in raw.split(',',1)[0] else [raw]
        out=[]
        for v in vals:
            if '=' not in v:
                raise AtlasError(f'invalid argument "{raw}" for "--var" flag: variables must be format as key=value, got: "{raw}"')
            out.append(v)
        return out
    if flag.typ=='duration':
        try:
            parse_duration_ns(raw)
        except ValueError as e:
            # messages: time: invalid duration "abc" / time: missing unit...
            msg=str(e)
            if msg.startswith('invalid') or msg.startswith('missing') or msg.startswith('unknown'):
                msg='time: '+msg
            raise AtlasError(f'invalid argument "{raw}" for "--{flag.name}" flag: {msg}')
        return raw
    if flag.typ=='uint':
        try:
            if raw.startswith('-') or raw.startswith('+'):
                # Go ParseUint accepts leading + ? docs: + sign accepted. - invalid
                if raw.startswith('-'): raise ValueError()
            if raw.lower().startswith('0x') or raw.lower().startswith('+0x'):
                v=int(raw,16)
            else:
                if not re.fullmatch(r'\+?\d+',raw): raise ValueError()
                v=int(raw)
            if v<0 or v>2**64-1:
                raise AtlasError(f'invalid argument "{raw}" for "--{flag.name}" flag: strconv.ParseUint: parsing "{raw}": value out of range')
            return v
        except AtlasError: raise
        except Exception:
            raise AtlasError(f'invalid argument "{raw}" for "--{flag.name}" flag: strconv.ParseUint: parsing "{raw}": invalid syntax')
    return raw

def parse_flags(argv, specs):
    by_long={f.name:f for f in specs}
    by_short={f.short:f for f in specs if f.short}
    # help always
    parsed=Parsed(specs)
    args=[]
    i=0; stopped=False
    def add_value(flag, raw):
        v=_convert(flag,raw,flag.name)
        if flag.typ in ('strings','var'):
            parsed.values[flag.name].extend(v)
        else:
            parsed.values[flag.name]=v
        parsed.changed.add(flag.name)
    while i<len(argv):
        tok=argv[i]
        if stopped or tok=='-' or not tok.startswith('-') or tok=='':
            args.append(tok); i+=1; continue
        if tok=='--':
            stopped=True; i+=1; continue
        if tok.startswith('--'):
            body=tok[2:]
            if '=' in body:
                name,raw=body.split('=',1); has_raw=True
            else:
                name,raw=body,None; has_raw=False
            f=by_long.get(name)
            if f is None:
                raise AtlasError(f'unknown flag: --{name}')
            if f.typ=='bool':
                if has_raw: add_value(f,raw)
                else: parsed.values[f.name]=True; parsed.changed.add(f.name)
                i+=1; continue
            if not has_raw:
                if i+1>=len(argv):
                    raise AtlasError(f'flag needs an argument: --{name}')
                raw=argv[i+1]; i+=2
            else:
                i+=1
            add_value(f,raw); continue
        # shorthand cluster
        body=tok[1:]
        j=0
        consumed_next=False
        while j<len(body):
            ch=body[j]
            f=by_short.get(ch)
            if f is None:
                raise AtlasError(f"unknown shorthand flag: '{ch}' in -{body}")
            if f.typ=='bool':
                # -b=true possible
                if j+1<len(body) and body[j+1]=='=':
                    add_value(f,body[j+2:]); j=len(body)
                else:
                    parsed.values[f.name]=True; parsed.changed.add(f.name); j+=1
                continue
            # non-bool consumes rest or next
            if j+1<len(body):
                rest=body[j+1:]
                if rest.startswith('='): rest=rest[1:]
                add_value(f,rest); j=len(body)
            else:
                if i+1>=len(argv):
                    raise AtlasError(f"flag needs an argument: '{ch}' in -{body}")
                add_value(f,argv[i+1]); consumed_next=True; j=len(body)
        i+=2 if consumed_next else 1
    parsed.args=args
    return parsed

def check_required(parsed, required):
    missing=[r for r in required if r not in parsed.changed or parsed.values.get(r) in ('',[],None)]
    # Cobra: a flag set to empty string is considered set? It checks Changed only. If --url '' it is changed so required passes then missing scheme. Use changed only.
    missing=[r for r in required if r not in parsed.changed]
    if missing:
        lst=', '.join(f'"{m}"' for m in missing)
        raise AtlasError(f'required flag(s) {lst} not set')

def check_groups(parsed, groups):
    for group in groups:
        is_set=[g for g in group if g in parsed.changed]
        if len(is_set)>1:
            set_sorted=sorted(is_set)
            raise AtlasError(f"if any flags in the group [{' '.join(group)}] are set none of the others can be; [{' '.join(set_sorted)}] were all set")
