def _home():
    try:
        return os.path.expanduser('~')
    except Exception:
        return ''

def _now_rfc3339nano():
    now = datetime.datetime.now(datetime.timezone.utc)
    base = now.strftime('%Y-%m-%dT%H:%M:%S')
    frac = f"{now.microsecond*1000:09d}".rstrip('0')
    return base + ('.'+frac if frac else '') + 'Z'

def _parse_ts(s):
    # Go time JSON parsing RFC3339Nano
    if not isinstance(s,str): raise ValueError()
    t=s
    if t.endswith('Z'): t=t[:-1]+'+00:00'
    dt=datetime.datetime.fromisoformat(t)
    if dt.tzinfo is None: raise ValueError()
    return dt

def _should(fname, key, interval_days):
    home=_home()
    if not home: return False
    path=os.path.join(home,'.atlas',fname)
    if os.path.exists(path):
        try:
            data=json.load(open(path))
            if key not in data:
                pass  # zero time => show
            else:
                last=_parse_ts(data[key])
                if datetime.datetime.now(datetime.timezone.utc)-last < datetime.timedelta(days=interval_days):
                    return False
        except Exception:
            return False
    # write
    try:
        os.makedirs(os.path.join(home,'.atlas'),exist_ok=True)
        with open(path,'w') as f:
            json.dump({key:_now_rfc3339nano()},f,separators=(',',':'))
    except Exception:
        pass
    return True

