    msg=f'unknown command "{name}" for "{parent}"'
    if sug:
        if len(sug)==1:
            msg+=f'\n\nDid you mean this?\n\t{sug[0]}\n\nRun \'{parent} --help\' for usage.'
        else:
            msg+='\n\nDid you mean one of these?\n'+'\n'.join('\t'+s for s in sug)+f'\n\nRun \'{parent} --help\' for usage.'
    else:
        msg+=f'\nRun \'{parent} --help\' for usage.'
    raise AtlasError(msg)

def lev(a,b):
    la,lb=len(a),len(b)
    if la==0: return lb
    prev=list(range(lb+1))
    for i in range(1,la+1):
        cur=[i]+[0]*lb
        for j in range(1,lb+1):
            cur[j]=min(prev[j]+1,cur[j-1]+1,prev[j-1]+(0 if a[i-1]==b[j-1] else 1))
        prev=cur
    return prev[lb]

def suggestions(name,candidates):
    out=[]
    for c in candidates:
        if lev(name.lower(),c.lower())<=2 or c.lower().startswith(name.lower()):
