    return out

def resolve_command(argv):
    """returns (path tuple, remaining args list)"""
    if not argv:
        return (),[]
    if argv[0] in ('__complete','__completeNoDesc'):
        return ('__complete',), argv[1:]
    if argv[0]=='help':
