        pos=i; break
    if pos is None:
        return (),argv
    cmd=argv[pos]
    if cmd not in ROOT_COMMANDS:
        unknown_command(cmd)
    prefix=argv[:pos]
    rest=argv[pos+1:]
    if cmd in ('version','license'):
        return (cmd,), prefix+rest
    if cmd=='help':
        return ('help',), rest
    if cmd in GROUPS:
        # scan group flags to find subcommand
        subs=GROUPS[cmd]
        # specs for knowing value flags at this level: persistent plus (for schema/migrate) all subcommand flags could appear after sub - before sub only persistent/help valid in cobra traverse
        value_flags={'--config','-c','--env','--var'}
        j=0; subpos=None
        while j<len(rest):
            t=rest[j]
            if t=='--': break
            if t in ('-h','--help') or t.startswith('--help='):
                return (cmd,), prefix+rest
            if t.startswith('-') and t!='-':
                # determine if this flag consumes a value
                name=t.split('=',1)[0]
                if name in value_flags and '=' not in t:
                    j+=2; continue
                # unknown or bool flag: group command handles it
                if name not in value_flags and not name.startswith('-c'):
                    # let group parse produce unknown flag error (unless it's -cvalue combined)
                    return (cmd,), prefix+rest
                j+=1; continue
            subpos=j; break
        if subpos is None:
            return (cmd,), prefix+rest
        sub=rest[subpos]
        if sub not in subs:
            return (cmd,), prefix+rest
        return (cmd,sub), prefix+rest[:subpos]+rest[subpos+1:]
    return (),argv

