    except HCLError as e:
        sys.stderr.write(f"Error: {e}\n")
        sug=maybe_suggestion()
        if sug: sys.stderr.write(sug)
        sys.exit(1)
    except BrokenPipeError:
        try: sys.stdout.close()
        except Exception: pass
        sys.exit(1)
    except Exception as e:
        # Unexpected errors: print in Atlas style for known sqlite errors fallback
        sys.stderr.write(f"Error: {e}\n")
        sug=maybe_suggestion()
        if sug: sys.stderr.write(sug)
        sys.exit(1)
    if success_cmd in (('schema','inspect'),('schema','diff'),('schema','apply')):
        n=maybe_notice()
        if n: sys.stderr.write(n)
    sys.exit(code or 0)

