        p=parse_flags(args,[F('help','h','bool')])
        # unknown positional handled by resolve; root with -- etc just help
        sys.stdout.write(HELP['root'])
        return 0,None
    if len(path)==1 and path[0] in GROUPS:
        grp=path[0]
        sp=GROUP_SPECS[grp]
        p=parse_flags(args,sp)
        sys.stdout.write(HELP[grp])
        return 0,None
    if path in LEAF_SPECS and path not in COMMANDS:
        return handle_leaf(path,args), None
    # main commands
    import handlers
    code=handlers.run_command(path,args)
    return code,path

