    return [],4

def group_descs(grp):
    # parse group's help Available Commands lines
    out={}
    in_av=False
    for line in HELP[grp].splitlines():
        if line.startswith('Available Commands:'): in_av=True; continue
        if in_av:
            if not line.strip(): break
            m=re.match(r'\s+(\S+)\s+(.*)',line)
            if m: out[m.group(1)]=m.group(2).strip()
    return out

def flag_description(path,flag):
    key=help_key(path) if path else 'root'
    text=HELP.get(key,'')
    for line in text.splitlines():
        # normalize flag token searching for --name or -s,
        name=flag.lstrip('-')
        if flag.startswith('--'):
            if f"--{name}" in line:
                parts=re.split(r'\s{2,}',line.strip())
                return parts[-1].strip() if len(parts)>1 else ''
        else:
            if re.search(rf'(^|\s)-{name},',line):
                parts=re.split(r'\s{2,}',line.strip())
                return parts[-1].strip() if len(parts)>1 else ''
    return ''
