    def sqlfn(*args):
        if len(args)==0:
            raise FunctionTypeError('wrong number of args for sql: want at least 1 got 0',0)
        _check_sql_arg(args[0],data,'*cmdlog.SchemaDiff')
        if any(c.kind=='DropSchema' for c in changes):
            raise GoMethodError('unsupported change *schema.DropSchema')
        indent=str(args[1]) if len(args)>1 else ''
        return render_sql(plan,indent=indent)
    out=execute_template(fmtval,data,{'sql':sqlfn})
    sys.stdout.write(out)
    return 0

# ---------------- apply / clean ----------------
def execute_plan_on_conn(con, plan, tx_mode='file'):
    cmds=[pc.cmd for pc in plan if pc.cmd]
    if tx_mode=='none':
        for c in cmds: con.execute(c)
        return
    # file mode: pragmas outside tx
    in_tx=False
    try:
        for c in cmds:
            if c.startswith('PRAGMA foreign_keys'):
                if in_tx:
                    con.execute('COMMIT'); in_tx=False
                con.execute(c); continue
            if not in_tx:
                con.execute('BEGIN'); in_tx=True
            con.execute(c)
        if in_tx: con.execute('COMMIT')
    except Exception:
        if in_tx:
            try: con.execute('ROLLBACK')
            except Exception: pass
        raise

def prompt_apply():
    return prompt_select()

def prompt_select():
    # Returns True for Apply, False for Abort. Raises AtlasError('^D')/(^C)
    import sys as _sys
    out=_sys.stdout
    initial = "\x1b[?25l\x1b[2K\n\x1b[34m?\x1b[0m Are you sure?: \n\x1b[2K\n  \x1b[1m▸\x1b[0m \x1b[4mApply\x1b[0m\n\x1b[2K\n    Abort\n"
    out.write(initial); out.flush()
    sel=0  # 0 Apply 1 Abort
    # terminal handling
    data=b''
    try:
        import termios, tty
        fd=_sys.stdin.fileno()
        old=termios.tcgetattr(fd)
        tty.setcbreak(fd)
        restore=(fd,old)
    except Exception:
        restore=None
    def cleanup(final=True):
        if restore:
            try:
                import termios; termios.tcsetattr(restore[0],termios.TCSADRAIN,restore[1])
            except Exception: pass
    def redraw():
        # approximate survey redraw on selection change
        if sel==0:
            body="\x1b[34m?\x1b[0m Are you sure?: \x1b[1B\x1b[2K\n  \x1b[1m▸\x1b[0m \x1b[4mApply\x1b[0m\x1b[1B\x1b[2K\n    Abort\x1b[1B"
        else:
            body="\x1b[34m?\x1b[0m Are you sure?: \x1b[1B\x1b[2K\n    Apply\x1b[1B\x1b[2K\n  \x1b[1m▸\x1b[0m \x1b[4mAbort\x1b[0m\x1b[1B"
        out.write("\x1b[1A\x1b[1A\x1b[1A\x1b[2K\n"+body); out.flush()
    def finish(choose=True):
        out.write("\x1b[1A\x1b[2K\n\x1b[1A\x1b[2K\n\x1b[1A\x1b[2K\n\x1b[2K\n")
        if choose:
            label='Apply' if sel==0 else 'Abort'
            out.write(f"\x1b[32m\x1b[32m✔\x1b[0m \x1b[2m{label}\x1b[0m\n")
        out.write("\x1b[?25h"); out.flush()
    try:
        while True:
            ch=_sys.stdin.buffer.read(1)
            if ch==b'' or ch==b'\x04':
                out.write("\x1b[1A\x1b[2K\n\x1b[1A\x1b[2K\n\x1b[1A\x1b[2K\n\x1b[2K\n\x1b[?25h"); out.flush()
                raise AtlasError('^D')
            if ch==b'\x03':
                out.write("\x1b[1A\x1b[2K\n\x1b[1A\x1b[2K\n\x1b[1A\x1b[2K\n\x1b[2K\n\x1b[?25h"); out.flush()
                raise AtlasError('^C')
            if ch in (b'\r',b'\n'):
                finish(True)
                return sel==0
            if ch==b'\x1b':
                seq=_sys.stdin.buffer.read(2)
                if seq==b'[B':
                    if sel!=1: sel=1; redraw()
                elif seq==b'[A':
                    if sel!=0: sel=0; redraw()
                continue
            if ch in (b'j',b'J'):
                if sel!=1: sel=1; redraw()
            elif ch in (b'k',b'K'):
                if sel!=0: sel=0; redraw()
            elif ch==b'\x0e':  # ctrl-n
                if sel!=1: sel=1; redraw()
            elif ch==b'\x10':
                if sel!=0: sel=0; redraw()
            # other input ignored (survey may redraw; approximation)
