def schema_apply_cmd(path,p):
    check_groups(p,[['dry-run','auto-approve'],['log','format'],['file','to'],['edit','plan']])
    # community before required/env
    for flag in ['edit','plan','include']:
        if p.get(flag):
            raise community_abort('schema apply',flag)
    env=load_env_for(p)
    if env:
        set_env_defaults(p,env,{'url':env.url,'dev-url':env.dev,'schema':env.schemas,'exclude':env.exclude})
        if env.src and not p.is_set('to') and not p.is_set('file'):
            p.values['to']=list(env.src); p.changed.add('to')
    check_required(p,['url'])
    if not p.is_set('to') and not p.is_set('file'):
        raise AtlasError('one of flag(s) "file" or "to" is required')
    tx=p.get('tx-mode')
    if tx not in ('none','file'):
        raise AtlasError(f'unknown tx-mode "{tx}"')
    exclude=p.get('exclude') or []
    validate_patterns(exclude)
    fmtval=effective_format(p)
    # parse format early (to match parse error before DB errors in apply)
    early_tmpl=None
    if fmtval:
        from gotmpl import Template as _T
        try:
            early_tmpl=_T(fmtval,name='format',funcs={'json':lambda *a: ''})
        except Exception as e:
            # execute_template-like
            from gotmpl import TemplateParseError
            if isinstance(e,TemplateParseError):
                raise AtlasError(f"parse log format: template: format:{e.line}: {e.msg}")
            raise
    url=p.get('url')
    u,con=open_sqlite(url)
    if con is None:
        raise AtlasError('missing scheme. See: https://atlasgo.io/url')
    try:
        current=filter_realm(inspect_sqlite_conn(con,exclude_patterns=exclude),exclude)
        if p.is_set('file'):
            to_urls=[]
            for f in p.get('file'):
                to_urls.append(f if '://' in f else 'file://'+f)
        else:
            to_urls=p.get('to')
        desired=filter_realm(read_states(to_urls,p.get('dev-url') or '',var_inputs(p),exclude),exclude)
        plan,changes=plan_changes(current,desired)
        drv=u.driver or 'sqlite'
        env_struct=reportmod.env_struct(drv,u,'')
        # output / execution
        applied_plan=[]
        if fmtval:
            if not plan:
                data=reportmod.schema_apply_struct(env_struct,[])
                sys.stdout.write(execute_template(fmtval,data,{'json':lambda *a: go_json_encode(a[0]) if a else ''}))
                return 0
            if p.get('dry-run'):
                data=reportmod.schema_apply_struct(env_struct,plan)
                sys.stdout.write(execute_template(fmtval,data,{'json':lambda *a: go_json_encode(a[0]) if a else ''}))
                return 0
            if not p.get('auto-approve'):
                if not prompt_apply():
                    data=reportmod.schema_apply_struct(env_struct,plan)
                    sys.stdout.write(execute_template(fmtval,data,{'json':lambda *a: go_json_encode(a[0]) if a else ''}))
                    return 0
            try:
                execute_plan_on_conn(con,plan,tx)
                applied_plan=plan
            except sqlite3.Error as e:
                data=reportmod.schema_apply_struct(env_struct,plan)
                # mark error? write template then raise
                try: sys.stdout.write(execute_template(fmtval,data,{'json':lambda *a: go_json_encode(a[0]) if a else ''}))
                except Exception: pass
                raise AtlasError(str(e))
            data=reportmod.schema_apply_struct(env_struct,[],applied_plan=applied_plan)
            sys.stdout.write(execute_template(fmtval,data,{'json':lambda *a: go_json_encode(a[0]) if a else ''}))
            return 0
        # default output
        if not plan:
            sys.stdout.write('Schema is synced, no changes to be made\n')
            return 0
        sys.stdout.write('-- Planned Changes:\n'+render_sql(plan,indent='  '))
        if p.get('dry-run'):
            return 0
        if not p.get('auto-approve'):
            if not prompt_apply():
                return 0
        try:
            execute_plan_on_conn(con,plan,tx)
        except sqlite3.Error as e:
            raise AtlasError(str(e))
        return 0
    finally:
        try: con.close()
        except Exception: pass

def schema_clean_cmd(path,p):
    env=load_env_for(p)
    if env:
        set_env_defaults(p,env,{'url':env.url})
    check_required(p,['url'])
    if p.get('dry-run'):
        raise community_abort('schema clean','dry-run')
    if p.is_set('format'):
        raise community_abort('schema clean','format')
    url=p.get('url')
    u,con=open_sqlite(url)
    if con is None:
        raise AtlasError('missing scheme. See: https://atlasgo.io/url')
    try:
