    if p.is_set('format'): return p.get('format') or ''
    if 'log' in p.values and p.is_set('log'): return p.get('log') or ''
    return p.get('format') or ''

def execute_template(text,data,funcs,parse_prefix='parse log format',exec_prefix=''):
    try:
        tmpl=Template(text,name='format',funcs=funcs or {})
    except TemplateParseError as e:
        raise AtlasError(f"{parse_prefix}: template: format:{e.line}: {e.msg}")
    try:
        return tmpl.execute(data)
    except TemplateExecError as e:
        raise AtlasError(f'{exec_prefix}template: format:{e.line}:{e.col}: executing "format" at <{e.context}>: {e.msg}')

def validate_patterns(patterns):
    for pat in patterns or []:
        validate_glob(pat)

def filter_realm(realm, exclude):
    if not exclude: return realm
    import fnmatch, copy
    r=copy.deepcopy(realm)
    for sch in r.schemas:
        sch.tables=[t for t in sch.tables if not any(fnmatch.fnmatchcase(t.name,pat) for pat in exclude)]
    return r

def run_command(path,args):
    if path[0]=='schema':
        return run_schema(path,args)
    if path[0]=='migrate':
        import migcmd
        return migcmd.run_migrate(path,args)
    return 0

def run_schema(path,args):
    cmd=path[1]
    if cmd=='fmt':
        return schema_fmt(args)
    p=prep(path,args)
    if p is None: return 0
    if cmd=='inspect': return schema_inspect(path,p)
    if cmd=='diff': return schema_diff_cmd(path,p)
    if cmd=='apply': return schema_apply_cmd(path,p)
    if cmd=='clean': return schema_clean_cmd(path,p)
    return 0

