def schema_fmt(args):
    sp=COMMANDS[('schema','fmt')]
    p=parse_flags(args,sp)
    if p.get('help'):
        sys.stdout.write(HELP['schema_fmt']); return 0
    from hclfmt import format_hcl
    paths=p.args if p.args else ['.']
    for path in paths:
        if not os.path.exists(path):
            raise AtlasError(f"stat {path}: no such file or directory")
        files=[]
        if os.path.isdir(path):
            for n in sorted(os.listdir(path)):
                fp=os.path.join(path,n)
                if os.path.isfile(fp) and n.endswith('.hcl'):
                    display=n if path in ('.','./','') else os.path.join(path,n)
                    # filepath.Join cleans ./ prefix
                    if display.startswith('./'): display=display[2:]
                    files.append((fp,display))
        elif os.path.isfile(path):
            if path.endswith('.hcl'):
                files.append((path,path))
        for fp,display in files:
            data=open(fp,'rb').read()
            text=data.decode('utf-8','replace')
            out=format_hcl(text)
            if out!=text:
                open(fp,'w').write(out)
                sys.stdout.write(display+'\n')
    return 0

