def _inspect_json_func(realm,data):
    def fn(*args):
        if len(args)!=1:
            raise FunctionTypeError('wrong number of args for json: want 1 got %d'%len(args),0)
        v=args[0]
        if v is data:
            return go_json(realm_to_json_spec(realm))
        # Realm struct cycle
        from gotmpl import GoStruct
        if isinstance(v,GoStruct) and v.go_type=='*schema.Realm':
            raise GoMethodError('json: unsupported value: encountered a cycle via []*schema.Schema')
        return go_json_encode(v)
    return fn

def _check_sql_arg(v,data,expected):
    if v is not data:
        raise FunctionTypeError(f'wrong type for value; expected {expected}; got {go_type_of(v)}',0)

def _sql_func_for_inspect(realm,data):
