def execute_template(text,data,funcs,parse_prefix='parse log format',exec_prefix=''):
    try:
        tmpl=Template(text,name='format',funcs=funcs or {})
    except TemplateParseError as e:
        raise AtlasError(f"{parse_prefix}: template: format:{e.line}: {e.msg}")
    try:
