import migdir, migrateops, report as reportmod

def prep(path,args):
    p=parse_flags(args,COMMANDS[path])
    if p.get('help'):
        sys.stdout.write(HELP[help_key(path)]); return None
    return p

def load_env_for(p):
    if p.get('env'):
        return load_env(p.get('config'),p.get('env'),var_inputs(p))
    return None

def env_defaults_migrate(p,env):
    if not env: return
    mapping={'url':env.url,'dev-url':env.dev}
    set_env_defaults(p,env,mapping)
    if env.migration_dir and 'dir' in p.values and not p.is_set('dir'):
        p.values['dir']=env.migration_dir; p.changed.add('dir')
    if env.migration_format and 'dir-format' in p.values and not p.is_set('dir-format'):
        p.values['dir-format']=env.migration_format
    if env.revisions_schema and 'revisions-schema' in p.values and not p.is_set('revisions-schema'):
        p.values['revisions-schema']=env.revisions_schema

def get_dir(p,env=None,create=False):
    url=p.values.get('dir','file://migrations') if 'dir' in p.values else 'file://migrations'
    fmt_flag=p.get('dir-format') if p.is_set('dir-format') else ''
    d=migdir.open_dir(url,fmt_flag,env.migration_format if env else '',create=create)
    return d,url

def checksum_guard(d):
    try:
        migdir.validate_hash(d)
    except migdir.ChecksumError as e:
        if e.detail:
            line,name,action=e.detail
            sys.stdout.write(f"You have a checksum error in your migration directory.\n\n\tL{line}: {name} was {action}\n\nPlease check your migration files and run 'atlas migrate hash' to re-hash the contents\n\n\n")
        else:
            sys.stdout.write("You have a checksum error in your migration directory.\nPlease check your migration files and run 'atlas migrate hash' to re-hash the contents\n\n\n")
        raise AtlasError('checksum file not found' if e.kind=='notfound' else 'checksum mismatch')

def open_client(url):
    if not url:
        raise AtlasError('sql/sqlclient: missing driver. See: https://atlasgo.io/url')
    u,con=open_sqlite(url)
    if con is None:
        raise AtlasError('sql/sqlclient: missing driver. See: https://atlasgo.io/url')
    return u,con

def check_revisions_schema(p,u):
    rs=p.get('revisions-schema') if 'revisions-schema' in p.values else ''
    if rs and (u.driver=='sqlite'):
        raise AtlasError(f'cannot store revisions-table in a separate schema ("{rs}") with SQLite driver')

def run_migrate(path,args):
    cmd=path[1]
    # args validation for some commands occurs before env/dir in cobra
    p=prep(path,args)
    if p is None: return 0
    if cmd=='hash': return migrate_hash(p)
    if cmd=='validate': return migrate_validate(p)
    if cmd=='new': return migrate_new(p)
    if cmd=='apply': return migrate_apply(path,p)
    if cmd=='status': return migrate_status(path,p)
    if cmd=='set': return migrate_set(p)
    if cmd=='diff': return migrate_diff_cmd(p)
    if cmd=='lint': return migrate_lint_cmd(p)
    if cmd=='import': return migrate_import_cmd(p)
    return 0

def migrate_hash(p):
    env=load_env_for(p); env_defaults_migrate(p,env)
    d,_url=get_dir(p,env)
    migdir.write_hash(d)
    return 0

def migrate_validate(p):
    env=load_env_for(p); env_defaults_migrate(p,env)
    d,_url=get_dir(p,env)
    checksum_guard(d)
    dev_url=p.get('dev-url') or ''
    if dev_url:
        from state import Dev
        dev=Dev(dev_url); con=dev.reset()
        files=migrateops.sorted_by_version(d.files())
        for f in files:
            for stmt in migdir.file_statements(f,d.fmt,generic=False):
                try: con.execute(stmt)
                except sqlite3.Error as e:
                    raise AtlasError(f'replaying the migration directory: sql/migrate: read migration directory state: sql/migrate: executing statement "{stmt}" from version "{f.version}": {e}')
    return 0

def editor_edit_content(content):
    editor=os.environ.get('EDITOR','vi')
    fd,path=tempfile.mkstemp()
    try:
        os.write(fd, content.encode() if isinstance(content,str) else content); os.close(fd)
        cmd=f"{editor} {shlex.quote(path)}"
        r=subprocess.run(cmd,shell=True,executable='/bin/sh')
        if r.returncode!=0:
            raise AtlasError(f'exec edit: exit status {r.returncode}')
        return open(path,'rb').read()
    finally:
        try: os.remove(path)
        except Exception: pass

def migration_filename(fmt, version, name):
    if fmt=='flyway':
        return [(f"V{version}__{name}.sql",'v'),(f"U{version}__{name}.sql",'u')]
    if fmt=='golang-migrate':
        base=f"{version}_{name}" if name else version
        return [(f"{base}.up.sql",'up'),(f"{base}.down.sql",'down')]
    base=f"{version}_{name}" if name else version
    return [(f"{base}.sql",'main')]

def new_file_content(fmt,kind):
    if fmt=='liquibase' and kind=='main': return b'--liquibase formatted sql'
    if fmt=='goose' and kind=='main': return b'-- +goose Up\n\n-- +goose Down\n'
    if fmt=='dbmate' and kind=='main': return b'-- migrate:up\n\n-- migrate:down\n'
    return b''

def migrate_new(p):
    if len(p.args)>1:
        raise AtlasError(f'accepts at most 1 arg(s), received {len(p.args)}')
    env=load_env_for(p); env_defaults_migrate(p,env)
    fmt=p.get('dir-format') or 'atlas'
    if fmt not in migdir.FORMATS:
        raise AtlasError(f'unknown dir format "{fmt}"')
    d,_url=get_dir(p,env,create=True)
    # if dir url had format query, d.fmt may differ
    fmt=d.fmt
    name=p.args[0] if p.args else ''
    version=datetime.datetime.now().strftime('%Y%m%d%H%M%S')
    files=migration_filename(fmt,version,name)
    for fname,kind in files:
        content=new_file_content(fmt,kind)
        if p.get('edit'):
            content=editor_edit_content(content)
        open(os.path.join(d.path,fname),'wb').write(content)
    migdir.write_hash(d)
    return 0

def parse_amount(args):
    if len(args)>1:
        raise AtlasError(f'accepts at most 1 arg(s), received {len(args)}')
    if not args: return None
    s=args[0]
    try:
        # Go strconv.Atoi
        if not re.fullmatch(r'[+-]?\d+',s): raise ValueError()
        return int(s)
    except Exception:
        raise AtlasError(f'invalid amount argument "{s}" (invalid syntax). Omit the argument or pass a valid integer instead')

def build_env_struct(u,url_str,dir_str):
    return reportmod.env_struct(u.driver or 'sqlite', u, dir_str)

def render_apply_log(ex, total_start_ns):
    target=ex.target
    current=ex.current
    n=len(ex.pending)
    out=[]
    if current:
        out.append(f"Migrating to version {target} from {current} ({n} migrations in total):\n\n")
    else:
        out.append(f"Migrating to version {target} ({n} migrations in total):\n\n")
    ok_stmts=0; err_stmts=0; ok_files=0
    for rec in ex.applied:
        out.append(f"  -- migrating version {rec.file.version}\n")
        for stmt in rec.applied:
            out.append("    -> "+stmt.replace('\n','\n       ')+"\n")
            ok_stmts+=1
        if rec.error:
            # error stmt was not in applied list; in log it is printed as a statement line before error
            if rec.error_stmt:
                out.append("    -> "+rec.error_stmt.replace('\n','\n       ')+"\n")
                err_stmts+=1
            out.append(f"    {rec.error}\n")
        else:
            ok_files+=1
            elapsed=getattr(rec,'elapsed_ns',0)
            out.append(f"  -- ok ({format_go_duration(elapsed)})\n\n")
    total_ns=time.monotonic_ns()-total_start_ns
    if ex.error:
        out.append("\n")
    out.append("  -------------------------\n")
    out.append(f"  -- {format_go_duration(total_ns)}\n")
    err_files=len([r for r in ex.applied if r.error])
    if ex.error:
        if ok_files and err_files:
            out.append(f"  -- {ok_files} migration{'s' if ok_files!=1 else ''} ok, {err_files} with errors\n")
        else:
            out.append(f"  -- {err_files} migration{'s' if err_files!=1 else ''} with errors\n")
        if ok_stmts and err_stmts:
            out.append(f"  -- {ok_stmts} sql statement{'s' if ok_stmts!=1 else ''} ok, {err_stmts} with errors\n")
        elif err_stmts:
            out.append(f"  -- {err_stmts} sql statement{'s' if err_stmts!=1 else ''} with errors\n")
        elif ok_stmts:
            out.append(f"  -- {ok_stmts} sql statement{'s' if ok_stmts!=1 else ''} ok\n")
    else:
        total_files=len(ex.applied)
        out.append(f"  -- {total_files} migration{'s' if total_files!=1 else ''}\n")
        if ok_stmts:
            out.append(f"  -- {ok_stmts} sql statement{'s' if ok_stmts!=1 else ''}\n")
    return ''.join(out)

def migrate_apply_struct(env_struct, ex, pending_files, fmt):
    from gotmpl import GoStruct
    pending=[reportmod.localfile_struct(f,fmt) for f in pending_files]
    applied=[reportmod.applied_file_struct(r) for r in ex.applied]
    fields={'Env':env_struct,'Pending':pending,'Applied':applied,'Current':ex.current,'Target':ex.target,'Start':ex.start,'End':ex.end,'Error':''}
    s=GoStruct('*cmdlog.MigrateApply', fields=fields, embedded=[env_struct] if False else [])
    # template .Driver/.URL/.Dir in MigrateApply? It embeds Env, so promote:
    s.embedded=[env_struct]
    jo={}
    if env_struct.fields.get('Driver'): jo['Driver']=env_struct.fields['Driver']
    if env_struct.fields.get('URL') is not None: jo['URL']=env_struct.fields['URL']
    if env_struct.fields.get('Dir'): jo['Dir']=env_struct.fields['Dir']
    if pending_files: jo['Pending']=[reportmod.localfile_struct(f,fmt).json_obj for f in pending_files]
    if ex.applied: jo['Applied']=[reportmod.applied_file_struct(r).json_obj for r in ex.applied]
    if ex.current: jo['Current']=ex.current
    if ex.target: jo['Target']=ex.target
    if ex.start: jo['Start']=ex.start
    if ex.end: jo['End']=ex.end
    if ex.target:
        jo['Message']=f"Migrated to version {ex.target} from {ex.current} ({len(pending_files)} migrations in total)"
    s.json_obj=jo
    return s
