def status_values(files,revisions):
    calc=migrateops.pending_calc(files,revisions,'linear')
    pending=calc['pending']; ooo=calc['out_of_order']
    rev_sorted=sorted(revisions,key=lambda r:r.version)
    partial=None
    if rev_sorted and rev_sorted[-1].total and rev_sorted[-1].applied<rev_sorted[-1].total:
        partial=rev_sorted[-1]
    elif calc.get('partial') is not None:
        partial=calc['partial']
    if not revisions:
        current='No migration applied yet'
    elif partial is not None:
        if len(rev_sorted)==1:
            current=f"No migration applied yet ({partial.applied} statements applied)"
        else:
            current=f"{rev_sorted[-2].version} ({partial.applied} statements applied)"
    else:
        current=rev_sorted[-1].version
    if ooo:
        nxt='UNKNOWN'
    elif partial is not None:
        nxt=f"{partial.version} ({partial.total-partial.applied} statements left)"
    elif pending:
        nxt=pending[0].version or 'UNKNOWN'
    else:
        nxt='Already at latest version'
    status='OK' if not pending else 'PENDING'
    return {'calc':calc,'pending':pending,'ooo':ooo,'partial':partial,'current':current,'next':nxt,'status':status}

def migrate_status_struct(env_struct,files,revisions,vals,dir_url_status,fmt):
    from gotmpl import GoStruct
    es=reportmod.env_struct(env_struct.fields.get('Driver','sqlite'),env_struct.fields.get('URL'),dir_url_status)
    avail=[reportmod.localfile_struct(f,fmt) for f in files]
    pending=[reportmod.localfile_struct(f,fmt) for f in vals['pending']]
    ooo=[reportmod.localfile_struct(f,fmt) for f in vals['ooo']]
    applied=[reportmod.revision_struct(r) for r in sorted(revisions,key=lambda r:r.version)]
    fields={'Env':es,'Available':avail,'OutOfOrder':ooo if ooo else None,'Pending':pending,'Applied':applied,'Current':vals['current'],'Next':vals['next'],'Count':0,'Total':0,'Status':vals['status'],'Error':'','SQL':''}
    s=GoStruct('*cmdlog.MigrateStatus',fields=fields)
    jo={'Env':es}
    if files: jo['Available']=[reportmod.localfile_struct(f,fmt).json_obj for f in files]
    if vals['pending']: jo['Pending']=[reportmod.localfile_struct(f,fmt).json_obj for f in vals['pending']]
    if revisions: jo['Applied']=[reportmod.revision_struct(r).json_obj for r in sorted(revisions,key=lambda r:r.version)]
    jo['Current']=vals['current']; jo['Next']=vals['next']; jo['Status']=vals['status']
    s.json_obj=jo
    return s

def migrate_status(path,p):
    check_groups(p,[['log','format']])
    env=load_env_for(p); env_defaults_migrate(p,env)
    d,dir_url=get_dir(p,env)
    checksum_guard(d)
    u,con=open_client(p.get('url') or '')
    try:
        files=d.files()
        revisions=migrateops.read_revisions(con)
        vals=status_values(files,revisions)
        fmtval=effective_format(p)
        dir_status=dir_url
        if '?' not in dir_status:
            dir_status=dir_status+f"?format={d.fmt}"
        env_struct=build_env_struct(u,p.get('url'),dir_status)
        if fmtval:
            data=migrate_status_struct(env_struct,files,revisions,vals,dir_status,d.fmt)
            sys.stdout.write(execute_template(fmtval,data,{'json':lambda *a: go_json_encode(a[0]) if a else ''}))
            return 0
        out=[]
        out.append(f"Migration Status: {vals['status']}\n")
        out.append(f"  -- Current Version: {vals['current']}\n")
        out.append(f"  -- Next Version:    {vals['next']}\n")
        exec_line=str(len(revisions))
        if vals['partial'] is not None:
            exec_line+= " (last one partially)"
        out.append(f"  -- Executed Files:  {exec_line}\n")
        pend_line=str(len(vals['pending']))
        if vals['ooo']:
            pend_line+=f" ({len(vals['ooo'])} out of order)"
        out.append(f"  -- Pending Files:   {pend_line}\n")
        if vals['ooo']:
            out.append(f"\n  ERROR: migration file {vals['ooo'][0].name} was added out of order. See: https://atlasgo.io/versioned/apply#non-linear-error\n")
        if vals['partial'] is not None and vals['partial'].error:
            out.append("\nLast migration attempt had errors:\n")
            out.append(f"  -- SQL:   {vals['partial'].error_stmt}\n")
            out.append(f"  -- ERROR: {vals['partial'].error}\n")
        sys.stdout.write(''.join(out))
        return 0
    finally:
        try: con.close()
        except Exception: pass

def migrate_set(p):
    env=load_env_for(p); env_defaults_migrate(p,env)
    d,_url=get_dir(p,env)
    u,con=open_client(p.get('url') or '')
    try:
        check_revisions_schema(p,u)
        checksum_guard(d)
        files=migrateops.sorted_by_version(d.files())
        hash_map=migrateops.file_hash_map(d.files())
        migrateops.ensure_revisions_table(con)
        revisions=migrateops.read_revisions(con)
        if len(p.args)>1:
            raise AtlasError(f'accepts 1 arg(s), received {len(p.args)}')
        if len(p.args)==0:
            if not revisions:
                raise AtlasError('accepts 1 arg(s), received 0')
            if not files:
                raise AtlasError('accepts 1 arg(s), received 0')
            target=files[-1].version
        else:
            target=p.args[0]
        target_file=None
        for f in files:
            if f.version==target: target_file=f; break
        if target_file is None:
            raise AtlasError(f'migration with version "{target}" not found')
        # desired files up to target in version-sorted order
        desired=[]
        for f in files:
            desired.append(f)
            if f.version==target: break
        desired_versions={f.version for f in desired}
        rev_by={r.version:r for r in revisions}
        added=[]; removed=[]
        for f in desired:
            if f.version not in rev_by:
                rev=migrateops.Revision(version=f.version,description=f.description,type=4,applied=0,total=0,executed_at=GoTime(),execution_time=0,hash=hash_map.get(f.name,''))
                migrateops.write_revision(con,rev); added.append(f)
        for r in sorted(revisions,key=lambda x:x.version):
            if r.version not in desired_versions:
                # find file for description if exists
                ff=None
                for f in files:
                    if f.version==r.version: ff=f; break
                removed.append((r,ff))
                migrateops.delete_revision(con,r.version)
        if added and not removed:
            out=[f"Current version is {target} ({len(added)} set):\n\n"]
            for f in added:
                out.append(f"  + {f.version}" + (f" ({f.description})" if f.description else "")+"\n")
            out.append("\n"); sys.stdout.write(''.join(out))
        elif removed and not added:
            out=[f"Current version is {target} ({len(removed)} removed):\n\n"]
            for r,ff in removed:
                desc=ff.description if ff else r.description
                out.append(f"  - {r.version}" + (f" ({desc})" if desc else "")+"\n")
            out.append("\n"); sys.stdout.write(''.join(out))
        elif added or removed:
            out=[f"Current version is {target} ({len(added)} set, {len(removed)} removed):\n\n"]
            for f in added: out.append(f"  + {f.version}" + (f" ({f.description})" if f.description else "")+"\n")
            for r,ff in removed:
                desc=ff.description if ff else r.description
                out.append(f"  - {r.version}" + (f" ({desc})" if desc else "")+"\n")
            out.append("\n"); sys.stdout.write(''.join(out))
        return 0
    finally:
        try: con.close()
        except Exception: pass
