        for f in files:
            desired.append(f)
            if f.version==target: break
        desired_versions={f.version for f in desired}
        rev_by={r.version:r for r in revisions}
        added=[]; removed=[]
        for f in desired:
            if f.version not in rev_by:
                rev=migrateops.Revision(version=f.version,description=f.description,type=4,applied=0,total=0,executed_at=GoTime(),execution_time=0,hash=hash_map.get(f.name,''))
                migrateops.write_revision(con,rev); added.append(f)
        for r in sorted(revisions,key=lambda x:x.version):
            if r.version not in desired_versions:
                # find file for description if exists
                ff=None
                for f in files:
                    if f.version==r.version: ff=f; break
                removed.append((r,ff))
                migrateops.delete_revision(con,r.version)
        if added and not removed:
            out=[f"Current version is {target} ({len(added)} set):\n\n"]
            for f in added:
                out.append(f"  + {f.version}" + (f" ({f.description})" if f.description else "")+"\n")
            out.append("\n"); sys.stdout.write(''.join(out))
        elif removed and not added:
            out=[f"Current version is {target} ({len(removed)} removed):\n\n"]
            for r,ff in removed:
                desc=ff.description if ff else r.description
                out.append(f"  - {r.version}" + (f" ({desc})" if desc else "")+"\n")
            out.append("\n"); sys.stdout.write(''.join(out))
        elif added or removed:
            out=[f"Current version is {target} ({len(added)} set, {len(removed)} removed):\n\n"]
            for f in added: out.append(f"  + {f.version}" + (f" ({f.description})" if f.description else "")+"\n")
            for r,ff in removed:
                desc=ff.description if ff else r.description
                out.append(f"  - {r.version}" + (f" ({desc})" if desc else "")+"\n")
            out.append("\n"); sys.stdout.write(''.join(out))
        return 0
    finally:
        try: con.close()
        except Exception: pass
