def _replay_dir_on_dev(d, dev, err_prefix=''):
    con=dev.reset()
    files=migrateops.sorted_by_version(d.files())
    for f in files:
        for stmt in migdir.file_statements(f,d.fmt,generic=False):
            try: con.execute(stmt)
            except sqlite3.Error as e:
                raise AtlasError(f'sql/migrate: read migration directory state: sql/migrate: executing statement "{stmt}" from version "{f.version}": {e}')
    from sqliteinspect import inspect_sqlite_conn
    return inspect_sqlite_conn(con)

def migrate_diff_cmd(p):
    if len(p.args)>1:
        raise AtlasError(f'accepts at most 1 arg(s), received {len(p.args)}')
    env=load_env_for(p); env_defaults_migrate(p,env)
    if env and env.src and not p.is_set('to'):
        p.values['to']=list(env.src); p.changed.add('to')
    if env and env.schemas and not p.is_set('schema'):
        p.values['schema']=list(env.schemas)
    # required order: to, dev-url in flag definition order of missing
    missing=[]
    if not p.is_set('to'): missing.append('to')
    if not p.is_set('dev-url'): missing.append('dev-url')
    if missing:
        raise AtlasError('required flag(s) '+', '.join(f'"{m}"' for m in missing)+' not set')
    from state import Dev, read_states
    from schemadiff import plan_changes
    from sqlgen import render_sql
    # dir may not exist: create later, files empty. Check format validity
    url=p.values.get('dir','file://migrations')
    fmt_flag=p.get('dir-format') if p.is_set('dir-format') else ''
    d=migdir.parse_dir_url(url,fmt_flag,env.migration_format if env else '')
    if d.fmt not in migdir.FORMATS:
        raise AtlasError(f'unknown dir format "{d.fmt}"')
    # if exists, checksum guard
    if os.path.isdir(d.path):
        checksum_guard(d)
    dev=Dev(p.get('dev-url'))
    current=_replay_dir_on_dev(d,dev) if os.path.isdir(d.path) else _empty_realm()
    # Filter current: replay may include revisions table? If migrations created it explicitly, keep - migrations themselves generally don't.
    desired=read_states(p.get('to'),p.get('dev-url') or '',var_inputs(p))
    plan,changes=plan_changes(current,desired)
    if not plan:
        sys.stdout.write('The migration directory is synced with the desired state, no changes to be made\n')
        return 0
    name=p.args[0] if p.args else ''
    # qualifier handling: regenerate plan with qualifier by rewriting table identifiers in cmds (approximation)
    qualifier=p.get('qualifier') or ''
    if qualifier:
        plan=_apply_qualifier(plan,qualifier,desired,current)
    fmtval=p.get('format') or ''
    plan_struct=_plan_struct(name,plan)
    if fmtval:
        content=_render_migrate_diff_format(fmtval,plan_struct,plan)
    else:
        content=render_sql(plan)
    content_bytes=content.encode() if isinstance(content,str) else content
    if p.get('edit'):
        content_bytes=editor_edit_content(content_bytes)
    version=datetime.datetime.now().strftime('%Y%m%d%H%M%S')
    os.makedirs(d.path,exist_ok=True)
    _write_migration_file(d,version,name,content_bytes,plan)
    migdir.write_hash(d)
    return 0

def _empty_realm():
    from model import Realm, Schema
    return Realm(schemas=[Schema(name='main',tables=[])])

def _apply_qualifier(plan,qualifier,desired,current):
    # Regenerate CREATE TABLE/INDEX/ALTER/DROP cmds prefixing table names with qualifier for AddTable-type commands. Approximation: rebuild new table changes for AddTable sources using qualified builder.
    from sqlgen import qid, build_create_table, build_create_index, effective_index_name
    # Collect desired tables
    tables={}
    for sch in desired.schemas:
        for t in sch.tables: tables[t.name]=t
    for pc in plan:
        if pc.create_table is not None:
            orig=build_create_table(pc.create_table,name_override=pc.create_name)
            # replace first occurrence of `name` after CREATE TABLE with `q`.`name`
            tname=pc.create_name or pc.create_table.name
            pc.cmd=orig.replace(f"CREATE TABLE {qid(tname)}", f"CREATE TABLE {qid(qualifier)}.{qid(tname)}",1)
            # FK references also qualified in builder output? Reference table refs inside cmd are `ref` - qualify those refs in create after REFERENCES
            pc.cmd=re.sub(r'REFERENCES `([^`]+)`', lambda m: f'REFERENCES {qid(qualifier)}.`{m.group(1)}`', pc.cmd)
        elif pc.cmd.startswith('CREATE') and 'INDEX' in pc.cmd:
            pc.cmd=re.sub(r'ON `([^`]+)`', lambda m: f'ON {qid(qualifier)}.`{m.group(1)}`', pc.cmd, count=1)
    return plan

def _plan_struct(name,plan):
    from gotmpl import GoStruct
    changes=[]
    for pc in plan:
        ch=reportmod.migrate_change_struct(pc,indent_cmd=False)
        changes.append(ch)
    s=GoStruct('*migrate.Plan',fields={'Version':'','Name':name,'Reversible':True,'Transactional':True,'Changes':changes,'Delimiter':'','Directives':None})
    return s

def _render_migrate_diff_format(fmtval,plan_struct,plan):
    from gotmpl import Template, TemplateParseError, TemplateExecError, FunctionTypeError, GoMethodError
    from sqlgen import render_sql
    def sqlfn(*args):
        if len(args)==0:
            raise FunctionTypeError('wrong number of args for sql: want at least 1 got 0',0)
        if args[0] is not plan_struct:
            from gotmpl import go_type_of
            raise FunctionTypeError(f'wrong type for value; expected *migrate.Plan; got {go_type_of(args[0])}',0)
        indent=str(args[1]) if len(args)>1 else ''
        return render_sql(plan,indent=indent)
    try:
        tmpl=Template(fmtval,name='format',funcs={'sql':sqlfn})
    except TemplateParseError as e:
        raise AtlasError(f"parse format: template: format:{e.line}: {e.msg}")
    canon=tmpl.canonical()
    # check sql usage
    if 'sql' in _template_sql_calls(tmpl):
        if not re.fullmatch(r'\{\{sql \.(?: "[^"]*")?\}\}',canon):
            raise AtlasError(f"'sql' can only be used to indent statements. got: {canon}\n")
    try:
        return tmpl.execute(plan_struct)
    except TemplateExecError as e:
        raise AtlasError(f'template: format:{e.line}:{e.col}: executing "format" at <{e.context}>: {e.msg}')

def _template_sql_calls(tmpl):
    out=[]
    def visit(nodes):
        for nd in nodes:
            pipe=getattr(nd,'pipe',None)
            if pipe:
                for c in pipe.cmds:
                    if c.terms and c.terms[0].kind=='IDENT': out.append(c.terms[0].text)
            for attr in ('body','els'):
                if hasattr(nd,attr): visit(getattr(nd,attr))
    visit(tmpl.nodes)
    return out

def _write_migration_file(d,version,name,content_bytes,plan):
    fmt=d.fmt
    files=migration_filename(fmt,version,name)
    # reverse content for down files
    from sqlgen import render_sql, PlanChange
    reverse_cmds=[]
    for pc in reversed(plan):
        if pc.reverse:
            reverse_cmds.append(pc.reverse+';\n')
    reverse_content=''.join(reverse_cmds).encode()
    for fname,kind in files:
        if fmt=='goose' and kind=='main':
            data=b'-- +goose Up\n'+content_bytes+(b'' if content_bytes.endswith(b'\n') else b'\n')+b'-- +goose Down\n'+reverse_content
        elif fmt=='dbmate' and kind=='main':
            data=b'-- migrate:up\n'+content_bytes+(b'' if content_bytes.endswith(b'\n') else b'\n')+b'-- migrate:down\n'+reverse_content
        elif kind in ('down','u'):
            data=reverse_content
        elif fmt=='liquibase' and kind=='main':
            data=content_bytes
        else:
            data=content_bytes
        open(os.path.join(d.path,fname),'wb').write(data)

# ---------------- lint ----------------
def migrate_lint_cmd(p):
    check_groups(p,[['log','format']])
    env=load_env_for(p); env_defaults_migrate(p,env)
    if not p.is_set('dev-url'):
        raise AtlasError('required flag(s) "dev-url" not set')
    d,_url=get_dir(p,env)
    if p.get('latest') and p.get('git-base'):
        raise AtlasError('--latest and --git-base are mutually exclusive')
    if not p.get('latest') and not p.get('git-base'):
        raise AtlasError('--latest or --git-base is required')
    checksum_guard(d)
    files_all=migrateops.sorted_by_version(d.files())
    if p.get('git-base'):
        files=_lint_git_files(p,d,files_all)
    else:
        n=int(p.get('latest') or 0)
        files=files_all[-n:] if n < len(files_all) else list(files_all)
    fmtval=effective_format(p)
    if not files_all:
        # No output regardless format? If format set, still render an empty summary (reference printed LOG literal in earlier test)
        if fmtval:
            summary=_lint_summary_struct(p,d,files_all,files,[],None,None)
            sys.stdout.write(execute_template(fmtval,summary,{'json':lambda *a: go_json_encode(a[0]) if a else ''}))
        return 0
    from state import Dev
    from sqliteinspect import inspect_sqlite_conn
    dev=Dev(p.get('dev-url'))
    start_ns=time.monotonic_ns(); start_time=GoTime()
    con=dev.reset()
    # replay files before analyzed ones
    analyzed_start_index=len(files_all)-len(files)
    base_files=files_all[:analyzed_start_index]
    for f in base_files:
        for stmt in migdir.file_statements(f,d.fmt,generic=False):
            try: con.execute(stmt)
            except sqlite3.Error as e:
                # Error during replay of base files - treat as execution error for that file? Reference behavior: report error in header. Simplified via lint exec error path with files=[f]
                pass
    from_realm=inspect_sqlite_conn(con)
    file_reports=[]
    total_changes=0; total_diags=0; versions_ok=0; versions_warn=0; versions_err=0
    exec_error=None
    current_realm=from_realm
    desired_realm=from_realm
    for f in files:
        fstart=time.monotonic_ns()
        before=current_realm
        stmts=migdir.file_statements(f,d.fmt,generic=False)
        file_changes_count=0
        reports=[]  # list dict {text, diagnostics}
        # execute statement by statement, diff each
        for si,stmt in enumerate(stmts):
            try:
                con.execute(stmt)
            except sqlite3.Error as e:
                exec_error=(f,stmt,str(e))
                break
            after=inspect_sqlite_conn(con)
            from schemadiff import realm_diff
            diffs=realm_diff(before,after)
            file_changes_count+=len([c for c in diffs if c.kind!='DropSchema'])
            reports.extend(_analyze_changes(before,after,diffs,si,f))
            before=after
        if exec_error:
            file_reports.append({'file':f,'reports':reports,'changes':file_changes_count,'elapsed':time.monotonic_ns()-fstart,'error':exec_error})
            versions_err+=1
            desired_realm=before
            break
        current_realm=before; desired_realm=before
        total_changes+=file_changes_count
        diags=[diag for r in reports for diag in r['diagnostics']]
        total_diags+=len(diags)
        has_error=any(r['text']=='destructive changes detected' for r in reports)
        has_warn=bool(diags) and not has_error
        if has_error: versions_err+=1
        elif has_warn: versions_warn+=1
        else: versions_ok+=1
        file_reports.append({'file':f,'reports':reports,'changes':file_changes_count,'elapsed':time.monotonic_ns()-fstart,'error':None})
    total_elapsed=time.monotonic_ns()-start_ns
    if fmtval:
        summary=_lint_summary_struct(p,d,files_all,files,file_reports,from_realm,desired_realm,start_time=start_time)
        sys.stdout.write(execute_template(fmtval,summary,{'json':lambda *a: go_json_encode(a[0]) if a else ''}))
        return 1 if (versions_err or exec_error) else 0
    # default log
    sys.stdout.write(_render_lint_log(files_all,files,file_reports,total_elapsed,total_changes,total_diags,versions_ok,versions_warn,versions_err,exec_error))
    return 1 if (versions_err or exec_error) else 0

def _lint_git_files(p,d,files_all):
    # Determine changed migration files between git-base and HEAD/worktree in git-dir
    gitdir=p.get('git-dir') or '.'
    base=p.get('git-base')
    try:
        r=subprocess.run(['git','-C',gitdir,'diff','--name-only',base,'--'],capture_output=True,text=True)
        changed=set(r.stdout.splitlines())
        # also untracked?
        r2=subprocess.run(['git','-C',gitdir,'ls-files','--others','--exclude-standard'],capture_output=True,text=True)
        changed.update(r2.stdout.splitlines())
    except Exception:
        changed=set()
    # Map repo-relative paths to dir files: path relative to gitdir + d.path
    dir_abs=os.path.abspath(d.path); git_abs=os.path.abspath(gitdir)
    out=[]
    for f in files_all:
        rel=os.path.relpath(os.path.abspath(f.path),git_abs)
        if rel in changed: out.append(f)
    return out

def _diag(text,code,fix=None,pos=0):
    d={'Pos':pos,'Text':text}
    if code: d['Code']=code
    if fix: d['SuggestedFixes']=[{'Message':fix}]
    return d

def _analyze_changes(before,after,diffs,stmt_idx,f):
    reports_by_kind={}
    def add(kind,diag):
        reports_by_kind.setdefault(kind,[]).append(diag)
    for ch in diffs:
        if ch.kind=='DropTable':
            add('destructive changes detected',_diag(f'Dropping table "{ch.table.name}"','DS102',f'Add a pre-migration check to ensure table "{ch.table.name}" is empty before dropping it'))
        elif ch.kind=='ModifyTable':
            for s in ch.changes:
                if s[0]=='DropColumn':
                    col=s[1]
                    if col.generated is None or col.generated.type!='VIRTUAL':
                        add('destructive changes detected',_diag(f'Dropping non-virtual column "{col.name}"','DS103',f'Add a pre-migration check to ensure column "{col.name}" is NULL before dropping it'))
                elif s[0]=='AddColumn':
                    col=s[1]
                    if not col.null and col.default is None and col.generated is None:
                        from model import sql_type_name
                        add('data dependent changes detected',_diag(f'Adding a non-nullable "{sql_type_name(col.raw_type)}" column "{col.name}" will fail in case table "{ch.to_table.name}" is not empty','MF103'))
                elif s[0]=='AddIndex':
                    idx=s[1]
                    if idx.unique and idx.parts and idx.parts[0].column:
                        add('data dependent changes detected',_diag(f'Adding a unique index "{idx.name}" on table "{ch.to_table.name}" might fail in case column "{idx.parts[0].column}" contains duplicate entries','MF101'))
        elif ch.kind=='AddTable':
            pass
    reports=[]
    order=['destructive changes detected','data dependent changes detected']
    for k in order:
        if k in reports_by_kind:
            reports.append({'text':k,'diagnostics':reports_by_kind[k]})
    return reports

def _render_lint_log(files_all,files,file_reports,total_elapsed,total_changes,total_diags,v_ok,v_warn,v_err,exec_error):
    from gotmpl import format_go_duration
    out=[]
    if not files:
        return ''
    first=files[0]; last=files[-1]
    # from version: version of file before first analyzed, if any
    analyzed_start=len(files_all)-len(files)
    if analyzed_start>0:
        from_v=files_all[analyzed_start-1].version
        out.append(f"Analyzing changes from version {from_v} to {last.version} ({len(files)} migration{'s' if len(files)!=1 else ''} in total):\n\n")
    else:
        out.append(f"Analyzing changes until version {last.version} ({len(files)} migrations in total):\n\n")
    if exec_error:
        f,stmt,msg=exec_error
        out.append(f"  Error: executing statement: {stmt}: {msg}\n\n")
        out.append("  -------------------------\n")
        out.append(f"  -- {format_go_duration(total_elapsed)}\n")
        out.append("  -- 1 version with errors\n")
        return ''.join(out)
    for rep in file_reports:
        f=rep['file']
        out.append(f"  -- analyzing version {f.version}\n")
        if not rep['reports']:
            out.append("    -- no diagnostics found\n")
        else:
            for r in rep['reports']:
                out.append(f"    -- {r['text']}:\n")
                fixes=[]
                for diag in r['diagnostics']:
                    line=diag.get('_line','L1')
                    code=diag.get('Code','')
                    # wrap at ~92 chars like reference for MF texts (handled by simple wrap for long ones)
                    txt=f"      -- L1: {diag['Text']}"
                    if code:
                        txt+=f" https://atlasgo.io/lint/analyzers#{code}"
                    out.append(_wrap_lint_line(txt)+"\n")
                    for fix in diag.get('SuggestedFixes',[]): fixes.append(fix['Message'])
                if fixes:
                    out.append("    -- suggested fix:\n")
                    for fx in fixes:
                        out.append(f"      -> {fx}\n")
        out.append(f"  -- ok ({format_go_duration(rep['elapsed'])})\n\n")
    out.append("  -------------------------\n")
    out.append(f"  -- {format_go_duration(total_elapsed)}\n")
    # versions line
    parts=[]
    if v_ok: parts.append(f"{v_ok} version{'s' if v_ok!=1 else ''} ok")
    if v_warn: parts.append(f"{v_warn} version{'s' if v_warn!=1 else ''} with warnings")
    if v_err: parts.append(f"{v_err} version{'s' if v_err!=1 else ''} with errors")
    # Special cases from reference: all ok => "N version(s) ok", single warn => "1 version with warnings", single err => "1 version with errors", mixed ok+err => "1 version ok, 1 with errors"
    if v_ok and v_err and not v_warn:
        parts=[f"{v_ok} version{'s' if v_ok!=1 else ''} ok", f"{v_err} with errors"]
    out.append("  -- "+', '.join(parts)+"\n")
    if total_changes:
        out.append(f"  -- {total_changes} schema change{'s' if total_changes!=1 else ''}\n")
    if total_diags:
        out.append(f"  -- {total_diags} diagnostic{'s' if total_diags!=1 else ''}\n")
    return ''.join(out)

def _wrap_lint_line(txt):
    # Reference wraps long diagnostic lines: continuation indented 9 spaces before URL in examples.
    if len(txt)<=95:
        return txt
    # break before last words to keep <= ~95 first line, continuation 9 spaces
    words=txt.split(' ')
    line=''; out=[]
    for w in words:
        if line and len(line)+1+len(w)>92:
            out.append(line); line='         '+w
        else:
            line=(line+' '+w) if line else w
    if line: out.append(line)
    return '\n'.join(out)

def _lint_summary_struct(p,d,files_all,files,file_reports,from_realm,desired_realm,start_time=None):
    from gotmpl import GoStruct
    from schemamarshal import marshal_hcl
    u=parse_client_url(p.get('dev-url') or '')
    env=reportmod.env_struct(u.driver or 'sqlite',u,d.path)
    # Env in lint JSON: Dir is "migrations" (path) not url
    current_hcl=marshal_hcl(from_realm) if from_realm is not None else ''
    desired_hcl=marshal_hcl(desired_realm) if desired_realm is not None else ''
    analyzed_start=len(files_all)-len(files) if files_all else 0
    from_v=files_all[analyzed_start-1].version if analyzed_start>0 else ''
    to_v=files[-1].version if files else ''
    steps=[]
    def step(name,text,result=None):
        jo={'Name':name,'Text':text}
        if result is not None: jo['Result']=result
        s=GoStruct('*migratelint.StepReport',fields={'Name':name,'Text':text,'Result':result})
        s.json_obj=jo; return s
    steps.append(step('Migration Integrity Check','File atlas.sum is valid'))
    steps.append(step('Detect New Migration Files',f"Found {len(files)} new migration files (from {len(files_all)} total)"))
    nchanges=sum(r.get('changes',0) for r in file_reports)
    steps.append(step('Replay Migration Files',f"Loaded {nchanges} changes on dev database"))
    file_structs=[]
    for rep in file_reports:
        f=rep['file']
        reports=[]
        for r in rep['reports']:
            diags=[]
            for diag in r['diagnostics']:
                dj={'Pos':diag.get('Pos',0),'Text':diag['Text']}
                if diag.get('Code'): dj['Code']=diag['Code']
                if diag.get('SuggestedFixes'): dj['SuggestedFixes']=diag['SuggestedFixes']
                diags.append(dj)
            reports.append({'Text':r['text'],'Diagnostics':diags})
        jo={'Name':f.name,'Text':migdir.file_content_text(f)}
        if reports: jo['Reports']=reports
        if rep['reports']:
            # Error field is first report text if destructive etc - reference sets Error to report text for errors/warnings? For warnings maybe empty; set for any report
            jo['Error']=rep['reports'][0]['text']
        fs=GoStruct('*migratelint.FileReport',fields={'Name':f.name,'Text':migdir.file_content_text(f),'Reports':reports,'Error':jo.get('Error','')})
        fs.json_obj=jo; file_structs.append(fs)
        nrep=len(reports)
        steps.append(step(f'Analyze {f.name}',f"{nrep} reports were found in analysis" if nrep else 'No reports were found in analysis', result=fs))
    schema_s=GoStruct('struct',fields={'Current':current_hcl,'Desired':desired_hcl})
    fields={'URL':'','Env':env,'Schema':schema_s,'Steps':steps,'Files':file_structs,'Start':start_time or GoTime(),'End':GoTime(),'FromV':from_v,'ToV':to_v,'TotalFiles':len(files),'Warning':None}
    s=GoStruct('*migratelint.SummaryReport',fields=fields)
    jo={'Env':{'Driver':u.driver or 'sqlite','URL':u,'Dir':d.path},'Schema':{'Current':current_hcl,'Desired':desired_hcl},'Steps':[st.json_obj for st in steps],'Files':[fs.json_obj for fs in file_structs]}
    s.json_obj=jo
    return s

