def _empty_realm():
    from model import Realm, Schema
    return Realm(schemas=[Schema(name='main',tables=[])])

def _apply_qualifier(plan,qualifier,desired,current):
    # Regenerate CREATE TABLE/INDEX/ALTER/DROP cmds prefixing table names with qualifier for AddTable-type commands. Approximation: rebuild new table changes for AddTable sources using qualified builder.
    from sqlgen import qid, build_create_table, build_create_index, effective_index_name
    # Collect desired tables
    tables={}
    for sch in desired.schemas:
        for t in sch.tables: tables[t.name]=t
    for pc in plan:
        if pc.create_table is not None:
            orig=build_create_table(pc.create_table,name_override=pc.create_name)
            # replace first occurrence of `name` after CREATE TABLE with `q`.`name`
            tname=pc.create_name or pc.create_table.name
            pc.cmd=orig.replace(f"CREATE TABLE {qid(tname)}", f"CREATE TABLE {qid(qualifier)}.{qid(tname)}",1)
            # FK references also qualified in builder output? Reference table refs inside cmd are `ref` - qualify those refs in create after REFERENCES
            pc.cmd=re.sub(r'REFERENCES `([^`]+)`', lambda m: f'REFERENCES {qid(qualifier)}.`{m.group(1)}`', pc.cmd)
        elif pc.cmd.startswith('CREATE') and 'INDEX' in pc.cmd:
            pc.cmd=re.sub(r'ON `([^`]+)`', lambda m: f'ON {qid(qualifier)}.`{m.group(1)}`', pc.cmd, count=1)
    return plan

def _plan_struct(name,plan):
    from gotmpl import GoStruct
    changes=[]
    for pc in plan:
        ch=reportmod.migrate_change_struct(pc,indent_cmd=False)
        changes.append(ch)
    s=GoStruct('*migrate.Plan',fields={'Version':'','Name':name,'Reversible':True,'Transactional':True,'Changes':changes,'Delimiter':'','Directives':None})
    return s

def _render_migrate_diff_format(fmtval,plan_struct,plan):
    from gotmpl import Template, TemplateParseError, TemplateExecError, FunctionTypeError, GoMethodError
    from sqlgen import render_sql
    def sqlfn(*args):
        if len(args)==0:
            raise FunctionTypeError('wrong number of args for sql: want at least 1 got 0',0)
        if args[0] is not plan_struct:
            from gotmpl import go_type_of
            raise FunctionTypeError(f'wrong type for value; expected *migrate.Plan; got {go_type_of(args[0])}',0)
        indent=str(args[1]) if len(args)>1 else ''
        return render_sql(plan,indent=indent)
    try:
        tmpl=Template(fmtval,name='format',funcs={'sql':sqlfn})
    except TemplateParseError as e:
        raise AtlasError(f"parse format: template: format:{e.line}: {e.msg}")
    canon=tmpl.canonical()
    # check sql usage
    if 'sql' in _template_sql_calls(tmpl):
        if not re.fullmatch(r'\{\{sql \.(?: "[^"]*")?\}\}',canon):
            raise AtlasError(f"'sql' can only be used to indent statements. got: {canon}\n")
    try:
        return tmpl.execute(plan_struct)
    except TemplateExecError as e:
        raise AtlasError(f'template: format:{e.line}:{e.col}: executing "format" at <{e.context}>: {e.msg}')

def _template_sql_calls(tmpl):
    out=[]
    def visit(nodes):
        for nd in nodes:
            pipe=getattr(nd,'pipe',None)
            if pipe:
                for c in pipe.cmds:
                    if c.terms and c.terms[0].kind=='IDENT': out.append(c.terms[0].text)
            for attr in ('body','els'):
                if hasattr(nd,attr): visit(getattr(nd,attr))
    visit(tmpl.nodes)
    return out

def _write_migration_file(d,version,name,content_bytes,plan):
    fmt=d.fmt
    files=migration_filename(fmt,version,name)
    # reverse content for down files
    from sqlgen import render_sql, PlanChange
    reverse_cmds=[]
    for pc in reversed(plan):
        if pc.reverse:
            reverse_cmds.append(pc.reverse+';\n')
    reverse_content=''.join(reverse_cmds).encode()
    for fname,kind in files:
        if fmt=='goose' and kind=='main':
            data=b'-- +goose Up\n'+content_bytes+(b'' if content_bytes.endswith(b'\n') else b'\n')+b'-- +goose Down\n'+reverse_content
        elif fmt=='dbmate' and kind=='main':
            data=b'-- migrate:up\n'+content_bytes+(b'' if content_bytes.endswith(b'\n') else b'\n')+b'-- migrate:down\n'+reverse_content
        elif kind in ('down','u'):
            data=reverse_content
        elif fmt=='liquibase' and kind=='main':
            data=content_bytes
        else:
            data=content_bytes
        open(os.path.join(d.path,fname),'wb').write(data)

