def migrate_import_cmd(p):
    env=load_env_for(p); env_defaults_migrate(p,env)
    from_url=p.get('from'); to_url=p.get('to')
    fmt_flag=p.get('dir-format') if p.is_set('dir-format') else ''
    src=migdir.parse_dir_url(from_url,fmt_flag,'')
    if src.fmt not in migdir.FORMATS:
        raise AtlasError(f'unknown dir format "{src.fmt}"')
    if src.fmt=='atlas':
        # still needs dir to exist first? Reference with missing migrations gave stat before this error
        if not os.path.isdir(src.path):
            raise AtlasError(f"sql/migrate: stat {src.path}: no such file or directory")
        raise AtlasError('cannot import a migration directory already in "atlas" format')
    if not os.path.isdir(src.path):
        raise AtlasError(f"sql/migrate: stat {src.path}: no such file or directory")
    dst=migdir.parse_dir_url(to_url,'','')
    os.makedirs(dst.path,exist_ok=True)
    files=src.files()
    # For golang-migrate etc, files() only includes ups. Content transform:
    for f in files:
        if src.fmt=='flyway':
            if f.name.startswith('R__'):
                newname=f"{f.version}_{f.description}.sql"  # version like 2_1R
            else:
                newname=f"{f.version}_{f.description}.sql" if f.description else f"{f.version}.sql"
            content=f.content
        elif src.fmt=='golang-migrate':
            newname=f"{f.version}_{f.description}.sql" if f.description else f"{f.version}.sql"
            content=f.content
        elif src.fmt in ('goose','dbmate'):
            newname=f.name
            text=migdir.extract_up(migdir.file_content_text(f),src.fmt)
            # reference output strips leading/trailing blank lines but keeps trailing newline of last stmt
            text=text.strip()
            content=(text+'\n').encode() if text else b''
        else:  # liquibase
            newname=f.name; content=f.content
        open(os.path.join(dst.path,newname),'wb').write(content)
    # write hash in dst as atlas
    dst_dir=migdir.MigDir(dst.path,'atlas')
    migdir.write_hash(dst_dir)
    return 0
