def _replay_dir_on_dev(d, dev, err_prefix=''):
    con=dev.reset()
    files=migrateops.sorted_by_version(d.files())
    for f in files:
        for stmt in migdir.file_statements(f,d.fmt,generic=False):
            try: con.execute(stmt)
            except sqlite3.Error as e:
                raise AtlasError(f'sql/migrate: read migration directory state: sql/migrate: executing statement "{stmt}" from version "{f.version}": {e}')
    from sqliteinspect import inspect_sqlite_conn
