def migrate_diff_cmd(p):
    if len(p.args)>1:
        raise AtlasError(f'accepts at most 1 arg(s), received {len(p.args)}')
    env=load_env_for(p); env_defaults_migrate(p,env)
    if env and env.src and not p.is_set('to'):
        p.values['to']=list(env.src); p.changed.add('to')
    if env and env.schemas and not p.is_set('schema'):
        p.values['schema']=list(env.schemas)
    # required order: to, dev-url in flag definition order of missing
    missing=[]
    if not p.is_set('to'): missing.append('to')
    if not p.is_set('dev-url'): missing.append('dev-url')
    if missing:
        raise AtlasError('required flag(s) '+', '.join(f'"{m}"' for m in missing)+' not set')
    from state import Dev, read_states
    from schemadiff import plan_changes
    from sqlgen import render_sql
    # dir may not exist: create later, files empty. Check format validity
    url=p.values.get('dir','file://migrations')
    fmt_flag=p.get('dir-format') if p.is_set('dir-format') else ''
    d=migdir.parse_dir_url(url,fmt_flag,env.migration_format if env else '')
    if d.fmt not in migdir.FORMATS:
        raise AtlasError(f'unknown dir format "{d.fmt}"')
