    if os.path.isdir(d.path):
        checksum_guard(d)
    dev=Dev(p.get('dev-url'))
    current=_replay_dir_on_dev(d,dev) if os.path.isdir(d.path) else _empty_realm()
    # Filter current: replay may include revisions table? If migrations created it explicitly, keep - migrations themselves generally don't.
    desired=read_states(p.get('to'),p.get('dev-url') or '',var_inputs(p))
    plan,changes=plan_changes(current,desired)
    if not plan:
        sys.stdout.write('The migration directory is synced with the desired state, no changes to be made\n')
        return 0
    name=p.args[0] if p.args else ''
    # qualifier handling: regenerate plan with qualifier by rewriting table identifiers in cmds (approximation)
    qualifier=p.get('qualifier') or ''
    if qualifier:
        plan=_apply_qualifier(plan,qualifier,desired,current)
    fmtval=p.get('format') or ''
    plan_struct=_plan_struct(name,plan)
    if fmtval:
        content=_render_migrate_diff_format(fmtval,plan_struct,plan)
    else:
