def migrate_lint_cmd(p):
    check_groups(p,[['log','format']])
    env=load_env_for(p); env_defaults_migrate(p,env)
    if not p.is_set('dev-url'):
        raise AtlasError('required flag(s) "dev-url" not set')
    d,_url=get_dir(p,env)
    if p.get('latest') and p.get('git-base'):
        raise AtlasError('--latest and --git-base are mutually exclusive')
    if not p.get('latest') and not p.get('git-base'):
        raise AtlasError('--latest or --git-base is required')
    checksum_guard(d)
    files_all=migrateops.sorted_by_version(d.files())
    if p.get('git-base'):
        files=_lint_git_files(p,d,files_all)
    else:
        n=int(p.get('latest') or 0)
        files=files_all[-n:] if n < len(files_all) else list(files_all)
    fmtval=effective_format(p)
    if not files_all:
        # No output regardless format? If format set, still render an empty summary (reference printed LOG literal in earlier test)
        if fmtval:
            summary=_lint_summary_struct(p,d,files_all,files,[],None,None)
            sys.stdout.write(execute_template(fmtval,summary,{'json':lambda *a: go_json_encode(a[0]) if a else ''}))
        return 0
    from state import Dev
    from sqliteinspect import inspect_sqlite_conn
    dev=Dev(p.get('dev-url'))
    start_ns=time.monotonic_ns(); start_time=GoTime()
    con=dev.reset()
    # replay files before analyzed ones
    analyzed_start_index=len(files_all)-len(files)
    base_files=files_all[:analyzed_start_index]
    for f in base_files:
        for stmt in migdir.file_statements(f,d.fmt,generic=False):
            try: con.execute(stmt)
            except sqlite3.Error as e:
                # Error during replay of base files - treat as execution error for that file? Reference behavior: report error in header. Simplified via lint exec error path with files=[f]
                pass
    from_realm=inspect_sqlite_conn(con)
