def _lint_git_files(p,d,files_all):
    # Determine changed migration files between git-base and HEAD/worktree in git-dir
    gitdir=p.get('git-dir') or '.'
    base=p.get('git-base')
    try:
        r=subprocess.run(['git','-C',gitdir,'diff','--name-only',base,'--'],capture_output=True,text=True)
        changed=set(r.stdout.splitlines())
        # also untracked?
        r2=subprocess.run(['git','-C',gitdir,'ls-files','--others','--exclude-standard'],capture_output=True,text=True)
        changed.update(r2.stdout.splitlines())
    except Exception:
        changed=set()
    # Map repo-relative paths to dir files: path relative to gitdir + d.path
    dir_abs=os.path.abspath(d.path); git_abs=os.path.abspath(gitdir)
    out=[]
    for f in files_all:
        rel=os.path.relpath(os.path.abspath(f.path),git_abs)
        if rel in changed: out.append(f)
    return out

def _diag(text,code,fix=None,pos=0):
    d={'Pos':pos,'Text':text}
    if code: d['Code']=code
    if fix: d['SuggestedFixes']=[{'Message':fix}]
    return d

def _analyze_changes(before,after,diffs,stmt_idx,f):
    reports_by_kind={}
    def add(kind,diag):
        reports_by_kind.setdefault(kind,[]).append(diag)
    for ch in diffs:
        if ch.kind=='DropTable':
            add('destructive changes detected',_diag(f'Dropping table "{ch.table.name}"','DS102',f'Add a pre-migration check to ensure table "{ch.table.name}" is empty before dropping it'))
        elif ch.kind=='ModifyTable':
            for s in ch.changes:
                if s[0]=='DropColumn':
                    col=s[1]
                    if col.generated is None or col.generated.type!='VIRTUAL':
                        add('destructive changes detected',_diag(f'Dropping non-virtual column "{col.name}"','DS103',f'Add a pre-migration check to ensure column "{col.name}" is NULL before dropping it'))
                elif s[0]=='AddColumn':
                    col=s[1]
                    if not col.null and col.default is None and col.generated is None:
                        from model import sql_type_name
                        add('data dependent changes detected',_diag(f'Adding a non-nullable "{sql_type_name(col.raw_type)}" column "{col.name}" will fail in case table "{ch.to_table.name}" is not empty','MF103'))
                elif s[0]=='AddIndex':
                    idx=s[1]
                    if idx.unique and idx.parts and idx.parts[0].column:
                        add('data dependent changes detected',_diag(f'Adding a unique index "{idx.name}" on table "{ch.to_table.name}" might fail in case column "{idx.parts[0].column}" contains duplicate entries','MF101'))
        elif ch.kind=='AddTable':
            pass
    reports=[]
    order=['destructive changes detected','data dependent changes detected']
    for k in order:
        if k in reports_by_kind:
            reports.append({'text':k,'diagnostics':reports_by_kind[k]})
    return reports

def _render_lint_log(files_all,files,file_reports,total_elapsed,total_changes,total_diags,v_ok,v_warn,v_err,exec_error):
    from gotmpl import format_go_duration
    out=[]
    if not files:
        return ''
    first=files[0]; last=files[-1]
    # from version: version of file before first analyzed, if any
    analyzed_start=len(files_all)-len(files)
    if analyzed_start>0:
        from_v=files_all[analyzed_start-1].version
        out.append(f"Analyzing changes from version {from_v} to {last.version} ({len(files)} migration{'s' if len(files)!=1 else ''} in total):\n\n")
    else:
        out.append(f"Analyzing changes until version {last.version} ({len(files)} migrations in total):\n\n")
    if exec_error:
        f,stmt,msg=exec_error
        out.append(f"  Error: executing statement: {stmt}: {msg}\n\n")
        out.append("  -------------------------\n")
        out.append(f"  -- {format_go_duration(total_elapsed)}\n")
        out.append("  -- 1 version with errors\n")
        return ''.join(out)
    for rep in file_reports:
        f=rep['file']
        out.append(f"  -- analyzing version {f.version}\n")
        if not rep['reports']:
            out.append("    -- no diagnostics found\n")
        else:
            for r in rep['reports']:
                out.append(f"    -- {r['text']}:\n")
                fixes=[]
                for diag in r['diagnostics']:
                    line=diag.get('_line','L1')
                    code=diag.get('Code','')
                    # wrap at ~92 chars like reference for MF texts (handled by simple wrap for long ones)
                    txt=f"      -- L1: {diag['Text']}"
                    if code:
                        txt+=f" https://atlasgo.io/lint/analyzers#{code}"
                    out.append(_wrap_lint_line(txt)+"\n")
                    for fix in diag.get('SuggestedFixes',[]): fixes.append(fix['Message'])
                if fixes:
                    out.append("    -- suggested fix:\n")
                    for fx in fixes:
                        out.append(f"      -> {fx}\n")
        out.append(f"  -- ok ({format_go_duration(rep['elapsed'])})\n\n")
    out.append("  -------------------------\n")
    out.append(f"  -- {format_go_duration(total_elapsed)}\n")
    # versions line
    parts=[]
    if v_ok: parts.append(f"{v_ok} version{'s' if v_ok!=1 else ''} ok")
    if v_warn: parts.append(f"{v_warn} version{'s' if v_warn!=1 else ''} with warnings")
    if v_err: parts.append(f"{v_err} version{'s' if v_err!=1 else ''} with errors")
    # Special cases from reference: all ok => "N version(s) ok", single warn => "1 version with warnings", single err => "1 version with errors", mixed ok+err => "1 version ok, 1 with errors"
    if v_ok and v_err and not v_warn:
        parts=[f"{v_ok} version{'s' if v_ok!=1 else ''} ok", f"{v_err} with errors"]
    out.append("  -- "+', '.join(parts)+"\n")
    if total_changes:
        out.append(f"  -- {total_changes} schema change{'s' if total_changes!=1 else ''}\n")
    if total_diags:
        out.append(f"  -- {total_diags} diagnostic{'s' if total_diags!=1 else ''}\n")
    return ''.join(out)

def _wrap_lint_line(txt):
    # Reference wraps long diagnostic lines: continuation indented 9 spaces before URL in examples.
    if len(txt)<=95:
        return txt
    # break before last words to keep <= ~95 first line, continuation 9 spaces
    words=txt.split(' ')
    line=''; out=[]
    for w in words:
        if line and len(line)+1+len(w)>92:
            out.append(line); line='         '+w
        else:
            line=(line+' '+w) if line else w
    if line: out.append(line)
    return '\n'.join(out)

def _lint_summary_struct(p,d,files_all,files,file_reports,from_realm,desired_realm,start_time=None):
    from gotmpl import GoStruct
    from schemamarshal import marshal_hcl
    u=parse_client_url(p.get('dev-url') or '')
    env=reportmod.env_struct(u.driver or 'sqlite',u,d.path)
    # Env in lint JSON: Dir is "migrations" (path) not url
    current_hcl=marshal_hcl(from_realm) if from_realm is not None else ''
    desired_hcl=marshal_hcl(desired_realm) if desired_realm is not None else ''
    analyzed_start=len(files_all)-len(files) if files_all else 0
    from_v=files_all[analyzed_start-1].version if analyzed_start>0 else ''
    to_v=files[-1].version if files else ''
    steps=[]
    def step(name,text,result=None):
        jo={'Name':name,'Text':text}
        if result is not None: jo['Result']=result
        s=GoStruct('*migratelint.StepReport',fields={'Name':name,'Text':text,'Result':result})
        s.json_obj=jo; return s
    steps.append(step('Migration Integrity Check','File atlas.sum is valid'))
    steps.append(step('Detect New Migration Files',f"Found {len(files)} new migration files (from {len(files_all)} total)"))
    nchanges=sum(r.get('changes',0) for r in file_reports)
    steps.append(step('Replay Migration Files',f"Loaded {nchanges} changes on dev database"))
    file_structs=[]
    for rep in file_reports:
        f=rep['file']
        reports=[]
        for r in rep['reports']:
            diags=[]
            for diag in r['diagnostics']:
                dj={'Pos':diag.get('Pos',0),'Text':diag['Text']}
                if diag.get('Code'): dj['Code']=diag['Code']
                if diag.get('SuggestedFixes'): dj['SuggestedFixes']=diag['SuggestedFixes']
                diags.append(dj)
            reports.append({'Text':r['text'],'Diagnostics':diags})
        jo={'Name':f.name,'Text':migdir.file_content_text(f)}
        if reports: jo['Reports']=reports
        if rep['reports']:
            # Error field is first report text if destructive etc - reference sets Error to report text for errors/warnings? For warnings maybe empty; set for any report
            jo['Error']=rep['reports'][0]['text']
        fs=GoStruct('*migratelint.FileReport',fields={'Name':f.name,'Text':migdir.file_content_text(f),'Reports':reports,'Error':jo.get('Error','')})
        fs.json_obj=jo; file_structs.append(fs)
        nrep=len(reports)
        steps.append(step(f'Analyze {f.name}',f"{nrep} reports were found in analysis" if nrep else 'No reports were found in analysis', result=fs))
    schema_s=GoStruct('struct',fields={'Current':current_hcl,'Desired':desired_hcl})
    fields={'URL':'','Env':env,'Schema':schema_s,'Steps':steps,'Files':file_structs,'Start':start_time or GoTime(),'End':GoTime(),'FromV':from_v,'ToV':to_v,'TotalFiles':len(files),'Warning':None}
    s=GoStruct('*migratelint.SummaryReport',fields=fields)
    jo={'Env':{'Driver':u.driver or 'sqlite','URL':u,'Dir':d.path},'Schema':{'Current':current_hcl,'Desired':desired_hcl},'Steps':[st.json_obj for st in steps],'Files':[fs.json_obj for fs in file_structs]}
    s.json_obj=jo
    return s

