    s=re.sub(r'\((\d+\.?\d*(?:ns|µs|ms|s))\)', '(<dur>)', s)
    s=re.sub(r'-- \d+\.?\d*(?:ns|µs|ms|s)\n', '-- <dur>\n', s)
