                p=os.path.join(w,k); os.makedirs(os.path.dirname(p),exist_ok=True); open(p,'w').write(v)
        if step.get('remove'):
            for k in step['remove']:
                try: os.remove(os.path.join(w,k))
                except: pass
        if step.get('rehash'):
            subprocess.run([bin,'migrate','hash']+step.get('rehash',[]),cwd=w,env=ENV,capture_output=True)
        if 'args' in step:
            r=subprocess.run([bin]+step['args'],capture_output=True,text=True,cwd=w,env=ENV,input=step.get('input'))
            outs.append((r.returncode,norm(r.stdout),norm(r.stderr)))
    # final files & dbs
    files={}
    for root,dirs,fn in os.walk(w):
        dirs.sort()
