# __complete support (approximation of cobra)
COBRA_REQUIRED={
 ('schema','inspect'):{'url'},('schema','clean'):{'url'},('schema','diff'):{'from','to'},('migrate','diff'):{'to','dev-url'},('migrate','lint'):{'dev-url'},
}
def handle_complete(nodesc,args):
    if not args:
        sys.stdout.write(':0\n'); sys.stderr.write('Completion ended with directive: ShellCompDirectiveDefault\n'); return 0
    to_complete=args[-1]; prior=args[:-1]
    result=complete_words(prior,to_complete)
    if result[0]=='__unable':
        sys.stdout.write(':0\n')
        sys.stderr.write(f"[Debug] [Error] Unable to find a command for arguments: [{' '.join(prior)}]\n")
        sys.stderr.write("Completion ended with directive: ShellCompDirectiveDefault\n")
        return 0
    comps,directive=result
    for c,desc in comps:
        if nodesc or not desc: sys.stdout.write(c+'\n')
        else: sys.stdout.write(f"{c}\t{desc}\n")
    sys.stdout.write(f":{directive}\n")
    names={0:'ShellCompDirectiveDefault',4:'ShellCompDirectiveNoFileComp'}
    sys.stderr.write(f"Completion ended with directive: {names.get(directive,'ShellCompDirectiveDefault')}\n")
    return 0

DESCS={
 'completion':'Generate the autocompletion script for the specified shell','help':'Help about any command','license':'Display license information','migrate':'Manage versioned migration files','schema':'Work with atlas schemas.','version':'Prints this Atlas CLI version information.',
}

def _completion_path(prior):
    """Parse prior words into (path, remaining words, set_flags). None if unable root."""
    # find root command: iterate words skipping root flags (only help bool)
    i=0; path=[]
    # root level
    while i<len(prior):
        w=prior[i]
        if w.startswith('-'):
            i+=1; continue
        if w not in ROOT_COMMANDS:
            return None
        path.append(w); i+=1; break
    if not path:
        return ([], prior, set())
    if path[0] in GROUPS:
        # scan for subcommand skipping persistent flag values via generic spec scan below in set detection; simple: find first nonflag that is in subs
        j=i
        while j<len(prior):
            w=prior[j]
            if w.startswith('-'):
                # crude skip flag value if flag name is a known value flag in any spec and no =
                j+=1; continue
            if w in GROUPS[path[0]]:
                path.append(w)
            break
    return (path, prior, None)

def _specs_for_path(path):
    if tuple(path) in COMMANDS: return COMMANDS[tuple(path)]
    if tuple(path) in LEAF_SPECS: return LEAF_SPECS[tuple(path)]
    if len(path)==1 and path[0] in GROUP_SPECS: return GROUP_SPECS[path[0]]
    return [F('help','h','bool')]

def _set_flags(prior,path):
    sp=_specs_for_path(path)
    by_long={f.name:f for f in sp}; by_short={f.short:f for f in sp if f.short}
    is_set=set()
    i=0
    # start scanning after command words: simply scan all; command names won't match flags
    while i<len(prior):
        w=prior[i]
        if w.startswith('--'):
            name=w[2:].split('=',1)[0]
            f=by_long.get(name)
            if f:
                is_set.add(name)
                if f.typ!='bool' and '=' not in w: i+=1
            i+=1; continue
        if w.startswith('-') and w!='-' and len(w)>1:
            # cluster
            body=w[1:]; consumed=False
            for ch in body:
                f=by_short.get(ch)
                if f:
                    is_set.add(f.name)
                    if f.typ!='bool': consumed=True; break
            if consumed and '=' not in w and len(body)==1: i+=1
            i+=1; continue
        i+=1
    return is_set

def _ordered_specs_for_completion(sp):
    # persistent first (config, env, var), then locals in definition order, help last
    pers=[]; local=[]; helpf=[]
    for f in sp:
        if f.name in ('config','env','var'): pers.append(f)
        elif f.name=='help': helpf.append(f)
        else: local.append(f)
    # sort pers by desired order
    order={'config':0,'env':1,'var':2}
    pers.sort(key=lambda f:order.get(f.name,9))
    return pers+local+helpf

def complete_words(prior,to_complete):
    parsed=_completion_path(prior)
    if parsed is None:
        return ('__unable',)
    path,_,_=parsed
    sp=_specs_for_path(path)
    by_long={f.name:f for f in sp}
    is_set=_set_flags(prior,path)
    # If prior word is a non-bool flag needing a value, completing its value -> default
    if prior:
        last=prior[-1]
        if last.startswith('--') and '=' not in last:
            f=by_long.get(last[2:])
            if f and f.typ!='bool': return ([],0)
        if re.fullmatch(r'-[A-Za-z]',last):
            f=next((x for x in sp if x.short==last[1]),None)
            if f and f.typ!='bool': return ([],0)
    # help command topic completion
    if path==['help'] and not to_complete.startswith('-'):
        return ([(c,DESCS.get(c,'')) for c in ROOT_COMMANDS if c.startswith(to_complete)],4)
    if to_complete.startswith('-') and to_complete!='-':
        # exact flag name requiring value -> value completion default
        if to_complete.startswith('--'):
            nm=to_complete[2:].split('=',1)[0]
            if nm in by_long and by_long[nm].typ!='bool' and ('=' in to_complete or to_complete=='--'+nm):
                return ([],0)
        elif re.fullmatch(r'-[A-Za-z]',to_complete):
            f=next((x for x in sp if x.short==to_complete[1]),None)
            if f and f.typ!='bool': return ([],0)
        required=COBRA_REQUIRED.get(tuple(path),set())
        missing_required=[r for r in required if r not in is_set]
        cand_specs=[]
        for f in _ordered_specs_for_completion(sp):
            if f.hidden: continue
            if missing_required and f.name not in missing_required: continue
            if f.name in is_set and f.typ not in ('strings','var'): continue
            cand_specs.append(f)
        out=[]
        long_only=to_complete.startswith('--')
        for f in cand_specs:
            cand=f"--{f.name}"
            if cand.startswith(to_complete): out.append((cand,flag_description(tuple(path),f)))
            if not long_only and f.short:
                cand2=f"-{f.short}"
                if cand2.startswith(to_complete): out.append((cand2,flag_description(tuple(path),f)))
        return (out,4)
    # positional
    if len(path)==0:
        return ([(c,DESCS.get(c,'')) for c in ROOT_COMMANDS if c.startswith(to_complete)],4)
    if len(path)==1 and path[0] in GROUPS:
        # check if an unknown subcommand word was already in prior (path len 1 but a nonflag in prior after group not matching)
        descs=group_descs(path[0])
        return ([(c,descs.get(c,'')) for c in GROUPS[path[0]] if c.startswith(to_complete)],4)
    # leaf
    if path and path[0]=='completion':
        return ([],4)
    required=COBRA_REQUIRED.get(tuple(path),set())
    missing=[r for r in required if r not in is_set]
    if missing:
        out=[]
        # order by flag definition order in local specs
        for f in sp:
            if f.name in missing:
                out.append((f"--{f.name}",flag_description(tuple(path),f)))
                if f.short: out.append((f"-{f.short}",flag_description(tuple(path),f)))
        # filter by prefix if to_complete nonempty
        out=[o for o in out if o[0].startswith(to_complete)] if to_complete else out
        return (out,0)
    return ([],0)

def group_descs(grp):
    out={}; in_av=False
    for line in HELP[grp].splitlines():
        if line.startswith('Available Commands:'): in_av=True; continue
        if in_av:
            if not line.strip(): break
            m=re.match(r'\s+(\S+)\s+(.*)',line)
            if m: out[m.group(1)]=m.group(2).strip()
    return out

def flag_description(path,flag):
    if flag.name=='help':
        cmd=path[-1] if path else 'atlas'
        return f'help for {cmd}'
    key=help_key(path) if path else 'root'
    text=HELP.get(key,'')
    # search lines containing --name
    for line in text.splitlines():
        if f"--{flag.name}" not in line: continue
        # pattern with optional shorthand and value token depending on type
        if flag.typ=='bool':
            m=re.match(r'^\s+(?:-\w,\s+)?--'+re.escape(flag.name)+r'\s{2,}(.+)$',line)
        else:
            m=re.match(r'^\s+(?:-\w,\s+)?--'+re.escape(flag.name)+r'\s+\S+\s{2,}(.+)$',line)
            if not m:
                m=re.match(r'^\s+(?:-\w,\s+)?--'+re.escape(flag.name)+r'\s+\S+\s+(.+)$',line)
        if m:
            desc=m.group(1).strip()
            desc=re.sub(r'\s+\(default [^)]*\)$','',desc)
            return desc
    return ''
