        'trimsuffix': lambda s,p: _str(s)[:-len(_str(p,1))] if _str(p,1) and _str(s).endswith(_str(p,1)) else _str(s),
        'replace': lambda s, a, b: _str(s).replace(_str(a,1), _str(b,2)),
        'keys': lambda d: list(d.keys()),
