        'strrev': lambda s: _str(s)[::-1],
        'substr': lambda s, off, ln: _str(s)[int(off):int(off)+int(ln)] if int(ln) >= 0 else _str(s)[int(off):],
        'title': lambda s: _str(s).title(),
