        'sort': lambda lst: sorted(lst),
        'zipmap': lambda ks,vs: dict(zip(ks,vs)),
        'jsonencode': lambda v: _json.dumps(v, separators=(',',':'), ensure_ascii=False, sort_keys=isinstance(v,dict)),
        'jsondecode': lambda s: _json.loads(_str(s)),
        'csvdecode': lambda s: __import__('csv').list if False else _csvdecode(s),
        'tobool': lambda v: (v if isinstance(v,bool) else (_str(v).lower()=='true' if isinstance(v,str) else bool(v))),
